  private struct RectTransformSnapshot
  {
    public Vector2 AnchorMin;
    public Vector2 AnchorMax;
    public Vector2 Pivot;
    public Vector2 AnchoredPosition;
    public Vector2 SizeDelta;
    public Vector3 LocalScale;
    public Quaternion LocalRotation;
    public Vector2 OffsetMin;
    public Vector2 OffsetMax;

    public static RectTransformSnapshot Capture(RectTransform rect)
    {
      return new RectTransformSnapshot
      {
        AnchorMin = rect.anchorMin,
        AnchorMax = rect.anchorMax,
        Pivot = rect.pivot,
        AnchoredPosition = rect.anchoredPosition,
        SizeDelta = rect.sizeDelta,
        LocalScale = rect.localScale,
        LocalRotation = rect.localRotation,
        OffsetMin = rect.offsetMin,
        OffsetMax = rect.offsetMax
      };
    }

    public void Apply(RectTransform rect)
    {
      rect.localRotation = LocalRotation;
      rect.localScale = LocalScale;
      rect.anchorMin = AnchorMin;
      rect.anchorMax = AnchorMax;
      rect.pivot = Pivot;
      rect.anchoredPosition = AnchoredPosition;
      rect.sizeDelta = SizeDelta;
      // Stretch layouts need offsets restored after sizeDelta.
      if (AnchorMin != AnchorMax)
      {
        rect.offsetMin = OffsetMin;
        rect.offsetMax = OffsetMax;
      }
    }
  }

  [MenuItem("Tools/ViewEdit &v")]
  public static void Open()
  {
    EditorWindow inspector = FindInspectorWindow();
    OpenCoveringInspector(inspector != null ? inspector.position : default);
  }

  /// <summary>
  /// Open ViewEdit over the Inspector, only as wide as the widest row.
  /// GetWindow restores the last saved rect, which is the full 1920x1080
  /// display, so the content width is applied again after Unity shows it.
  /// </summary>
  private static void OpenCoveringInspector(Rect inspectorRect)
  {
    if (inspectorRect.width < 1f || inspectorRect.height < 1f)
    {
      EditorWindow inspector = FindInspectorWindow();
      if (inspector != null)
        inspectorRect = inspector.position;
    }

    if (inspectorRect.width < 1f || inspectorRect.height < 1f)
      inspectorRect = new Rect(80f, 80f, 420f, 640f);

    ViewportLayoutEditor window =
        GetWindow<ViewportLayoutEditor>("ViewEdit");
    window.fitWidthToContent = true;
    window.fittedContentRight = 0f;
    Rect contentRect = ContentRectOverInspector(window, inspectorRect);
    CoverInspector(window, contentRect);

    Rect capturedInspector = inspectorRect;
    EditorApplication.delayCall += () =>
    {
      if (window == null)
        return;

      Rect again = ContentRectOverInspector(window, capturedInspector);
      CoverInspector(window, again);
      EditorApplication.delayCall += () =>
      {
        if (window == null)
          return;

        CoverInspector(window, ContentRectOverInspector(window, capturedInspector));
      };
    };
  }

  /// <summary>
  /// Keep the Inspector's vertical span. Horizontally, fit the widest
  /// ViewEdit row and right-align to the Inspector so the game view is not
  /// resized to 1920.
  /// </summary>
  private static Rect ContentRectOverInspector(
      ViewportLayoutEditor window,
      Rect inspectorRect)
  {
    float width = window != null
        ? window.MeasureViewEditContentWidth()
        : 560f;
    float x = inspectorRect.xMax - width;
    if (x < 0f)
      x = inspectorRect.x;

    // ViewEdit always spans the full monitor height: top Y = 0 and the
    // bottom edge at the monitor maximum. Keep only the fitted content width.
    return new Rect(x, 0f, width, GetViewEditMonitorHeight());
  }

  /// <summary>
  /// Return the real desktop-monitor height used by a floating Unity editor
  /// window. Screen.currentResolution is intentionally not used here: inside
  /// the editor it can describe the Game display / a scaled resolution and can
  /// therefore leave ViewEdit short of the physical monitor bottom.
  /// </summary>
  private static float GetViewEditMonitorHeight()
  {
#if UNITY_EDITOR_WIN
    // Unity editor windows use desktop screen coordinates on Windows. Query the
    // monitor containing the centre of ViewEdit and use the monitor rectangle,
    // not the work area, so Y=0 + height reaches the true bottom of the screen.
    ViewportLayoutEditor existing = FindOpenViewEditWindow();

    Rect r = existing != null ? existing.position : new Rect(0f, 0f, 1f, 1f);
    POINT pt = new POINT
    {
      x = Mathf.RoundToInt(r.x + Mathf.Max(1f, r.width) * 0.5f),
      y = Mathf.RoundToInt(r.y + Mathf.Max(1f, r.height) * 0.5f)
    };

    System.IntPtr monitor = MonitorFromPoint(pt, MONITOR_DEFAULTTONEAREST);
    if (monitor != System.IntPtr.Zero)
    {
      MONITORINFO info = new MONITORINFO();
      info.cbSize = Marshal.SizeOf(typeof(MONITORINFO));
      if (GetMonitorInfo(monitor, ref info))
      {
        int monitorHeight = info.rcMonitor.bottom - info.rcMonitor.top;
        if (monitorHeight > 0)
          return monitorHeight;
      }
    }

    int systemHeight = GetSystemMetrics(SM_CYSCREEN);
    if (systemHeight > 0)
      return systemHeight;
#endif

    if (Screen.currentResolution.height > 0)
      return Screen.currentResolution.height;

    ViewportLayoutEditor fallback = FindOpenViewEditWindow();
    if (fallback != null && fallback.position.height > 1f)
      return fallback.position.height;

    return 1080f;
  }

#if UNITY_EDITOR_WIN
  private const uint MONITOR_DEFAULTTONEAREST = 2;
  private const int SM_CYSCREEN = 1;

  [StructLayout(LayoutKind.Sequential)]
  private struct POINT
  {
    public int x;
    public int y;
  }

  [StructLayout(LayoutKind.Sequential)]
  private struct RECT
  {
    public int left;
    public int top;
    public int right;
    public int bottom;
  }

  [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Auto)]
  private struct MONITORINFO
  {
    public int cbSize;
    public RECT rcMonitor;
    public RECT rcWork;
    public uint dwFlags;
  }

  [DllImport("user32.dll")]
  private static extern System.IntPtr MonitorFromPoint(
      POINT pt, uint dwFlags);

  [DllImport("user32.dll", CharSet = CharSet.Auto)]
  [return: MarshalAs(UnmanagedType.Bool)]
  private static extern bool GetMonitorInfo(
      System.IntPtr hMonitor, ref MONITORINFO lpmi);

  [DllImport("user32.dll")]
  private static extern int GetSystemMetrics(int nIndex);
#endif

  /// <summary>
  /// Width of the widest fixed ViewEdit row, including the minimap and the
  /// help-box padding around a piece card. Rows use fixed control widths, so
  /// this is the window width that shows every control without a horizontal
  /// scrollbar.
  /// </summary>
  private float MeasureViewEditContentWidth()
  {
    float enabledWidth =
        EditorStyles.label.CalcSize(new GUIContent("Set")).x + 18f;
    float mirrorWidth =
        EditorStyles.label.CalcSize(new GUIContent("Mirror")).x + 18f;

    // Black Door frame header: 180 name + 135 graphic + Enabled + Mirror.
    float frameHeader =
        180f + 135f + enabledWidth + 10f + mirrorWidth + 10f;

    // FrontF1 row: Width popup + X stepper + Y stepper + Ref.
    const float StepperWidth = 12f + 36f + 36f + 36f;
    float frontF1Row =
        38f + 52f + 4f + StepperWidth + StepperWidth + 10f + 125f;

    // Second Snap toolbar: All Walls, algorithm toggle, L1–L6.
    float toolbarRow = 90f + 8f + 140f + 8f + 174f;

    float featureRow = 48f + 48f + 210f + enabledWidth;

    float mapWidth = 0f;
    if (previewMiniMap != null && !previewMiniMapMuted)
      mapWidth = 18f + previewMiniMap.Width * 14f;

    float content = Mathf.Max(
        frameHeader,
        frontF1Row,
        toolbarRow,
        featureRow,
        mapWidth);

    RectOffset helpPad = EditorStyles.helpBox.padding;
    RectOffset helpMargin = EditorStyles.helpBox.margin;
    // Help-box chrome, gaps between fixed-width controls, and the vertical
    // scrollbar that appears once the piece list is taller than the window.
    float chrome = helpPad.left + helpPad.right
        + helpMargin.left + helpMargin.right
        + 40f
        + 16f;
    return content + chrome - 50f;
  }

  private void NoteContentRight()
  {
    if (Event.current == null)
      return;

    NoteContentRight(GUILayoutUtility.GetLastRect());
  }

  /// <summary>
  /// Record the right edge of a fixed-width control. Expanded groups report
  /// the whole window, which is the empty area that should not set the width.
  /// </summary>
  private void NoteContentRight(Rect rect)
  {
    if (!fitWidthToContent
        || Event.current == null
        || Event.current.type != EventType.Repaint)
    {
      return;
    }

    if (rect.width < 1f || rect.xMax < 1f)
      return;

    if (rect.xMax >= position.width - 4f && rect.width > position.width * 0.85f)
      return;

    if (rect.xMax > fittedContentRight)
      fittedContentRight = rect.xMax;
  }

  private void FinishContentWidthFit()
  {
    if (!fitWidthToContent
        || Event.current == null
        || Event.current.type != EventType.Repaint
        || fittedContentRight < 100f)
    {
      return;
    }

    fitWidthToContent = false;
    float contentRight = fittedContentRight;
    EditorApplication.delayCall += () => ApplyFittedContentWidth(contentRight);
  }

  private void ApplyFittedContentWidth(float contentRight)
  {
    if (this == null)
      return;

    float pad = EditorStyles.helpBox.padding.right
        + EditorStyles.helpBox.margin.right
        + 8f;
    float width = Mathf.Ceil(contentRight + pad) - 50f;
    Rect current = position;
    if (width < 1f || Mathf.Abs(current.width - width) < 2f)
      return;

    if (maximized)
      maximized = false;

    if (minSize.x > width)
      minSize = new Vector2(width, Mathf.Min(minSize.y, current.height));

    position = new Rect(current.x, current.y, width, current.height);
  }

  private static void CoverInspector(EditorWindow window, Rect inspectorRect)
  {
    if (window == null || inspectorRect.width < 1f || inspectorRect.height < 1f)
      return;

    UndockIfShared(window);

    if (window.maximized)
      window.maximized = false;

    Vector2 min = window.minSize;
    if (min.x > inspectorRect.width || min.y > inspectorRect.height)
    {
      window.minSize = new Vector2(
          Mathf.Min(min.x, inspectorRect.width),
          Mathf.Min(min.y, inspectorRect.height));
    }

    window.position = inspectorRect;
    window.Focus();
  }

  /// <summary>
  /// A pane shared with other tabs must be pulled out before its rect is set,
  /// otherwise the position write resizes that whole dock.
  /// </summary>
  private static void UndockIfShared(EditorWindow window)
  {
    object parent = GetEditorWindowParent(window);
    if (parent == null)
      return;

    BindingFlags flags =
        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
    FieldInfo panesField = parent.GetType().GetField("m_Panes", flags);
    System.Collections.IList panes = panesField != null
        ? panesField.GetValue(parent) as System.Collections.IList
        : null;
    if (panes == null || panes.Count <= 1)
      return;

    MethodInfo removeTab = parent.GetType().GetMethod(
        "RemoveTab",
        flags,
        null,
        new System.Type[] { typeof(EditorWindow), typeof(bool) },
        null);
    if (removeTab == null)
      return;

    removeTab.Invoke(parent, new object[] { window, true });
    window.Show();
  }

  private static object GetEditorWindowParent(EditorWindow window)
  {
    if (window == null)
      return null;

    FieldInfo parentField = typeof(EditorWindow).GetField(
        "m_Parent",
        BindingFlags.Instance | BindingFlags.NonPublic);
    if (parentField == null)
      return null;

    return parentField.GetValue(window);
  }

  private static EditorWindow FindInspectorWindow()
  {
    if (IsInspectorWindow(mouseOverWindow))
      return mouseOverWindow;

    EditorWindow[] windows = Resources.FindObjectsOfTypeAll<EditorWindow>();
    EditorWindow fallback = null;
    for (int i = 0; i < windows.Length; ++i)
    {
      EditorWindow candidate = windows[i];
      if (!IsInspectorWindow(candidate))
        continue;

      if (candidate.hasFocus)
        return candidate;

      if (fallback == null)
        fallback = candidate;
    }

    return fallback;
  }

  private static bool IsInspectorWindow(EditorWindow window)
  {
    return window != null
        && window.GetType().FullName == "UnityEditor.InspectorWindow";
  }

  [InitializeOnLoadMethod]
  private static void RegisterInspectorRightClickOpen()
  {
    EditorApplication.CallbackFunction handler = HandleInspectorRightClickOpen;
    RemoveViewEditGlobalEventHandler(handler);
    AddViewEditGlobalEventHandler(handler);

    // When ViewEdit and Dungeon Features are both open, a right-click anywhere
    // inside the Dungeon Features editor closes Dungeon Features.  Keep this
    // in ViewportLayoutEditor.cs so no DungeonFeatureEditor source change is
    // required.
    EditorApplication.CallbackFunction closeDungeonFeaturesHandler =
        HandleDungeonFeaturesRightClickClose;
    RemoveViewEditGlobalEventHandler(closeDungeonFeaturesHandler);
    AddViewEditGlobalEventHandler(closeDungeonFeaturesHandler);
  }

  private static void HandleDungeonFeaturesRightClickClose()
  {
    TryCloseDungeonFeaturesUnderMouse();
  }

  /// <summary>
  /// Close Dungeon Features when a right-click's screen position lies inside
  /// that window's screen rectangle. The event may be delivered to ViewEdit
  /// when ViewEdit overlaps Dungeon Features, so the test uses screen space
  /// rather than which pane received the event.
  /// </summary>
  private static bool TryCloseDungeonFeaturesUnderMouse()
  {
    if (!HasOpenInstances<ViewportLayoutEditor>())
      return false;

    Event current = Event.current;
    if (current == null)
      return false;

    // Unity can turn the RMB event into ContextClick before a later handler
    // sees it. rawType keeps the original mouse event. ContextClick does not
    // always report button 1.
    bool rightClick =
        ((current.type == EventType.MouseDown
            || current.rawType == EventType.MouseDown)
            && current.button == 1)
        || current.type == EventType.ContextClick
        || current.rawType == EventType.ContextClick;
    if (!rightClick)
      return false;

    Vector2 screenMouse = GUIUtility.GUIToScreenPoint(current.mousePosition);

    EditorWindow dungeonFeatures = null;
    EditorWindow[] windows = Resources.FindObjectsOfTypeAll<EditorWindow>();
    for (int i = 0; i < windows.Length; ++i)
    {
      EditorWindow candidate = windows[i];
      if (!IsDungeonFeaturesWindow(candidate))
        continue;

      if (candidate.position.Contains(screenMouse))
      {
        dungeonFeatures = candidate;
        break;
      }
    }

    if (dungeonFeatures == null)
      return false;

    current.Use();
    EditorWindow windowToClose = dungeonFeatures;
    EditorApplication.delayCall += () =>
    {
      if (windowToClose != null)
        windowToClose.Close();
    };
    return true;
  }

  private static bool IsDungeonFeaturesWindow(EditorWindow window)
  {
    if (window == null)
      return false;

    string typeName = window.GetType().Name;
    string title = window.titleContent != null
        ? window.titleContent.text
        : string.Empty;

    return string.Equals(typeName, "DungeonFeatureEditor",
               System.StringComparison.Ordinal)
        || typeName.IndexOf("DungeonFeature",
               System.StringComparison.OrdinalIgnoreCase) >= 0
        || string.Equals(title, "Dungeon Features",
               System.StringComparison.Ordinal);
  }

  private static void HandleInspectorRightClickOpen()
  {
    Event current = Event.current;
    if (current == null
        || current.type != EventType.MouseDown
        || current.button != 1)
    {
      return;
    }

    EditorWindow hovered = mouseOverWindow;
    if (!IsInspectorWindow(hovered))
      return;

    current.Use();
    OpenCoveringInspector(hovered.position);
  }

  private void ReapplyCurrentPoseToWallRendererAfterReload()
  {
    if (this == null || Application.isPlaying)
      return;

    // A script/domain reload must return the current saved X/Y/Facing to the
    // automatic wall renderer, never to a temporary Hide Walls / manual test.
    previewEnabledOverrideByPiece.Clear();
    previewMirrorOverrideByPiece.Clear();
    previewPositionOverrideByPiece.Clear();
    previewFrontF1WidthOverrideByPiece.Clear();
    previewFrontF3WidthOverrideByPiece.Clear();
    previewGraphicOverrideByPiece.Clear();
    previewDisableAllWalls = false;
    dynamicGeometrySignatureInitialized = false;

    showOnlyWallsNeededForCurrentPose = true;
    showWallsActivFilter = true;

    ReloadLayoutFromDisk();
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap != null)
      previewMiniMap.SetPlayerPose(previewX, previewY, previewFacing);

    CaptureNormalWallBaselinesFromLayout();
    ApplyCurrentPoseVisibilityToLayout();

    ResetEditModeViewportLogCache();
    DestroyEditModePreviewTextureOnly();
    RefreshEditModePreview();
    RepaintGameViews();
    Repaint();
  }

  private void OnEnable()
  {
    titleContent = new GUIContent("ViewEdit");
    wantsMouseMove = true;

    RestorePersistedAssets();
    ReloadLayoutFromDisk();
    RestoreSessionPrefs();
    showOnlyWallsNeededForCurrentPose = true;
    showWallsActivFilter = true;
    StripObsoleteFrontWallF1ABPieces();
    EnsureLeftS3AndRightS3Pieces();
    CaptureNormalWallBaselinesFromLayout();
    ApplyCurrentPoseVisibilityToLayout();
    EditorApplication.playModeStateChanged += HandlePlayModeStateChanged;
    // Force a fresh compose from the current pose's Enabled flags.
    DestroyEditModePreviewTextureOnly();
    RefreshEditModePreview();

    // Domain reload can invoke OnEnable before the editor hierarchy/assets are
    // fully restored. Re-run the CURRENT saved pose one editor tick later so
    // the wall renderer is always authoritative after code changes.
    EditorApplication.delayCall -= ReapplyCurrentPoseToWallRendererAfterReload;
    EditorApplication.delayCall += ReapplyCurrentPoseToWallRendererAfterReload;

    if (!hookedViewEditGlobalNavigation)
    {
      RegisterViewEditGlobalNavigation();
      hookedViewEditGlobalNavigation = true;
    }
  }

  private void OnDisable()
  {
    EditorApplication.delayCall -= ReapplyCurrentPoseToWallRendererAfterReload;

    if (hookedViewEditGlobalNavigation)
    {
      UnregisterViewEditGlobalNavigation();
      hookedViewEditGlobalNavigation = false;
    }
    StripObsoleteFrontWallF1ABPieces();
    SaveAssetGuid(PrefsLayoutGuidKey, layout);
    SaveAssetGuid(PrefsGraphicsGuidKey, graphics);
    SaveSessionPrefs();

    EditorApplication.playModeStateChanged -= HandlePlayModeStateChanged;

    if (cachedNativeFrontF2ReadableCopy != null)
    {
      DestroyImmediate(cachedNativeFrontF2ReadableCopy);
      cachedNativeFrontF2ReadableCopy = null;
    }

    if (cachedNativeFrontF3ReadableCopy != null)
    {
      DestroyImmediate(cachedNativeFrontF3ReadableCopy);
      cachedNativeFrontF3ReadableCopy = null;
    }

    if (cachedRight2SReadableCopy != null)
    {
      DestroyImmediate(cachedRight2SReadableCopy);
      cachedRight2SReadableCopy = null;
    }

    if (cachedViAltarEngineF2TestTexture != null)
    {
      DestroyImmediate(cachedViAltarEngineF2TestTexture);
      cachedViAltarEngineF2TestTexture = null;
    }
    if (cachedViAltarEngineF3TestTexture != null)
    {
      DestroyImmediate(cachedViAltarEngineF3TestTexture);
      cachedViAltarEngineF3TestTexture = null;
    }
    cachedViAltarS2Texture = null;
    cachedViAltarS3Texture = null;

    RepaintGameViews();
  }

  private void HandlePlayModeStateChanged(PlayModeStateChange state)
  {
    cachedViewportImage = null;

    if (state == PlayModeStateChange.ExitingEditMode
        || state == PlayModeStateChange.EnteredPlayMode)
    {
      // Hand the RawImage back to the scene RenderTexture before Play runs.
      RestoreViewportTextureAndDestroyPreview();
    }

    if (state == PlayModeStateChange.EnteredPlayMode)
    {
      // In Play Mode, ViewEdit becomes a live "what is actually active" wall view.
      // Clear list filters and show only wall pieces whose runtime Enabled flag is on.
      showOnlyWallsNeededForCurrentPose = true;
      pieceSearchFamilyIndex = 0;
      pieceSearchText = string.Empty;

      // Request a one-shot scroll-to-bottom after the Play Mode UI has
      // completed a real repaint. Setting the scroll position only here is too
      // early because Unity has not calculated the final content height yet.
      scrollToBottomOnNextRepaint = true;
      editorScroll = new Vector2(0f, float.MaxValue);

      Repaint();
    }

    if (state == PlayModeStateChange.EnteredEditMode)
    {
      // Re-apply preview pose after Play mutated live layout Enabled flags.
      StripObsoleteFrontWallF1ABPieces();
      ApplyCurrentPoseVisibilityToLayout();
      RefreshEditModePreview();
    }

    if (state == PlayModeStateChange.ExitingPlayMode)
      RepaintGameViews();
  }

  private void RefreshViewEditIfDynamicGeometryChanged()
  {
    if (Application.isPlaying)
      return;

    bool stairsDownRightD1Active =
        IsStairsDownRightD1ForCurrentPose();

    if (dynamicGeometrySignatureInitialized
        && cachedStairsDownRightD1Active == stairsDownRightD1Active)
    {
      return;
    }

    dynamicGeometrySignatureInitialized = true;
    cachedStairsDownRightD1Active = stairsDownRightD1Active;

    // Rebuild the wall visibility/list and the 320x200 preview from the same
    // current renderer state. This is especially important after recompiles:
    // the pose did not change, so the normal pose-change refresh would never
    // run and ViewEdit could otherwise keep stale RightF0 geometry.
    ApplyCurrentPoseVisibilityToLayout();
    ResetEditModeViewportLogCache();
    DestroyEditModePreviewTextureOnly();
    RefreshEditModePreview();
    RepaintGameViews();
    Repaint();
  }

  private void OnInspectorUpdate()
  {
    if (Application.isPlaying)
    {
      Repaint();
      return;
    }

    RefreshViewEditIfDynamicGeometryChanged();

    // Dungeon Features shares level/X/Y/facing through EditorPrefs. Apply a
    // requested level first so the following pose sync runs against the correct
    // map instead of the map from the previous level.
    int requestedLevel = Mathf.Clamp(
        EditorPrefs.GetInt(PrefsPreviewLevelKey, previewDungeonLevel),
        0,
        PreviewLevelMapPaths.Length - 1);
    if (requestedLevel != previewDungeonLevel)
    {
      previewLevelJumpText = requestedLevel.ToString();
      TryJumpToPreviewLevelFromField();
    }

    // Dungeon Features uses the existing preview X/Y EditorPrefs as a small
    // editor-to-editor bridge. If another editor requests a different tile,
    // apply it through the normal ViewEdit pose path so all geometry, walls,
    // preview texture, and per-pose state are refreshed exactly as usual.
    int requestedX = EditorPrefs.GetInt(PrefsPreviewXKey, previewX);
    int requestedY = EditorPrefs.GetInt(PrefsPreviewYKey, previewY);
    DungeonFacing requestedFacing = (DungeonFacing)EditorPrefs.GetInt(
        PrefsPreviewFacingKey,
        (int)previewFacing);

    if (requestedX != previewX
        || requestedY != previewY
        || requestedFacing != previewFacing)
    {
      SwitchPreviewPose(
          requestedX,
          requestedY,
          requestedFacing);

      // SwitchPreviewPose refuses non-enterable cells. In that case restore
      // the shared prefs to the real ViewEdit pose so Dungeon Features snaps
      // back to the valid highlighted tile instead of drifting out of sync.
      if (previewX != requestedX
          || previewY != requestedY
          || previewFacing != requestedFacing)
      {
        SaveSessionPrefs();
      }
    }
  }

  /// <summary>
  /// Pressing the rear thumb/side mouse button (XButton1 / IMGUI button 3)
  /// anywhere in ViewEdit opens Dungeon Features and maximizes that editor
  /// window. The previous left-button double-click shortcut is intentionally
  /// disabled.
  /// </summary>
  private bool HandleViewEditRearMouseButton()
  {
    Event current = Event.current;
    if (current == null
        || current.type != EventType.MouseDown
        || current.button != 3)
    {
      return false;
    }

    current.Use();
    EditorApplication.delayCall += OpenDungeonFeaturesMaximized;
    return true;
  }

  private static void OpenDungeonFeaturesMaximized()
  {
    // Avoid a compile-time dependency on the separate DungeonFeatureEditor
    // script. A missing class/method is a hard error, not a substitute window.
    System.Type dungeonFeatureEditorType = null;
    System.Reflection.Assembly[] assemblies = System.AppDomain.CurrentDomain.GetAssemblies();
    for (int a = 0; a < assemblies.Length && dungeonFeatureEditorType == null; ++a)
    {
      System.Type[] types;
      try { types = assemblies[a].GetTypes(); }
      catch (System.Reflection.ReflectionTypeLoadException ex) { types = ex.Types; }
      for (int t = 0; t < types.Length; ++t)
      {
        if (types[t] != null && types[t].Name == "DungeonFeatureEditor")
        {
          dungeonFeatureEditorType = types[t];
          break;
        }
      }
    }
    if (dungeonFeatureEditorType == null)
    {
      Debug.LogError("ViewEdit: DungeonFeatureEditor class was not found. Cannot open Dungeon Features.");
      return;
    }
    MethodInfo openMethod = dungeonFeatureEditorType.GetMethod(
        "Open", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static,
        null, System.Type.EmptyTypes, null);
    if (openMethod == null)
    {
      Debug.LogError("ViewEdit: DungeonFeatureEditor.Open() was not found. Cannot open Dungeon Features.");
      return;
    }
    try { openMethod.Invoke(null, null); }
    catch (System.Exception ex)
    {
      Debug.LogError("ViewEdit: DungeonFeatureEditor.Open() failed: " + ex);
      return;
    }

    // DungeonFeatureEditor.Open may create/show the window at the end of this
    // editor update. Maximize it on the next update after Unity has attached
    // the new window to its host view.
    EditorApplication.delayCall += MaximizeDungeonFeaturesWindow;
  }

  private static void MaximizeDungeonFeaturesWindow()
  {
    EditorWindow[] windows = Resources.FindObjectsOfTypeAll<EditorWindow>();
    for (int i = 0; i < windows.Length; ++i)
    {
      EditorWindow candidate = windows[i];
      if (!IsDungeonFeaturesWindow(candidate))
        continue;

      candidate.Focus();
      if (!candidate.maximized)
        candidate.maximized = true;
      return;
    }
  }

  /// <summary>
  /// Right-clicking anywhere inside ViewEdit toggles the minimap on/off.
  /// </summary>
  private bool HandleViewEditRightClick()
  {
    Event current = Event.current;
    if (current == null
        || current.type != EventType.MouseDown
        || current.button != 1)
    {
      return false;
    }

    previewMiniMapMuted = !previewMiniMapMuted;
    current.Use();
    Repaint();
    return true;
  }

  private void OnGUI()
  {
    // Keep ViewEdit pinned to the full monitor height even if Unity restores an
    // older floating-window position or the user drags/resizes the window.
    // Top is always Y=0 and bottom is always the monitor maximum.
    Rect currentWindowRect = position;
    float monitorHeight = GetViewEditMonitorHeight();
    if (!maximized
        && (Mathf.Abs(currentWindowRect.y) > 0.01f
            || Mathf.Abs(currentWindowRect.height - monitorHeight) > 0.5f))
      position = new Rect(
          currentWindowRect.x,
          0f,
          currentWindowRect.width,
          monitorHeight);

    if (HandleViewEditRearMouseButton())
      return;

    if (HandleViewEditRightClick())
      return;

    selectionChangedThisFrame = false;

    if (Application.isPlaying
        && (previewX != lastPlayModeScrollX
            || previewY != lastPlayModeScrollY
            || previewFacing != lastPlayModeScrollFacing))
    {
      lastPlayModeScrollX = previewX;
      lastPlayModeScrollY = previewY;
      lastPlayModeScrollFacing = previewFacing;
      scrollToBottomOnNextRepaint = true;
    }

    // Claim EditorWindow focus on click so existing keyboard nav can run.
    // Do not clear GUI.FocusControl here — a TextField/IntField on this
    // same MouseDown still needs to receive it.
    if (Event.current.type == EventType.MouseDown && Event.current.button == 0)
      Focus();

    // Arrow Up/Down must be handled before BeginScrollView — otherwise the
    // scroll view consumes them for scrolling and HandlePreviewMoveKeyboard
    // never sees a usable KeyDown (Left/Right strafe is unaffected).
    // Facing keys run here too so EnumPopup cannot override the same KeyDown.
    if (layout != null && !Application.isPlaying)
    {
      HandlePreviewMoveKeyboard();
      HandlePreviewFacingKeyboard();
      HandlePreviewStrafeKeyboard();
    }

    if (layout == null)
    {
      EditorGUILayout.HelpBox("Select a ViewportLayout asset.", MessageType.Info);
      return;
    }

    if (graphics == null)
    {
      EditorGUILayout.HelpBox(
          "Select a DungeonGraphics asset (textures for the Edit Mode preview).",
          MessageType.Warning);
    }

    bool layoutEditable = !Application.isPlaying;
    if (!layoutEditable)
    {
      EditorGUILayout.HelpBox(
          "ViewportLayout.asset is read-only in Play Mode. "
              + "Stop Play to edit and save layout coordinates/visibility.",
          MessageType.Warning);
    }

    ClampSelectedPieceIndex();

    // Keep the complete minimap outside the controls scroll area. The map is
    // always visible as one fixed ViewEdit header; only the wall/feature rows
    // below it scroll when the window eventually needs more vertical room.
    if (fitWidthToContent && Event.current.type == EventType.Repaint)
      fittedContentRight = 0f;

    DrawMapPosePreviewControls();

    editorScroll = EditorGUILayout.BeginScrollView(editorScroll);

    // Run the global ViewEdit right-click action only after DrawPreviewMiniMap
    // has had a chance to consume a right-click inside the minimap. This keeps
    // the existing "right-click anywhere else -> Search/top" behavior without
    // overruling the minimap mute toggle.
    HandleViewEditRightClickHome();

    using (new EditorGUI.DisabledScope(!layoutEditable))
    {
      EditorGUI.BeginChangeCheck();

      if (layoutEditable)
        Undo.RecordObject(layout, "Viewport Layout Change");

      DrawSnapToolbar();

      string currentFrontChampion;
      if (TryGetCurrentD1FrontChampion(out currentFrontChampion))
      {
        string currentChampionKey = NormalizeChampionAssetKey(currentFrontChampion);
        bool taken = previewTakenChampionKeys.Contains(currentChampionKey);

        EditorGUILayout.BeginHorizontal();
        GUILayout.Space(4f);
        GUILayout.Label("Champion Mirror", EditorStyles.miniLabel, GUILayout.Width(96f));
        bool newTaken = GUILayout.Toggle(
            taken,
            currentFrontChampion + " Taken",
            EditorStyles.miniButton,
            GUILayout.Width(130f));
        if (newTaken != taken)
        {
          if (newTaken)
            previewTakenChampionKeys.Add(currentChampionKey);
          else
            previewTakenChampionKeys.Remove(currentChampionKey);

          RefreshEditModePreview();
          RepaintGameViews();
          Repaint();
        }
        EditorGUILayout.EndHorizontal();
      }

      EditorGUILayout.BeginHorizontal();
      EditorGUILayout.PrefixLabel(
          "Search Pieces",
          EditorStyles.popup,
          GetSearchPiecesLabelStyle());

      GUIStyle searchPoseStyle = new GUIStyle(EditorStyles.boldLabel);
      Color brightBlue = new Color(0.2f, 0.7f, 1.0f);
      searchPoseStyle.normal.textColor = brightBlue;
      searchPoseStyle.hover.textColor = brightBlue;
      searchPoseStyle.focused.textColor = brightBlue;
      searchPoseStyle.active.textColor = brightBlue;
      GUILayout.Label(
          previewX + "/" + previewY + " " + previewFacing,
          searchPoseStyle,
          GUILayout.Width(78f));

      bool guiChangedBeforeSearch = GUI.changed;
      Rect searchPiecesPopupRect = EditorGUILayout.GetControlRect(
          GUILayout.Width(135f),
          GUILayout.ExpandWidth(false));
      Event searchEvent = Event.current;
      if (searchEvent.type == EventType.MouseDown
          && searchEvent.button == 0
          && searchPiecesPopupRect.Contains(searchEvent.mousePosition))
      {
        openSearchPiecesPopup = true;
        focusSearchPieces = true;
      }
      GUI.SetNextControlName(SearchPiecesControlName);
      pieceSearchText = EditorGUI.TextField(
          searchPiecesPopupRect,
          pieceSearchText ?? string.Empty);
      if (focusSearchPieces && Event.current.type == EventType.Repaint)
      {
        GUI.FocusControl(SearchPiecesControlName);
        EditorGUI.FocusTextInControl(SearchPiecesControlName);
        focusSearchPieces = false;
      }
      // Search is a list filter only — never treat it as a layout persist.
      GUI.changed = guiChangedBeforeSearch;
      if (openSearchPiecesPopup && Event.current.type != EventType.Layout)
      {
        openSearchPiecesPopup = false;
        bool previousEnabled = GUI.enabled;
        GUI.enabled = true;
        ShowSearchPiecesFamilyMenu(searchPiecesPopupRect);
        GUI.enabled = previousEnabled;
      }

      EditorGUILayout.EndHorizontal();


      ClampSearchFamilyToEnabledPieces();
      HandlePieceSearchKeyboard();

      if (layoutEditable)
      {
        StripObsoleteFrontWallF1ABPieces();
        EnsureLeftS3AndRightS3Pieces();
      }

      bool changed = false;

      List<int> displayIndices = new List<int>();
      for (int i = 0; i < layout.Pieces.Count; i++)
      {
        ViewportPiece piece = layout.Pieces[i];
        if (IsHiddenFromEditorPieceList(piece))
          continue;

        if (!PieceMatchesSearchFilter(piece))
          continue;

        displayIndices.Add(i);
      }

      displayIndices.Sort(CompareViewEditPieceDisplayOrder);

      for (int n = 0; n < displayIndices.Count; n++)
      {
        int i = displayIndices[n];
        ViewportPiece piece = layout.Pieces[i];
        bool isSelected = i == selectedPieceIndex;
        DrawPieceCard(i, piece, isSelected, ref changed);
      }

      // Non-wall map features are always listed directly below the wall rows
      // for the current pose. X/Y come first and the temporary Enabled switch
      // stays on the far right, so ViewEdit can be used as a visual checklist.
      DrawCurrentPoseFeatureRows();

      bool editorChanged = EditorGUI.EndChangeCheck();
      if ((editorChanged || changed)
          && !previewMirrorChangedThisFrame
          && !previewFrontF1WidthChangedThisFrame
          && !previewFrontF3WidthChangedThisFrame
          && !previewPositionChangedThisFrame
          && !previewEnabledChangedThisFrame
          && !previewGraphicChangedThisFrame)
        PersistChanges();
      previewMirrorChangedThisFrame = false;
      previewFrontF1WidthChangedThisFrame = false;
      previewFrontF3WidthChangedThisFrame = false;
      previewPositionChangedThisFrame = false;
      previewEnabledChangedThisFrame = false;
      previewGraphicChangedThisFrame = false;
    }

    EditorGUILayout.EndScrollView();

    if (scrollToBottomOnNextRepaint
        && Event.current.type == EventType.Repaint)
    {
      editorScroll = new Vector2(0f, float.MaxValue);
      scrollToBottomOnNextRepaint = false;
      Repaint();
    }

    // Click on empty / non-control area: release leftover text-field focus
    // so keyboard nav works. Controls that consume MouseDown (TextField,
    // IntField, buttons) are left alone here.
    if (Event.current.type == EventType.MouseDown && Event.current.button == 0)
    {
      GUI.FocusControl(null);
      Focus();
    }

    if (selectionChangedThisFrame)
    {
      RefreshEditModePreview();
      Repaint();
    }

    FinishContentWidthFit();
  }

  /// <summary>
  /// Muted investigation pieces stay in the layout asset but are not listed.
  /// Disabled pieces for the current pose are also omitted from ViewEdit.
  /// </summary>
  private void EnsurePreviewStickyWallPose()
  {
    if (previewStickyPoseLevel == previewDungeonLevel
        && previewStickyPoseX == previewX
        && previewStickyPoseY == previewY
        && previewStickyPoseFacing == previewFacing)
    {
      return;
    }

    previewStickyVisibleWallFamilies.Clear();
    previewStickyPoseLevel = previewDungeonLevel;
    previewStickyPoseX = previewX;
    previewStickyPoseY = previewY;
    previewStickyPoseFacing = previewFacing;
  }

  private void KeepWallCardVisibleForCurrentPose(ViewportPiece piece)
  {
    if (piece == null)
      return;

    EnsurePreviewStickyWallPose();

    string family = GetViewport17NormalWallFamily(piece);
    if (string.IsNullOrEmpty(family))
      family = piece.Name ?? string.Empty;

    if (!string.IsNullOrEmpty(family))
      previewStickyVisibleWallFamilies.Add(family);
  }

  private bool IsWallCardStickyVisibleForCurrentPose(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    EnsurePreviewStickyWallPose();

    string family = GetViewport17NormalWallFamily(piece);
    if (string.IsNullOrEmpty(family))
      family = piece.Name ?? string.Empty;

    return !string.IsNullOrEmpty(family)
        && previewStickyVisibleWallFamilies.Contains(family);
  }

  private bool IsHiddenFromEditorPieceList(ViewportPiece piece)
  {
    if (piece == null || piece.Name == null)
      return false;

    // Permanent ViewEdit exclusions.
    if (piece.Name == "Front Wall F1"
        || piece.Name == "Ceiling"
        || piece.Name == "Floor"
        || piece.Graphic == DungeonGraphicType.Ceiling
        || piece.Graphic == DungeonGraphicType.Floor
        || piece.Name == "Movement Arrows"
        || piece.Graphic == DungeonGraphicType.MovementArrows
        || piece.Name == "Champion Status Slot 1"
        || piece.Name == "Champion Status Slot 2"
        || piece.Name == "Champion Status Slot 3"
        || piece.Name == "Champion Status Slot 4"
        || piece.Name == "Ceiling Strip 84"
        || piece.Name == "Ceiling Strip 85")
    {
      return true;
    }

    // Generic stairs-down rule: when the near-center relative cell is a
    // down-stair, FrontF2 is replaced by the stair opening and is not a
    // comparison card for this pose.
    if (IsViewport17NearCenterStairsDown()
        && (IsFrontWallF2Card(piece)
            || FrontWallF2Logic.IsFrontWallF2Graphic(piece.Graphic)))
    {
      return true;
    }

    // Black Door handling in ViewEdit:
    // - In normal/needed-only mode, show only Black Door pieces required by
    //   the current pose.
    // - In All Walls mode, expose the Black Door FRAME wall components so
    //   oblique/side scenes can be inspected and adjusted manually.
    // - Keep the solid BlackDoorF1/F2/F3 front images out of All Walls; they
    //   remain available only in their actual front-door poses.
    if (IsBlackDoorEditorPiece(piece))
    {
      bool blackDoorFrontImage = IsBlackDoorFrontImagePiece(piece);

      if (!showOnlyWallsNeededForCurrentPose)
      {
        if (blackDoorFrontImage)
          return true;
        // Frame components stay available in All Walls, including after a
        // temporary Enabled=OFF click at the current pose.
      }
      else if (!IsWallNeededForCurrentPose(piece))
      {
        return true;
      }
    }

    // Manual inspection cards may remain reachable only while the user is in
    // Show All Walls mode on the current pose. In the normal geometry-filtered
    // mode (including immediately after any pose change), disabled walls must
    // not leak into the ViewEdit list.
    if (!showOnlyWallsNeededForCurrentPose
        && (IsBlackDoorF1ManualSideWallCandidate(piece)
            || piece.Name == "LeftS3"))
      return false;

    if (showOnlyWallsNeededForCurrentPose
        && (IsWallEditorPiece(piece) || IsBlackDoorEditorPiece(piece)))
    {
      // Edit Mode: show walls required by the preview geometry.
      // Play Mode: show the walls the runtime renderer has actually enabled.
      bool wallIsActive =
          Application.isPlaying
          ? piece.Enabled
          : IsWallNeededForCurrentPose(piece);

      // Any temporary ViewEdit interaction with a piece must keep its card
      // visible for the rest of the current pose, even when Enabled was turned
      // OFF. The temporary override dictionaries are cleared on pose/facing
      // change, so the card naturally disappears/resets when leaving the pose.
      if (HasPreviewEnabledOverrideForPieceOrFamily(piece)
          || previewMirrorOverrideByPiece.ContainsKey(piece)
          || previewPositionOverrideByPiece.ContainsKey(piece)
          || IsWallCardStickyVisibleForCurrentPose(piece))
      {
        wallIsActive = true;
      }

      if (!wallIsActive)
        return true;
    }

    return false;
  }

  private void EnableAllWallsNeededForCurrentPose()
  {
    if (layout == null || layout.Pieces == null)
      return;

    Undo.RecordObject(layout, "Enable Walls Needed For Current Pose");

    bool changed = false;
    for (int i = 0; i < layout.Pieces.Count; i++)
    {
      ViewportPiece piece = layout.Pieces[i];
      if (piece == null
          || (!IsWallEditorPiece(piece) && !IsBlackDoorEditorPiece(piece)))
        continue;

      bool needed = IsWallNeededForCurrentPose(piece);
      if (needed && !piece.Enabled)
      {
        piece.Enabled = true;
        changed = true;
      }
    }

    if (!changed)
      return;

    EditorUtility.SetDirty(layout);

    RefreshEditModePreview();
  }

  private static bool IsWallEditorPiece(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    if (IsWallF0LeftPiece(piece)
        || IsWallF0RightPiece(piece)
        || IsWallF1LeftPiece(piece)
        || IsWallF1RightPiece(piece)
        || IsWallF2LeftPiece(piece)
        || IsWallF2RightPiece(piece)
        || IsWallF3LeftPiece(piece)
        || IsWallF3RightPiece(piece)
        || IsFrontWallF1Card(piece)
        || IsFrontWallF2Card(piece)
        || IsFrontWallF3Card(piece))
    {
      return true;
    }

    string name = piece.Name ?? string.Empty;
    return name == "LeftD3"
        || name == "RightD3"
        || name == "LeftS3"
        || name == "RightS3"
        || name == "Wall D3L2"
        || name == "Wall D3R2"
        || name == "WallD3L2"
        || name == "WallD3R2"
        || name == "Black Door Frame Left F1"
        || name == "Black Door Frame Right F1"
        || name == "Black Door Frame Left F2"
        || name == "Black Door Frame Right F2"
        || name == "BlackDoorF1";
  }

  private static bool IsBlackDoorFrontImagePiece(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    string name = piece.Name ?? string.Empty;
    return name == "BlackDoorF1"
        || name == "BlackDoorF2"
        || name == "BlackDoorF3";
  }

  private static bool IsBlackDoorEditorPiece(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    string name = piece.Name ?? string.Empty;
    return name == "BlackDoorF1"
        || name == "BlackDoorF2"
        || name == "BlackDoorF3"
        || name == "Black Door Frame Left F1"
        || name == "Black Door Frame Right F1"
        || name == "Black Door Frame Left F2"
        || name == "Black Door Frame Right F2"
        || name == "Black Door Frame Left F3"
        || name == "Black Door Frame Right F3";
  }

  private bool IsViewport17NearCenterStairsDown()
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return false;

    // Generic relative-cell rule: a down-stair directly ahead occupies the
    // D2 center opening. Map coordinates never participate in this decision.
    return SampleViewport17Cell(0, 1).IsStairsDown;
  }

  /// <summary>
  /// True only for the Hall of Champions special entrance Black Door.
  /// Regular Door tiles elsewhere must use their normal door renderer and must
  /// never activate the BlackDoorF1/F2/F3 family.
  /// </summary>
  private bool IsHallOfChampionsBlackDoorCell(Viewport17Cell cell)
  {
    return cell.IsInside
        && previewDungeonLevel == PreviewDungeonLevel
        && cell.MapX == HallOfChampionsBlackDoorX
        && cell.MapY == HallOfChampionsBlackDoorY
        && previewDoorTiles.Contains(new Vector2Int(cell.MapX, cell.MapY));
  }

  /// <summary>
  /// Player-relative center test for the special Black Door.
  /// Depth 1 = F1, 2 = F2, 3 = F3.
  /// </summary>
  private bool IsDoorAtViewportCenterDepth(int depth)
  {
    if (depth < 1)
      return false;

    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return false;

    // A wall in front of the door hides it. From 4,2 West the door at 1,2
    // is three steps ahead, but 3,2 and 2,2 are walls, so this is not F3.
    if (!IsCenterSightLineOpenBefore(depth))
      return false;

    return IsHallOfChampionsBlackDoorCell(SampleViewport17Cell(0, depth));
  }

  private bool IsCenterSightLineOpenBefore(int depth)
  {
    for (int step = 1; step < depth; step++)
    {
      Viewport17Cell nearer = SampleViewport17Cell(0, step);
      if (!nearer.IsInside || nearer.State == Viewport17CellState.Wall)
        return false;
    }

    return true;
  }

  private bool IsDoorF1FrontView()
  {
    return IsDoorAtViewportCenterDepth(1);
  }

  private bool IsDoorF2FrontView()
  {
    return IsDoorAtViewportCenterDepth(2);
  }

  private bool IsDoorF3FrontView()
  {
    return IsDoorAtViewportCenterDepth(3);
  }

  /// <summary>
  /// Player-relative D3-right oblique test for the special Black Door.
  /// It occupies the cell one lane right and three cells forward.
  /// </summary>
  private bool IsDoorF3RightObliqueView()
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return false;

    // The D3-right door is only visible down an open center corridor.
    if (!IsCenterSightLineOpenBefore(4))
      return false;

    return IsHallOfChampionsBlackDoorCell(SampleViewport17Cell(1, 3));
  }


  private bool IsWallNeededForCurrentPose(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    EnsurePreviewMiniMapLoaded();

    // If the minimap cannot be read, do not hide wall cards.
    if (previewMiniMap == null)
      return true;

    string name = piece.Name ?? string.Empty;
    bool doorAtF1 = IsDoorF1FrontView();
    bool doorAtF2 = IsDoorF2FrontView();
    bool doorAtF3 = IsDoorF3FrontView();

    // A door directly ahead occupies the F1 center opening, so the normal
    // FrontF2 wall behind it is not needed. Player-relative; no map coordinate.
    if (IsDoorF1FrontView()
        && (IsFrontWallF2Card(piece)
            || FrontWallF2Logic.IsFrontWallF2Graphic(piece.Graphic)))
    {
      return false;
    }

    // Generic stairs-down rule: a down-stair in the near-center relative
    // cell occupies the FrontF2 center band, so FrontF2 is not needed.
    if (IsViewport17NearCenterStairsDown()
        && (IsFrontWallF2Card(piece)
            || FrontWallF2Logic.IsFrontWallF2Graphic(piece.Graphic)))
    {
      return false;
    }

    // Black Door editor cards must be decided BEFORE the generic normal-wall
    // resolver. Some Black Door pieces are classified as normal wall pieces,
    // so the old ordering returned their resolved Enabled=false before these
    // dedicated door-pose rules were ever reached.
    if (IsBlackDoorEditorPiece(piece))
    {
      if (doorAtF1)
      {
        return name == "Black Door Frame Left F1"
            || name == "Black Door Frame Right F1"
            || name == "BlackDoorF1";
      }

      if (doorAtF2)
      {
        return name == "Black Door Frame Left F2"
            || name == "Black Door Frame Right F2"
            || name == "BlackDoorF2";
      }

      if (doorAtF3)
      {
        return name == "Black Door Frame Left F3"
            || name == "Black Door Frame Right F3"
            || name == "BlackDoorF3";
      }

      if (IsDoorF3RightObliqueView())
      {
        return name == "Black Door Frame Right F3"
            || name == "BlackDoorF3";
      }

      return false;
    }

    if (IsNormalWallPiece(piece)
        && TryGetResolvedNormalWallState(
            piece, out ResolvedNormalWallState resolvedNeededState))
    {
      return resolvedNeededState.Enabled;
    }

    // LeftS3 is a ViewEdit-only geometry piece, so it is not classified as a
    // normal wall. Use the same resolved strict-geometry state for the needed
    // walls filter instead of falling through to the default-visible path.
    if (name == "LeftS3")
    {
      if (TryGetResolvedNormalWallState(
              piece, out ResolvedNormalWallState leftS2NeededState))
      {
        return leftS2NeededState.Enabled;
      }

      return false;
    }

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    bool TileIsWallOrOutside(int x, int y)
    {
      return !previewMiniMap.IsInside(x, y)
          || previewMiniMap.GetTile(x, y).Type == DungeonTileType.Wall;
    }

    int f1X = previewX + forwardX;
    int f1Y = previewY + forwardY;
    int f2X = previewX + forwardX * 2;
    int f2Y = previewY + forwardY * 2;
    int f3X = previewX + forwardX * 3;
    int f3Y = previewY + forwardY * 3;

    bool f1CenterWall = TileIsWallOrOutside(f1X, f1Y);
    bool f2CenterWall = TileIsWallOrOutside(f2X, f2Y);
    bool f3CenterWall = TileIsWallOrOutside(f3X, f3Y);

    if (IsWallF0LeftPiece(piece))
      return TileIsWallOrOutside(previewX - rightX, previewY - rightY);

    if (IsWallF0RightPiece(piece))
      return TileIsWallOrOutside(previewX + rightX, previewY + rightY);

    if (IsWallF1LeftPiece(piece))
      return !f1CenterWall
          && TileIsWallOrOutside(f1X - rightX, f1Y - rightY);

    if (IsWallF1RightPiece(piece))
      return !f1CenterWall
          && TileIsWallOrOutside(f1X + rightX, f1Y + rightY);

    if (IsWallF2LeftPiece(piece))
      return !f1CenterWall
          && !f2CenterWall
          && TileIsWallOrOutside(f2X - rightX, f2Y - rightY);

    if (IsWallF2RightPiece(piece))
      return !f1CenterWall
          && !f2CenterWall
          && TileIsWallOrOutside(f2X + rightX, f2Y + rightY);

    if (IsWallF3LeftPiece(piece))
      return !f1CenterWall
          && !f2CenterWall
          && !f3CenterWall
          && TileIsWallOrOutside(f3X - rightX, f3Y - rightY);

    if (IsWallF3RightPiece(piece))
      return !f1CenterWall
          && !f2CenterWall
          && !f3CenterWall
          && TileIsWallOrOutside(f3X + rightX, f3Y + rightY);

    if (IsFrontWallF1Card(piece))
      return f1CenterWall;

    if (IsFrontWallF3Card(piece))
    {
      if (IsDoorF2FrontView())
        return false;

      return !f1CenterWall && !f2CenterWall && f3CenterWall;
    }

    if (name == "LeftD3" || name == "Wall D3L2")
    {
      return !f1CenterWall
          && !f2CenterWall
          && !f3CenterWall
          && TileIsWallOrOutside(f3X - rightX, f3Y - rightY);
    }

    if (name == "RightD3" || name == "Wall D3R2")
    {
      // RightD3 visibility is geometry-driven only. If the generic resolver
      // has no state for this piece, it is not needed at the current pose.
      if (TryGetResolvedNormalWallState(
              piece, out ResolvedNormalWallState rightD3State))
      {
        return rightD3State.Enabled;
      }

      return false;
    }

    // Other Black Door cards are hidden unless one of the exact views above needs them.
    if (name == "Black Door Frame Left F1"
        || name == "Black Door Frame Right F1"
        || name == "Black Door Frame Left F2"
        || name == "Black Door Frame Right F2"
        || name == "BlackDoorF1")
    {
      return false;
    }

    return true;
  }

  /// <summary>
  /// Live editor cards come from layout.Pieces. Obsolete A/B pieces must be
  /// removed here so Unity in-memory state cannot write them back to disk.
  /// </summary>
  private void StripObsoleteFrontWallF1ABPieces()
  {
    if (layout == null || layout.Pieces == null)
      return;

    bool hasFrontWallF1 = false;
    for (int i = 0; i < layout.Pieces.Count; i++)
    {
      ViewportPiece piece = layout.Pieces[i];
      if (piece == null)
        continue;

      if (piece.Name == "Front Wall F1"
          || piece.Graphic == DungeonGraphicType.FrontWallF1)
      {
        hasFrontWallF1 = true;
        break;
      }
    }

    int insertAt = -1;
    int keepX = 40;
    int keepY = 47;
    bool removed = false;

    for (int i = layout.Pieces.Count - 1; i >= 0; i--)
    {
      ViewportPiece piece = layout.Pieces[i];
      if (piece == null)
        continue;

      if (piece.Name != "Front Wall F1 A"
          && piece.Name != "Front Wall F1 B")
      {
        continue;
      }

      keepX = piece.X;
      keepY = piece.Y;
      insertAt = i;
      layout.Pieces.RemoveAt(i);
      removed = true;
    }

    if (!hasFrontWallF1)
    {
      if (insertAt < 0)
        insertAt = layout.Pieces.Count;

      layout.Pieces.Insert(
          insertAt,
          new ViewportPiece
          {
            Name = "Front Wall F1",
            Graphic = DungeonGraphicType.FrontWallF1,
            X = keepX,
            Y = keepY,
            Enabled = false,
            MirrorHorizontally = false,
            FrontWallF1Width = StraightF1WallLogic.DefaultFrontWallF1Width
          });
      removed = true;
    }

    if (!removed)
      return;

    EditorUtility.SetDirty(layout);
    ClampSelectedPieceIndex();
  }


  private bool PieceMatchesSearchFilter(ViewportPiece piece)
  {
    if (piece == null)
      return false;

    if (showOnlyWallsNeededForCurrentPose && showWallsActivFilter)
    {
      // Active-wall view normally follows the current resolved draw set.
      // Exception: once the user touches a wall card at this pose, keep that
      // card/family visible even after Enabled is turned OFF so it can be
      // switched back ON. This is especially important for LeftD3/RightD3,
      // whose visible card can be backed by Wall D3L2/Wall D3R2 aliases.
      return IsWallCardStickyVisibleForCurrentPose(piece)
          || MatchesShowWallsActivFilter(piece);
    }

    string search = (pieceSearchText ?? string.Empty).Trim();
    if (search.Length > 0)
    {
      string name = piece != null ? piece.Name ?? string.Empty : string.Empty;
      return name.IndexOf(search, System.StringComparison.OrdinalIgnoreCase) >= 0;
    }

    if (pieceSearchFamilyIndex <= 0
        || pieceSearchFamilyIndex >= PieceSearchFamilyOptions.Length)
    {
      return !IsOnDemandSearchPiece(piece);
    }

    string selectedFamily =
        PieceSearchFamilyOptions[pieceSearchFamilyIndex];
    return PieceMatchesSearchFamily(piece, selectedFamily);
  }

  /// <summary>
  /// Movement Arrows, Champion Status Slots, Ceiling, and Floor stay off the
  /// unfiltered ViewEdit list; Search Pieces text/family can still reveal them.
  /// </summary>
  private static bool IsOnDemandSearchPiece(ViewportPiece piece)
  {
    return PieceMatchesSearchFamily(piece, "Arrows")
        || PieceMatchesSearchFamily(piece, "Champion Slot 1")
        || PieceMatchesSearchFamily(piece, "Champion Slot 2")
        || PieceMatchesSearchFamily(piece, "Champion Slot 3")
        || PieceMatchesSearchFamily(piece, "Champion Slot 4")
        || PieceMatchesSearchFamily(piece, "Ceiling")
        || PieceMatchesSearchFamily(piece, "Floor");
  }

  /// <summary>
  /// Show Walls Activ: only wall images the loaded map's current view has
  /// resolved as enabled. Ceiling, Floor, and unmatched catalog images are
  /// excluded. Family and text search are not applied.
  /// </summary>
  private bool MatchesShowWallsActivFilter(ViewportPiece piece)
  {
    if (piece == null || IsFloorOrCeiling(piece))
      return false;

    if (IsBlackDoorEditorPiece(piece))
      return IsWallNeededForCurrentPose(piece);

    if (!IsWallEditorPiece(piece) && !IsNormalWallPiece(piece))
      return false;

    if (!TryGetResolvedNormalWallState(
            piece, out ResolvedNormalWallState resolvedState))
    {
      return false;
    }

    return resolvedState.Enabled;
  }

  /// <summary>
  /// Exact family filters for the Search Pieces dropdown. Prefixes use FrontF /
  /// LeftF / RightF so LeftD3 and RightD3 are not included in Left / Right.
  /// </summary>
  private static bool PieceMatchesSearchFamily(
      ViewportPiece piece,
      string family)
  {
    if (piece == null)
      return false;

    string name = piece.Name ?? string.Empty;
    switch (family)
    {
      case "Front":
        return name.StartsWith("FrontF", System.StringComparison.Ordinal)
            || name.StartsWith("Front Wall F", System.StringComparison.Ordinal);
      case "Left":
        return name.StartsWith("LeftF", System.StringComparison.Ordinal);
      case "Right":
        return name.StartsWith("RightF", System.StringComparison.Ordinal);
      case "LeftD3":
        return name == "LeftD3";
      case "RightD3":
        return name == "RightD3";
      case "Black Door":
        return name.IndexOf("Black Door", System.StringComparison.OrdinalIgnoreCase) >= 0
            || string.Equals(
                name,
                "BlackDoorF1",
                System.StringComparison.OrdinalIgnoreCase);
      case "Active":
        return piece.Enabled;
      case "Arrows":
        return name == "Movement Arrows"
            || piece.Graphic == DungeonGraphicType.MovementArrows;
      case "Champion Slot 1":
        return name == "Champion Status Slot 1";
      case "Champion Slot 2":
        return name == "Champion Status Slot 2";
      case "Champion Slot 3":
        return name == "Champion Status Slot 3";
      case "Champion Slot 4":
        return name == "Champion Status Slot 4";
      case "Ceiling":
        return name == "Ceiling"
            || piece.Graphic == DungeonGraphicType.Ceiling;
      case "Floor":
        return name == "Floor"
            || piece.Graphic == DungeonGraphicType.Floor;
      default:
        return true;
    }
  }

  private GUIStyle GetSearchPiecesLabelStyle()
  {
    if (searchPiecesLabelStyle == null)
    {
      searchPiecesLabelStyle = new GUIStyle(EditorStyles.label)
      {
        fontStyle = FontStyle.Bold
      };
      Color brightGreen = new Color(0.2f, 1.0f, 0.2f);
      searchPiecesLabelStyle.normal.textColor = brightGreen;
      searchPiecesLabelStyle.hover.textColor = brightGreen;
      searchPiecesLabelStyle.focused.textColor = brightGreen;
      searchPiecesLabelStyle.active.textColor = brightGreen;
    }

    return searchPiecesLabelStyle;
  }

  private GUIStyle GetPieceFamilyHeaderStyle(Color color)
  {
    if (pieceFamilyHeaderStyle == null)
    {
      pieceFamilyHeaderStyle = new GUIStyle(EditorStyles.boldLabel)
      {
        fontStyle = FontStyle.Bold
      };
    }

    pieceFamilyHeaderStyle.normal.textColor = color;
    pieceFamilyHeaderStyle.hover.textColor = color;
    pieceFamilyHeaderStyle.focused.textColor = color;
    pieceFamilyHeaderStyle.active.textColor = color;
    return pieceFamilyHeaderStyle;
  }
  /// <summary>
  /// Right-click anywhere in ViewEdit scrolls to the top and focuses the
  /// Search Pieces text field. Does not open a popup or change Enabled flags.
  /// </summary>
  private void HandleViewEditRightClickHome()
  {
    Event current = Event.current;
    if (current == null)
      return;

    bool rightPressed =
        current.type == EventType.MouseDown && current.button == 1;
    if (!rightPressed && current.type != EventType.ContextClick)
      return;

    editorScroll = Vector2.zero;
    pieceSearchFamilyIndex = 0;
    focusSearchPieces = true;
    current.Use();
    Repaint();
  }

  private void ShowSearchPiecesFamilyMenu(Rect popupRect)
  {
    GenericMenu menu = new GenericMenu();
    for (int i = 0; i < PieceSearchFamilyOptions.Length; i++)
    {
      string label = PieceSearchFamilyOptions[i];
      if (string.IsNullOrEmpty(label))
        continue;

      int index = i;
      menu.AddItem(
          new GUIContent(label),
          false,
          () =>
          {
            pieceSearchFamilyIndex = index;
            showWallsActivFilter = false;
            pieceSearchText = string.Empty;
            editorScroll = Vector2.zero;
            GUI.FocusControl(null);
            Repaint();
          });
    }

    menu.DropDown(popupRect);
  }

  private void ClampSearchFamilyToEnabledPieces()
  {
    if (pieceSearchFamilyIndex <= 0)
      return;

    if (pieceSearchFamilyIndex >= PieceSearchFamilyOptions.Length)
    {
      pieceSearchFamilyIndex = 0;
      return;
    }

    string family = PieceSearchFamilyOptions[pieceSearchFamilyIndex];
    if (string.IsNullOrEmpty(family))
    {
      pieceSearchFamilyIndex = 0;
      return;
    }

    // Keep the selected family even when all of its pieces are disabled.
    // This lets ViewEdit show those disabled pieces so they can be enabled again.
  }

  private static bool IsPermanentSearchFamily(string family)
  {
    return family == "Arrows"
        || family == "Champion Slot 1"
        || family == "Champion Slot 2"
        || family == "Champion Slot 3"
        || family == "Champion Slot 4"
        || family == "Ceiling"
        || family == "Floor";
  }

  private bool FamilyHasEnabledPiece(string family)
  {
    if (layout == null || layout.Pieces == null || string.IsNullOrEmpty(family))
      return false;

    for (int i = 0; i < layout.Pieces.Count; i++)
    {
      ViewportPiece piece = layout.Pieces[i];
      if (piece == null || !piece.Enabled)
        continue;

      if (PieceMatchesSearchFamily(piece, family))
        return true;
    }

    return false;
  }

  private void HandlePieceSearchKeyboard()
  {
    Event current = Event.current;
    if (current.type != EventType.KeyDown)
      return;

    if (focusedWindow != this)
      return;

    if (current.keyCode != KeyCode.Escape)
      return;

    if (pieceSearchFamilyIndex == 0)
      return;

    pieceSearchFamilyIndex = 0;
    current.Use();
    GUI.FocusControl(null);
    Repaint();
  }

  /// <summary>
  /// Piece-card checkbox that toggles only from mouse clicks. Keyboard
  /// events are ignored and the control is not allowed to keep focus, so
  /// End/Page Down/arrows/Space cannot change Enabled or Mirror.
  /// </summary>
  private static bool DrawMouseOnlyToggle(
      string label,
      bool value,
      bool pieceEnabled,
      params GUILayoutOption[] options)
  {
    Rect rowRect = EditorGUILayout.GetControlRect(
        true,
        EditorGUIUtility.singleLineHeight,
        options);
    Rect toggleRect = EditorGUI.PrefixLabel(rowRect, new GUIContent(label));
    toggleRect.width = 16f;

    Event current = Event.current;
    bool isMirror = label == "Mirror" || label == "Mirror Horizontally";
    if (current != null
        && current.type == EventType.MouseDown
        && current.button == 0
        && toggleRect.Contains(current.mousePosition))
    {
      value = !value;
      GUI.changed = true;
      current.Use();
    }

    // Shared Unity checkbox chrome. Colored fills are
    // inset so they cannot cover the PrefixLabel or change hit-testing.
    GUI.Toggle(toggleRect, false, GUIContent.none, EditorStyles.toggle);

    Color checkColor = new Color(0.2f, 1.0f, 0.2f);
    bool showChecked = value;
    if (pieceEnabled && showChecked && isMirror)
    {
      EditorGUI.DrawRect(InsetToggleFillRect(toggleRect), new Color(1f, 140f / 255f, 0f));
      checkColor = Color.black;
    }

    if (showChecked)
    {
      GUIStyle checkStyle = new GUIStyle(EditorStyles.label)
      {
        alignment = TextAnchor.MiddleCenter,
        fontStyle = FontStyle.Bold,
        fontSize = 13,
        padding = new RectOffset(0, 0, 0, 1)
      };
      checkStyle.normal.textColor = checkColor;
      GUI.Label(toggleRect, "✓", checkStyle);
    }

    // This custom toggle never takes keyboard focus, preserving ViewEdit's
    // End/Page Down/arrows/Space navigation behavior.
    return value;
  }

  /// <summary>
  /// Compact mouse-only toggle for feature rows. The checkbox is placed
  /// immediately after its caption instead of using Unity's global prefix
  /// label width. This keeps rows visually tight: Enabled [ ] Mirror [ ].
  /// </summary>
  private static bool DrawCompactMouseOnlyToggle(
      string label,
      bool value,
      bool isMirror)
  {
    float labelWidth = EditorStyles.label.CalcSize(new GUIContent(label)).x;
    GUILayout.Label(label, GUILayout.Width(labelWidth));

    Rect toggleRect = GUILayoutUtility.GetRect(
        16f,
        EditorGUIUtility.singleLineHeight,
        GUILayout.Width(16f),
        GUILayout.ExpandWidth(false));

    Event current = Event.current;
    if (current != null
        && current.type == EventType.MouseDown
        && current.button == 0
        && toggleRect.Contains(current.mousePosition))
    {
      value = !value;
      GUI.changed = true;
      current.Use();
    }

    GUI.Toggle(toggleRect, false, GUIContent.none, EditorStyles.toggle);

    if (value)
    {
      Color checkColor = new Color(0.2f, 1.0f, 0.2f);
      if (isMirror)
      {
        EditorGUI.DrawRect(
            InsetToggleFillRect(toggleRect),
            new Color(1f, 140f / 255f, 0f));
        checkColor = Color.black;
      }

      GUIStyle checkStyle = new GUIStyle(EditorStyles.label)
      {
        alignment = TextAnchor.MiddleCenter,
        fontStyle = FontStyle.Bold,
        fontSize = 13,
        padding = new RectOffset(0, 0, 0, 1)
      };
      checkStyle.normal.textColor = checkColor;
      GUI.Label(toggleRect, "✓", checkStyle);
    }

    GUILayout.Space(6f);
    return value;
  }

  private static Rect InsetToggleFillRect(Rect toggleRect)
  {
    const float inset = 2f;
    return new Rect(
        toggleRect.x + inset,
        toggleRect.y + inset,
        toggleRect.width - inset * 2f,
        toggleRect.height - inset * 2f);
  }

  /// <summary>
  /// ViewEdit card list only. Does not change layout.Pieces or draw order.
  /// Front, then Left, then Right, then all remaining pieces in original order.
  /// </summary>
  private int CompareViewEditPieceDisplayOrder(int indexA, int indexB)
  {
    ViewportPiece pieceA = layout.Pieces[indexA];
    ViewportPiece pieceB = layout.Pieces[indexB];
    int groupA = GetViewEditDisplayFamilyGroup(pieceA);
    int groupB = GetViewEditDisplayFamilyGroup(pieceB);
    if (groupA != groupB)
      return groupA.CompareTo(groupB);

    int distanceA = GetViewEditDisplayDistanceOrder(pieceA);
    int distanceB = GetViewEditDisplayDistanceOrder(pieceB);
    if (distanceA != distanceB)
      return distanceA.CompareTo(distanceB);

    return indexA.CompareTo(indexB);
  }

  private static int GetViewEditDisplayFamilyGroup(ViewportPiece piece)
  {
    if (piece == null)
      return 3;

    if (IsFrontWallF1Card(piece)
        || IsFrontWallF2Card(piece)
        || IsFrontWallF3Card(piece))
    {
      return 0;
    }

    if (IsWallF0LeftPiece(piece)
        || IsWallF1LeftPiece(piece)
        || IsWallF2LeftPiece(piece)
        || IsWallF3LeftPiece(piece)
        || piece.Name == "LeftD3"
        || piece.Name == "Wall D3L2"
        || piece.Name == "LeftS3")
    {
      return 1;
    }

    if (IsWallF0RightPiece(piece)
        || IsWallF1RightPiece(piece)
        || IsWallF2RightPiece(piece)
        || IsWallF3RightPiece(piece)
        || piece.Name == "RightD3"
        || piece.Name == "Wall D3R2"
        || piece.Name == "RightS3")
    {
      return 2;
    }

    return 3;
  }

  private static int GetViewEditDisplayDistanceOrder(ViewportPiece piece)
  {
    if (piece == null)
      return 0;

    if (IsFrontWallF1Card(piece)
        || IsWallF0LeftPiece(piece)
        || IsWallF0RightPiece(piece))
    {
      return 0;
    }

    if (IsFrontWallF2Card(piece)
        || IsWallF1LeftPiece(piece)
        || IsWallF1RightPiece(piece))
    {
      return 1;
    }

    if (IsFrontWallF3Card(piece)
        || IsWallF2LeftPiece(piece)
        || IsWallF2RightPiece(piece))
    {
      return 2;
    }

    if (IsWallF3LeftPiece(piece) || IsWallF3RightPiece(piece))
      return 3;

    if (piece.Name == "LeftD3"
        || piece.Name == "Wall D3L2"
        || piece.Name == "RightD3"
        || piece.Name == "Wall D3R2")
    {
      return 4;
    }

    return 0;
  }

