  private static bool TryGetPieceFamilyLabelColor(
      ViewportPiece piece,
      out Color color)
  {
    color = default;
    if (piece == null || string.IsNullOrEmpty(piece.Name))
      return false;

    switch (piece.Name)
    {
      case "Left0":
      case "LeftF0":
      case "Wall F0Left":
        color = new Color32(0x9D, 0xCA, 0xFF, 0xFF);
        return true;
      case "Left1":
      case "LeftF1":
      case "Wall F1Left":
        color = new Color32(0x7F, 0xD3, 0xFF, 0xFF);
        return true;
      case "Left2":
      case "LeftF2":
      case "Wall F2Left":
        color = new Color32(0x2F, 0xA8, 0xFF, 0xFF);
        return true;
      case "Left3":
      case "LeftF3":
      case "Wall F3Left":
        color = new Color32(0x17, 0x6A, 0xA5, 0xFF);
        return true;
      case "Front1":
      case "FrontF1":
      case "Front Wall F1":
        color = new Color32(0x79, 0xD9, 0x96, 0xFF);
        return true;
      case "Front2":
      case "FrontF2":
      case "Front Wall F2":
        color = new Color32(0x4F, 0xB8, 0x74, 0xFF);
        return true;
      case "Front3":
      case "FrontF3":
      case "Front Wall F3":
        color = new Color32(0x33, 0x89, 0x5A, 0xFF);
        return true;
      case "Right0":
      case "RightF0":
      case "Wall F0Right":
        color = new Color32(0xFF, 0xD1, 0xA1, 0xFF);
        return true;
      case "Right1":
      case "RightF1":
      case "Wall F1Right":
        color = new Color32(0xFF, 0xB8, 0x70, 0xFF);
        return true;
      case "Right2":
      case "RightF2":
      case "Wall F2Right":
        color = new Color32(0xE8, 0x95, 0x45, 0xFF);
        return true;
      case "Right3":
      case "RightF3":
      case "Wall F3Right":
        color = new Color32(0xB9, 0x6A, 0x22, 0xFF);
        return true;
      case "LeftD3":
      case "Wall D3L2":
      case "RightD3":
      case "Wall D3R2":
        color = new Color32(0x9B, 0x6F, 0xD1, 0xFF);
        return true;
      case "LeftS3":
      case "RightS3":
        color = new Color32(0x00, 0xFF, 0xFF, 0xFF);
        return true;
      case "BlackDoorF1":
      case "Black Door Frame Left F1":
      case "Black Door Frame Right F1":
        color = new Color32(0xFF, 0x66, 0xFF, 0xFF);
        return true;
      case "BlackDoorF2":
      case "Black Door Frame Left F2":
      case "Black Door Frame Right F2":
        color = new Color32(0xD8, 0x3F, 0xD8, 0xFF);
        return true;
      case "BlackDoorF3":
      case "Black Door Frame Left F3":
      case "Black Door Frame Right F3":
        color = new Color32(0x9C, 0x2B, 0x9C, 0xFF);
        return true;
      default:
        return false;
    }
  }

  private void SelectPiece(int index)
  {
    if (layout == null || layout.Pieces.Count == 0)
    {
      selectedPieceIndex = 0;
      selectionChangedThisFrame = true;
      SaveSessionPrefs();
      GUI.FocusControl(null);
      return;
    }

    int clamped = Mathf.Clamp(index, 0, layout.Pieces.Count - 1);
    if (clamped != selectedPieceIndex)
      selectionChangedThisFrame = true;

    selectedPieceIndex = clamped;
    SaveSessionPrefs();
    GUI.FocusControl(null);
  }

  private void HandlePreviewFacingKeyboard()
  {
    Event current = Event.current;
    if (current.type != EventType.KeyDown)
      return;

    if (!s_viewEditGlobalNavDispatch && focusedWindow != this)
      return;

    // End/PageDown are reserved ViewEdit turn keys. Do not let a stale
    // TextField/DelayedIntField focus block direction changes.
    DungeonFacing nextFacing;
    KeyCode key = current.keyCode;
    switch (key)
    {
      case KeyCode.End:
        // End is the ViewEdit LEFT-TURN key. Turn 90 degrees left relative
        // to the current facing; do not force an absolute map direction.
        nextFacing = TurnPreviewFacingLeft(previewFacing);
        break;
      case KeyCode.PageDown:
        nextFacing = TurnPreviewFacingRight(previewFacing);
        break;
      default:
        return;
    }

    if (TryTransitionFromStairsTurnInput())
    {
      current.Use();
      return;
    }

    if (nextFacing != previewFacing)
    {
      // Preserve Preview X / Preview Y; only facing changes.
      SwitchPreviewPose(previewX, previewY, nextFacing);
      // End must not refocus the window. Game View repaint and Focus()
      // were trading the keyboard after this key.
      if (!s_viewEditGlobalNavDispatch && key != KeyCode.End)
        TryRefocusPreviewWindow();
    }

    current.Use();
  }

  private void HandlePreviewStrafeKeyboard()
  {
    Event current = Event.current;
    if (current.type != EventType.KeyDown)
      return;

    if (!s_viewEditGlobalNavDispatch && focusedWindow != this)
      return;

    // ViewEdit reserves Left/Right for player-facing-relative strafe.
    // Left moves 90 degrees to the left of the direction arrow; Right moves
    // 90 degrees to its right. Preview Facing itself does not change.
    int localX;
    switch (current.keyCode)
    {
      case KeyCode.LeftArrow:
        localX = -1;
        break;
      case KeyCode.RightArrow:
        localX = 1;
        break;
      default:
        return;
    }

    current.Use();
    TryPreviewNavigateRelative(localX, 0);

    if (!s_viewEditGlobalNavDispatch)
      TryRefocusPreviewWindow();
  }

  private void HandlePreviewMoveKeyboard()
  {
    Event current = Event.current;
    if (current.type != EventType.KeyDown)
      return;

    if (!s_viewEditGlobalNavDispatch && focusedWindow != this)
      return;

    // Arrow keys are dedicated to ViewEdit navigation. Up moves in the
    // direction of the green facing triangle; Down moves exactly opposite it.
    // Both go through TryPreviewNavigateRelative so a stair destination is
    // accepted the same way as the on-screen pad.
    int localY;
    switch (current.keyCode)
    {
      case KeyCode.UpArrow:
        localY = 1;
        break;
      case KeyCode.DownArrow:
        localY = -1;
        break;
      default:
        return;
    }

    current.Use();
    TryPreviewNavigateRelative(0, localY);
    if (!s_viewEditGlobalNavDispatch)
      TryRefocusPreviewWindow();
  }

  private void TryRefocusPreviewWindow()
  {
    // Refocus synchronously. Do not enqueue delayCall focus requests: repeated
    // navigation used to accumulate callbacks and make ViewEdit/GameView trade
    // focus after End/PageDown.
    EditorApplication.delayCall -= RestoreViewEditKeyboardFocus;
    GUI.FocusControl(null);
    GUIUtility.keyboardControl = 0;
    Focus();
  }

  /// <summary>
  /// Compatibility cleanup for callbacks queued by an older script domain.
  /// New navigation does not schedule this method.
  /// </summary>
  private void RestoreViewEditKeyboardFocus()
  {
    EditorApplication.delayCall -= RestoreViewEditKeyboardFocus;
    if (this == null || EditorGUIUtility.editingTextField)
      return;

    Focus();
  }

  private static void RegisterViewEditGlobalNavigation()
  {
    s_viewEditGlobalNavOwners++;
    if (s_viewEditGlobalNavCallbackAdded)
      return;

    AddViewEditGlobalEventHandler(ViewEditGlobalNavHandler);
    AddViewEditBeforeEventProcessedHandler();
    if (!s_gameViewPointerUpdateAdded)
    {
      EditorApplication.update += EnsureGameViewPointerHook;
      s_gameViewPointerUpdateAdded = true;
    }

    EnsureGameViewPointerHook();
    s_viewEditGlobalNavCallbackAdded = true;
  }

  private static void UnregisterViewEditGlobalNavigation()
  {
    s_viewEditGlobalNavOwners--;
    if (s_viewEditGlobalNavOwners > 0)
      return;

    s_viewEditGlobalNavOwners = 0;
    if (!s_viewEditGlobalNavCallbackAdded)
      return;

    RemoveViewEditGlobalEventHandler(ViewEditGlobalNavHandler);
    RemoveViewEditBeforeEventProcessedHandler();
    if (s_gameViewPointerUpdateAdded)
    {
      EditorApplication.update -= EnsureGameViewPointerHook;
      s_gameViewPointerUpdateAdded = false;
    }

    RemoveGameViewPointerHook();
    s_viewEditGlobalNavCallbackAdded = false;
  }

  private static void AddViewEditGlobalEventHandler(
      EditorApplication.CallbackFunction handler)
  {
    EventInfo evt = typeof(EditorApplication).GetEvent(
        "globalEventHandler",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
    if (evt != null)
    {
      evt.GetAddMethod(true)?.Invoke(null, new object[] { handler });
      return;
    }

    FieldInfo field = typeof(EditorApplication).GetField(
        "globalEventHandler",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
    if (field == null)
      return;

    var value = (EditorApplication.CallbackFunction)field.GetValue(null);
    value -= handler;
    value += handler;
    field.SetValue(null, value);
  }

  private static void RemoveViewEditGlobalEventHandler(
      EditorApplication.CallbackFunction handler)
  {
    EventInfo evt = typeof(EditorApplication).GetEvent(
        "globalEventHandler",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
    if (evt != null)
    {
      evt.GetRemoveMethod(true)?.Invoke(null, new object[] { handler });
      return;
    }

    FieldInfo field = typeof(EditorApplication).GetField(
        "globalEventHandler",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
    if (field == null)
      return;

    var value = (EditorApplication.CallbackFunction)field.GetValue(null);
    value -= handler;
    field.SetValue(null, value);
  }

  private static EventInfo GetGuiViewBeforeEventProcessedEvent()
  {
    System.Type guiViewType = typeof(EditorWindow).Assembly.GetType(
        "UnityEditor.GUIView");
    if (guiViewType == null)
      return null;

    return guiViewType.GetEvent(
        "beforeEventProcessed",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
  }

  private static void AddViewEditBeforeEventProcessedHandler()
  {
    EventInfo evt = GetGuiViewBeforeEventProcessedEvent();
    if (evt == null)
      return;

    MethodInfo method = typeof(ViewportLayoutEditor).GetMethod(
        nameof(HandleViewEditBeforeEventProcessed),
        BindingFlags.Static | BindingFlags.NonPublic);
    if (method == null)
      return;

    s_viewEditBeforeEventProcessedHandler = System.Delegate.CreateDelegate(
        evt.EventHandlerType,
        method,
        false);
    if (s_viewEditBeforeEventProcessedHandler == null)
      return;

    evt.GetAddMethod(true)?.Invoke(
        null,
        new object[] { s_viewEditBeforeEventProcessedHandler });
  }

  private static void RemoveViewEditBeforeEventProcessedHandler()
  {
    EventInfo evt = GetGuiViewBeforeEventProcessedEvent();
    if (evt == null || s_viewEditBeforeEventProcessedHandler == null)
      return;

    evt.GetRemoveMethod(true)?.Invoke(
        null,
        new object[] { s_viewEditBeforeEventProcessedHandler });
    s_viewEditBeforeEventProcessedHandler = null;
  }

  private static void HandleViewEditBeforeEventProcessed(
      EventType type,
      KeyCode keyCode,
      EventModifiers modifiers)
  {
    if (type != EventType.KeyDown)
      return;

    if (keyCode == KeyCode.Escape)
    {
      ViewportLayoutEditor window = FindOpenViewEditWindow();
      if (window != null && window.championSheetVisible)
      {
        window.CloseChampionSheetByPlayer();
        Event escapeEvent = Event.current;
        if (escapeEvent != null
            && escapeEvent.type == EventType.KeyDown
            && escapeEvent.keyCode == KeyCode.Escape)
        {
          escapeEvent.Use();
        }
        return;
      }
    }

    // Fast Game View zoom shortcuts.
    // Ctrl + Numpad+ toggles the Game View between 100% and 300%.
    if ((modifiers & EventModifiers.Control) != 0
        && keyCode == KeyCode.KeypadPlus)
    {
      ToggleGameViewZoom100To300();
      Event current = Event.current;
      if (current != null
          && current.type == EventType.KeyDown
          && current.keyCode == keyCode)
      {
        current.Use();
      }
      return;
    }

    if ((modifiers & EventModifiers.Alt) != 0)
    {
      if (keyCode == KeyCode.KeypadPlus)
      {
        SetGameViewZoomScale(3f);
        return;
      }

      if (keyCode == KeyCode.KeypadMinus)
      {
        SetGameViewZoomScale(1f);
        return;
      }
    }

    if (!IsViewEditNavigationKey(keyCode))
      return;

    // End/PageDown can be consumed by the currently focused IMGUI/UI Toolkit
    // control before ViewEdit's normal OnGUI handler sees them. Dispatch these
    // turn keys directly from GUIView.beforeEventProcessed, which runs before
    // the focused control gets a chance to swallow the key.
    if (keyCode == KeyCode.End || keyCode == KeyCode.PageDown)
    {
      if (TryDispatchViewEditTurnKeyDirect(keyCode))
      {
        s_lastPreprocessedTurnKey = keyCode;
        s_lastPreprocessedTurnTime = EditorApplication.timeSinceStartup;
        Event current = Event.current;
        if (current != null
            && current.type == EventType.KeyDown
            && current.keyCode == keyCode)
        {
          current.Use();
        }
      }
      return;
    }

    TryDispatchViewEditGlobalNavigation();
  }


  private static void HandleViewEditGlobalNavigationEvent()
  {
    // GameView.OnGUI invokes globalEventHandler for MouseDown/MouseUp.
    if (TryDispatchViewEditGameViewOnGuiMouse())
      return;

    Event current = Event.current;
    if (current != null
        && current.type == EventType.KeyDown
        && current.keyCode == KeyCode.Escape)
    {
      ViewportLayoutEditor window = FindOpenViewEditWindow();
      if (window != null && window.championSheetVisible)
      {
        window.CloseChampionSheetByPlayer();
        current.Use();
        return;
      }
    }

    if (current != null
        && current.type == EventType.KeyDown
        && current.control
        && current.keyCode == KeyCode.KeypadPlus)
    {
      ToggleGameViewZoom100To300();
      current.Use();
      return;
    }

    if (current != null
        && current.type == EventType.KeyDown
        && current.alt)
    {
      if (current.keyCode == KeyCode.KeypadPlus)
      {
        SetGameViewZoomScale(3f);
        current.Use();
        return;
      }

      if (current.keyCode == KeyCode.KeypadMinus)
      {
        SetGameViewZoomScale(1f);
        current.Use();
        return;
      }
    }

    TryDispatchViewEditGlobalNavigation();
  }

  private static double s_lastGameViewZoomToggleTime = -1.0;

  /// <summary>
  /// Ctrl + Numpad+ toggles Game View zoom between 100% (1x) and 300% (3x).
  /// The tiny debounce prevents Unity's two editor event paths from toggling
  /// the same physical key press twice.
  /// </summary>
  private static void ToggleGameViewZoom100To300()
  {
    double now = EditorApplication.timeSinceStartup;
    if (s_lastGameViewZoomToggleTime >= 0.0
        && now - s_lastGameViewZoomToggleTime < 0.08)
    {
      return;
    }

    s_lastGameViewZoomToggleTime = now;

    float currentScale = GetGameViewZoomScale();
    float targetScale = currentScale >= 2f ? 1f : 3f;
    SetGameViewZoomScale(targetScale);
  }

  private static float GetGameViewZoomScale()
  {
    EditorWindow gameView = FindGameViewWindow();
    if (gameView == null)
      return 1f;

    System.Type gameViewType = gameView.GetType();
    FieldInfo zoomAreaField = gameViewType.GetField(
        "m_ZoomArea",
        BindingFlags.Instance | BindingFlags.NonPublic);
    object zoomArea = zoomAreaField != null
        ? zoomAreaField.GetValue(gameView)
        : null;
    if (zoomArea == null)
      return 1f;

    FieldInfo scaleField = zoomArea.GetType().GetField(
        "m_Scale",
        BindingFlags.Instance | BindingFlags.NonPublic);
    if (scaleField == null)
      return 1f;

    object value = scaleField.GetValue(zoomArea);
    if (value is Vector2 scale)
      return scale.x;
    if (value is float scalar)
      return scalar;

    return 1f;
  }

  /// <summary>
  /// Set the Unity Game View zoom slider to an exact scale. Unity 6 keeps
  /// the public UI on an internal ZoomableArea, so use GameView.SnapZoom
  /// when available and fall back to its private scale field.
  /// </summary>
  private static void SetGameViewZoomScale(float scale)
  {
    if (scale <= 0f)
      return;

    EditorWindow gameView = FindGameViewWindow();
    if (gameView == null)
      return;

    System.Type gameViewType = gameView.GetType();

    MethodInfo snapZoom = gameViewType.GetMethod(
        "SnapZoom",
        BindingFlags.Instance | BindingFlags.NonPublic,
        null,
        new[] { typeof(float) },
        null);
    if (snapZoom != null)
    {
      snapZoom.Invoke(gameView, new object[] { scale });
      gameView.Repaint();
      return;
    }

    FieldInfo zoomAreaField = gameViewType.GetField(
        "m_ZoomArea",
        BindingFlags.Instance | BindingFlags.NonPublic);
    object zoomArea = zoomAreaField != null
        ? zoomAreaField.GetValue(gameView)
        : null;
    if (zoomArea == null)
      return;

    FieldInfo scaleField = zoomArea.GetType().GetField(
        "m_Scale",
        BindingFlags.Instance | BindingFlags.NonPublic);
    if (scaleField == null)
      return;

    scaleField.SetValue(zoomArea, Vector2.one * scale);
    gameView.Repaint();
  }

  /// <summary>
  /// GameView.OnGUI mouse path. Unity 6 still draws Game View through IMGUI
  /// OnGUI, which invokes globalEventHandler for left-button down.
  /// </summary>
  private static bool TryDispatchViewEditGameViewOnGuiMouse()
  {
    Event current = Event.current;
    if (current == null
        || (current.type != EventType.MouseDown && current.type != EventType.MouseUp)
        || current.button != 0
        || Application.isPlaying)
    {
      return false;
    }

    EditorWindow gameView = GetCurrentExecutingGameView();
    if (gameView == null)
      return false;

    if (current.type == EventType.MouseUp)
      return DispatchGameViewChampionEyeRelease(gameView, current.mousePosition, current, null);

    return DispatchGameViewMovementClick(
        gameView,
        current.mousePosition,
        current,
        null);
  }

  private static void EnsureGameViewPointerHook()
  {
    if (Application.isPlaying || s_viewEditGlobalNavOwners <= 0)
    {
      RemoveGameViewPointerHook();
      return;
    }

    EditorWindow gameView = FindGameViewWindow();
    if (gameView == s_hookedGameView && s_gameViewPointerCallbackAdded)
      return;

    RemoveGameViewPointerHook();
    if (gameView == null)
      return;

    UnityEngine.UIElements.VisualElement root = gameView.rootVisualElement;
    if (root == null)
      return;

    root.RegisterCallback(
        GameViewPointerDownHandler,
        UnityEngine.UIElements.TrickleDown.TrickleDown);
    root.RegisterCallback(
        GameViewPointerUpHandler,
        UnityEngine.UIElements.TrickleDown.TrickleDown);
    s_hookedGameView = gameView;
    s_gameViewPointerCallbackAdded = true;
  }

  private static void RemoveGameViewPointerHook()
  {
    if (s_gameViewPointerCallbackAdded && s_hookedGameView != null)
    {
      UnityEngine.UIElements.VisualElement root =
          s_hookedGameView.rootVisualElement;
      if (root != null)
      {
        root.UnregisterCallback(
            GameViewPointerDownHandler,
            UnityEngine.UIElements.TrickleDown.TrickleDown);
        root.UnregisterCallback(
            GameViewPointerUpHandler,
            UnityEngine.UIElements.TrickleDown.TrickleDown);
      }
    }

    s_hookedGameView = null;
    s_gameViewPointerCallbackAdded = false;
  }

    private static void HandleGameViewPointerUp(
      UnityEngine.UIElements.PointerUpEvent evt)
  {
    if (evt == null || evt.button != 0 || Application.isPlaying)
      return;

    EditorWindow gameView = s_hookedGameView;
    if (gameView == null)
      gameView = FindGameViewWindow();
    if (gameView == null)
      return;

    DispatchGameViewChampionEyeRelease(
        gameView,
        evt.position,
        null,
        evt);
  }

private static void HandleGameViewPointerDown(
      UnityEngine.UIElements.PointerDownEvent evt)
  {
    if (evt == null || evt.button != 0 || Application.isPlaying)
      return;

    EditorWindow gameView = s_hookedGameView;
    if (gameView == null)
      gameView = FindGameViewWindow();
    if (gameView == null)
      return;

    DispatchGameViewMovementClick(
        gameView,
        evt.position,
        null,
        evt);
  }

  private static EditorWindow FindGameViewWindow()
  {
    EditorWindow[] windows = Resources.FindObjectsOfTypeAll<EditorWindow>();
    if (windows == null)
      return null;

    for (int i = 0; i < windows.Length; i++)
    {
      EditorWindow window = windows[i];
      if (window != null && window.GetType().FullName == "UnityEditor.GameView")
        return window;
    }

    return null;
  }

  private static bool DispatchGameViewChampionEyeRelease(
      EditorWindow gameView,
      Vector2 windowMouse,
      Event imguiEvent,
      UnityEngine.UIElements.PointerUpEvent pointerEvent)
  {
    ViewportLayoutEditor window = FindOpenViewEditWindow();
    if (window == null
        || !window.championSheetVisible
        || (!window.championEyePressed && !window.championMouthPressed))
    {
      return false;
    }

    if (window.championEyePressed)
    {
      window.championEyePressed = false;
      window.championEyeMoved = false;
      window.championEyeMiddle = true;
    }

    if (window.championMouthPressed)
      window.championMouthPressed = false;

    window.PresentEditModePreviewToGameView();

    if (imguiEvent != null)
      imguiEvent.Use();

    if (pointerEvent != null)
      pointerEvent.StopPropagation();

    if (gameView != null)
      gameView.Repaint();
    window.Repaint();
    RepaintGameViews();
    return true;
  }

  /// <summary>
  /// Shared Game View click dispatch for both UITK PointerDown and GameView
  /// OnGUI / globalEventHandler. Hit-tests the 320x200 movement pad.
  /// </summary>
  private static bool DispatchGameViewMovementClick(
      EditorWindow gameView,
      Vector2 windowMouse,
      Event imguiEvent,
      UnityEngine.UIElements.PointerDownEvent pointerEvent)
  {
    double now = EditorApplication.timeSinceStartup;
    if (now - s_lastGameViewClickTime < 0.05)
      return false;

    ViewportLayoutEditor window = FindOpenViewEditWindow();
    if (window == null || window.layout == null)
      return false;

    bool hasLogical = window.TryGetLogical320x200FromGameView(
        gameView,
        windowMouse,
        out Vector2 logical);

    if (hasLogical
        && window.TryHandleChampionSheetClick(logical.x, logical.y))
    {
      s_lastGameViewClickTime = now;
      if (imguiEvent != null)
        imguiEvent.Use();

      if (pointerEvent != null)
      {
        pointerEvent.StopPropagation();
        UnityEngine.UIElements.VisualElement pointerTarget =
            pointerEvent.currentTarget as UnityEngine.UIElements.VisualElement
            ?? pointerEvent.target as UnityEngine.UIElements.VisualElement;
        if (pointerTarget != null && pointerTarget.focusController != null)
          pointerTarget.focusController.IgnoreEvent(pointerEvent);
      }

      gameView.Repaint();
      window.Repaint();
      RepaintGameViews();
      return true;
    }

    string region = "none";
    if (hasLogical)
      region = GetMovementArrowRegionName(logical.x, logical.y);

    if (region == "none")
      return false;

    s_lastGameViewClickTime = now;
    window.InvokeMovementArrowRegion(region);

    if (imguiEvent != null)
      imguiEvent.Use();

    if (pointerEvent != null)
    {
      pointerEvent.StopPropagation();
      UnityEngine.UIElements.VisualElement pointerTarget =
          pointerEvent.currentTarget as UnityEngine.UIElements.VisualElement
          ?? pointerEvent.target as UnityEngine.UIElements.VisualElement;
      if (pointerTarget != null && pointerTarget.focusController != null)
        pointerTarget.focusController.IgnoreEvent(pointerEvent);
    }

    gameView.Repaint();
    window.Repaint();
    RepaintGameViews();
    return true;
  }

  /// <summary>
  /// Returns the EditorWindow whose OnGUI is currently executing.
  /// </summary>
  private static EditorWindow GetCurrentExecutingGameView()
  {
    const BindingFlags flags =
        BindingFlags.Static | BindingFlags.Instance
        | BindingFlags.Public | BindingFlags.NonPublic;

    System.Type guiViewType = typeof(EditorWindow).Assembly.GetType(
        "UnityEditor.GUIView");
    if (guiViewType != null)
    {
      PropertyInfo currentProperty = guiViewType.GetProperty("current", flags);
      object currentGuiView = currentProperty != null
          ? currentProperty.GetValue(null, null)
          : null;

      if (currentGuiView != null)
      {
        PropertyInfo actualViewProperty = null;
        for (System.Type hostType = currentGuiView.GetType();
             hostType != null && actualViewProperty == null;
             hostType = hostType.BaseType)
        {
          actualViewProperty = hostType.GetProperty(
              "actualView",
              BindingFlags.Instance
                  | BindingFlags.Public
                  | BindingFlags.NonPublic
                  | BindingFlags.DeclaredOnly);
        }

        EditorWindow actualView = actualViewProperty != null
            ? actualViewProperty.GetValue(currentGuiView, null) as EditorWindow
            : null;

        if (actualView != null
            && actualView.GetType().FullName == "UnityEditor.GameView")
        {
          return actualView;
        }
      }
    }

    EditorWindow hovered = mouseOverWindow;
    if (hovered != null
        && hovered.GetType().FullName == "UnityEditor.GameView")
    {
      return hovered;
    }

    EditorWindow focused = focusedWindow;
    if (focused != null
        && focused.GetType().FullName == "UnityEditor.GameView")
    {
      return focused;
    }

    return null;
  }

  /// <summary>
  /// Unity's own GameView conversion: window mouse -> camera render pixels.
  /// Does not require the point to be inside the target, so a miss still logs.
  /// </summary>
  private static bool TryGetGameViewRenderMouse(
      EditorWindow gameView,
      Vector2 mousePosition,
      out Vector2 gamePixel,
      out Vector2 targetSize)
  {
    gamePixel = Vector2.zero;
    targetSize = Vector2.zero;
    if (gameView == null)
      return false;

    System.Type type = gameView.GetType();
    const BindingFlags flags =
        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;

    PropertyInfo offsetProperty = type.GetProperty("gameMouseOffset", flags);
    PropertyInfo scaleProperty = type.GetProperty("gameMouseScale", flags);
    PropertyInfo targetSizeProperty = type.GetProperty("targetRenderSize", flags);

    if (offsetProperty == null
        || scaleProperty == null
        || targetSizeProperty == null)
    {
      return false;
    }

    object offsetValue = offsetProperty.GetValue(gameView, null);
    object scaleValue = scaleProperty.GetValue(gameView, null);
    object sizeValue = targetSizeProperty.GetValue(gameView, null);

    if (!(offsetValue is Vector2 mouseOffset)
        || !(sizeValue is Vector2 reflectedTargetSize)
        || reflectedTargetSize.x <= 0f
        || reflectedTargetSize.y <= 0f)
    {
      return false;
    }

    float mouseScale;
    try
    {
      mouseScale = System.Convert.ToSingle(scaleValue);
    }
    catch
    {
      mouseScale = 0f;
    }

    if (mouseScale <= 0f)
      return false;

    gamePixel = (mousePosition + mouseOffset) * mouseScale;
    targetSize = reflectedTargetSize;
    return true;
  }

  /// <summary>
  /// Maps a Game View window click onto the Edit Mode 320x200 GameplayRoot.
  /// Uses Unity's GameView render-pixel conversion, then the live centered
  /// 320x200 rect already applied in Edit Mode.
  /// </summary>
  private bool TryGetLogical320x200FromGameView(
      EditorWindow gameView,
      Vector2 windowMouse,
      out Vector2 logical)
  {
    logical = new Vector2(-1f, -1f);
    if (gameView == null)
      return false;

    if (!TryGetGameViewRenderMouse(
            gameView,
            windowMouse,
            out Vector2 gamePixel,
            out Vector2 targetSize))
    {
      return false;
    }

    // Edit Mode forces GameplayRoot to a centered 320x200 ConstantPixelSize
    // canvas. Camera pixels therefore contain that 320x200 frame with equal
    // letterboxing; Unity's gameMouseOffset already removed toolbar/zoom.
    logical.x = gamePixel.x - (targetSize.x - PreviewWidth) * 0.5f;
    logical.y = gamePixel.y - (targetSize.y - PreviewHeight) * 0.5f;
    return true;
  }

  /// <summary>
  /// Player-requested exit from the Champion Mirror sheet. CANCEL and Escape
  /// both use this exact path so they close identically and play pop04.wav once.
  /// Automatic closes (pose changes, invalid state) remain silent.
  /// </summary>
  private void CloseChampionSheetByPlayer()
  {
    if (!championSheetVisible)
      return;

    championSheetVisible = false;
    championSheetName = null;
    championEyeMoved = false;
    championEyeMiddle = false;
    championEyePressed = false;
    championMouthPressed = false;
    PlayChampionExitSound();
    SaveSessionPrefs();
    PresentEditModePreviewToGameView();
    Repaint();
  }

  private DungeonAudioSettings GetDungeonAudioSettings()
  {
    if (cachedDungeonAudioSettings != null)
      return cachedDungeonAudioSettings;

    string[] guids = AssetDatabase.FindAssets("t:DungeonAudioSettings");
    if (guids.Length == 0)
      return null;

    string path = AssetDatabase.GUIDToAssetPath(guids[0]);
    cachedDungeonAudioSettings =
        AssetDatabase.LoadAssetAtPath<DungeonAudioSettings>(path);
    return cachedDungeonAudioSettings;
  }

  private float GetChampionExitVolume()
  {
    DungeonAudioSettings settings = GetDungeonAudioSettings();
    return settings != null ? Mathf.Clamp01(settings.championExitVolume) : 1f;
  }

  private float GetChampionResurrectVolume()
  {
    DungeonAudioSettings settings = GetDungeonAudioSettings();
    return settings != null ? Mathf.Clamp01(settings.championResurrectVolume) : 1f;
  }

  private AudioClip GetVolumeAdjustedPreviewClip(
      AudioClip source,
      float volume,
      ref AudioClip cachedPreviewClip,
      ref float cachedPreviewVolume)
  {
    if (source == null)
      return null;

    volume = Mathf.Clamp01(volume);
    if (Mathf.Approximately(volume, 1f))
      return source;

    if (cachedPreviewClip != null
        && Mathf.Approximately(cachedPreviewVolume, volume)
        && cachedPreviewClip.samples == source.samples
        && cachedPreviewClip.channels == source.channels)
    {
      return cachedPreviewClip;
    }

    if (cachedPreviewClip != null)
    {
      Object.DestroyImmediate(cachedPreviewClip);
      cachedPreviewClip = null;
    }

    float[] samples = new float[source.samples * source.channels];
    if (!source.GetData(samples, 0))
    {
      Debug.LogWarning(
          "[ViewportLayoutEditor] Could not read AudioClip samples for Edit Mode volume preview: "
          + source.name);
      return source;
    }

    for (int i = 0; i < samples.Length; i++)
      samples[i] *= volume;

    cachedPreviewClip = AudioClip.Create(
        source.name + "_EditPreview",
        source.samples,
        source.channels,
        source.frequency,
        false);
    cachedPreviewClip.hideFlags = HideFlags.HideAndDontSave;
    cachedPreviewClip.SetData(samples, 0);
    cachedPreviewVolume = volume;
    return cachedPreviewClip;
  }

  private void PlayEditorPreviewClip(AudioClip clip)
  {
    if (clip == null)
      return;

    System.Type audioUtil = typeof(AudioImporter).Assembly.GetType("UnityEditor.AudioUtil");
    if (audioUtil == null)
      return;

    MethodInfo playMethod = audioUtil.GetMethod(
        "PlayPreviewClip",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic,
        null,
        new[] { typeof(AudioClip), typeof(int), typeof(bool) },
        null);

    if (playMethod != null)
    {
      playMethod.Invoke(null, new object[] { clip, 0, false });
      return;
    }

    playMethod = audioUtil.GetMethod(
        "PlayClip",
        BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic,
        null,
        new[] { typeof(AudioClip), typeof(int), typeof(bool) },
        null);
    if (playMethod != null)
      playMethod.Invoke(null, new object[] { clip, 0, false });
  }

  private AudioClip GetChampionExitSoundClip()
  {
    DungeonAudioSettings settings = GetDungeonAudioSettings();
    if (settings != null && settings.championExitSound != null)
      return settings.championExitSound;

    if (cachedChampionExitClip != null)
      return cachedChampionExitClip;

    string[] guids = AssetDatabase.FindAssets("pop04 t:AudioClip");
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      if (!string.Equals(
              Path.GetFileName(path),
              ChampionExitSoundAssetFileName,
              System.StringComparison.OrdinalIgnoreCase))
      {
        continue;
      }

      cachedChampionExitClip = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
      if (cachedChampionExitClip != null)
        return cachedChampionExitClip;
    }

    Debug.LogWarning(
        "[ViewportLayoutEditor] Champion exit sound not found in Assets: "
        + ChampionExitSoundAssetFileName);
    return null;
  }

  private void PlayChampionExitSound()
  {
    AudioClip clip = GetChampionExitSoundClip();
    float volume = GetChampionExitVolume();
    if (clip == null || volume <= 0f)
      return;

    if (Application.isPlaying)
    {
      GameObject soundObject = new GameObject("ChampionExit_pop04");
      soundObject.hideFlags = HideFlags.HideAndDontSave;
      AudioSource source = soundObject.AddComponent<AudioSource>();
      source.playOnAwake = false;
      source.spatialBlend = 0f;
      source.volume = volume;
      source.clip = clip;
      source.Play();
      Object.Destroy(soundObject, Mathf.Max(0.1f, clip.length + 0.1f));
      return;
    }

    AudioClip previewClip = GetVolumeAdjustedPreviewClip(
        clip,
        volume,
        ref cachedChampionExitPreviewClip,
        ref cachedChampionExitPreviewVolume);
    PlayEditorPreviewClip(previewClip);
  }


  private AudioClip GetChampionResurrectSoundClip()
  {
    DungeonAudioSettings settings = GetDungeonAudioSettings();
    if (settings != null && settings.championResurrectSound != null)
      return settings.championResurrectSound;

    if (cachedChampionResurrectClip != null)
      return cachedChampionResurrectClip;

    string[] guids = AssetDatabase.FindAssets("ResurrectSnd t:AudioClip");
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      if (!string.Equals(
              Path.GetFileName(path),
              ChampionResurrectSoundAssetFileName,
              System.StringComparison.OrdinalIgnoreCase))
      {
        continue;
      }

      cachedChampionResurrectClip = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
      if (cachedChampionResurrectClip != null)
        return cachedChampionResurrectClip;
    }

    Debug.LogWarning(
        "[ViewportLayoutEditor] Champion resurrect sound not found in Assets: "
        + ChampionResurrectSoundAssetFileName);
    return null;
  }

  private void PlayChampionResurrectSound()
  {
    AudioClip clip = GetChampionResurrectSoundClip();
    float volume = GetChampionResurrectVolume();
    if (clip == null || volume <= 0f)
      return;

    if (Application.isPlaying)
    {
      GameObject soundObject = new GameObject("ChampionResurrect_ResurrectSnd");
      soundObject.hideFlags = HideFlags.HideAndDontSave;
      AudioSource source = soundObject.AddComponent<AudioSource>();
      source.playOnAwake = false;
      source.spatialBlend = 0f;
      source.volume = volume;
      source.clip = clip;
      source.Play();
      Object.Destroy(soundObject, Mathf.Max(0.1f, clip.length + 0.1f));
      return;
    }

    AudioClip previewClip = GetVolumeAdjustedPreviewClip(
        clip,
        volume,
        ref cachedChampionResurrectPreviewClip,
        ref cachedChampionResurrectPreviewVolume);
    PlayEditorPreviewClip(previewClip);
  }


  /// <summary>
  /// Single Champion Mirror click path. A click on the current D1/F1 front
  /// Champion Mirror opens CharacterSheet_224x136.png. No legacy F1 click
  /// handler or old Zed-screen path is used. A later click, or a pose change,
  /// returns to the dungeon view.
  /// </summary>
  private bool TryHandleChampionSheetClick(float logicalX, float logicalY)
  {
    bool insideGame =
        logicalX >= 0f && logicalX < PreviewWidth
        && logicalY >= 0f && logicalY < PreviewHeight;
    if (!insideGame)
      return false;

    if (championSheetVisible)
    {
      // Character Sheet eye icon: exact 16x16 screen hitbox.
      // Mouse-down shows Eye_moved_16x16.png. Mouse release is handled by
      // the Game View MouseUp/PointerUp path and switches to Eye_middle_16x16.png.
      const float eyeX = 12f;
      const float eyeY = 46f;
      const float eyeWidth = 16f;
      const float eyeHeight = 16f;
      bool clickedEye =
          logicalX >= eyeX && logicalX < eyeX + eyeWidth
          && logicalY >= eyeY && logicalY < eyeY + eyeHeight;
      if (clickedEye)
      {
        championEyePressed = true;
        championEyeMoved = true;
        championEyeMiddle = false;
        championMouthPressed = false;
        PresentEditModePreviewToGameView();
        Repaint();
        return true;
      }

      // Character Sheet mouth symbol. While the left mouse button is held
      // on the mouth, show FOOD and WATER labels as runtime overlays.
      // Mouse release is handled by the same Game View MouseUp/PointerUp path
      // used by the eye, which hides these labels again.
      const float mouthX = 59f;
      const float mouthY = 47f;
      const float mouthWidth = 16f;
      const float mouthHeight = 16f;
      bool clickedMouth =
          logicalX >= mouthX && logicalX < mouthX + mouthWidth
          && logicalY >= mouthY && logicalY < mouthY + mouthHeight;
      if (clickedMouth)
      {
        championMouthPressed = true;
        championEyePressed = false;
        championEyeMoved = false;
        championEyeMiddle = false;
        PresentEditModePreviewToGameView();
        Repaint();
        return true;
      }

      // Resurrect_Reincarnate_116x73.png is drawn at screen X=103, Y=85.
      // Confirmed RESURRECT hitbox: X=103..159, Y=85..143 (57x59).
      // This test only plays ResurrectSnd.wav; it does not change champion state yet.
      const float resurrectX = 103f;
      const float resurrectY = 85f;
      const float resurrectWidth = 57f;
      const float resurrectHeight = 59f;

      bool clickedResurrect =
          logicalX >= resurrectX && logicalX < resurrectX + resurrectWidth
          && logicalY >= resurrectY && logicalY < resurrectY + resurrectHeight;

      if (clickedResurrect)
      {
        PlayChampionResurrectSound();
        return true;
      }

      // Its CANCEL strip occupies local Y=60..72, therefore screen
      // X=103..218 and Y=145..157. Only a click inside that exact
      // 116x13 pixel strip closes the Champion Mirror view. Other clicks
      // are consumed here so they cannot move the party while this view is open.
      const float cancelX = 103f;
      const float cancelY = 145f;
      const float cancelWidth = 116f;
      const float cancelHeight = 13f;

      bool clickedCancel =
          logicalX >= cancelX && logicalX < cancelX + cancelWidth
          && logicalY >= cancelY && logicalY < cancelY + cancelHeight;

      if (clickedCancel)
        CloseChampionSheetByPlayer();

      return true;
    }

    if (!TryGetClickedChampionMirror(logicalX, logicalY, out string championName))
      return false;

    if (recruitedChampionNames == null)
      recruitedChampionNames = new List<string>(4);

    // In Edit Mode this is a calibration/inspection selection, not a real
    // gameplay recruitment. Keep exactly one current test Champion in party
    // slot 1 so we can freely inspect every mirror without ever filling the
    // four-Champion party. Future Play Mode keeps the real four-member cap.
    if (!EditorApplication.isPlaying)
    {
      recruitedChampionNames.Clear();
      recruitedChampionNames.Add(championName);
    }
    else
    {
      // Recruit first, then open Character Sheet mode. This guarantees that the
      // first frame of the Character Sheet can always resolve party slot 1.
      bool alreadyRecruited = recruitedChampionNames.Exists(
          name => string.Equals(
              name, championName, System.StringComparison.OrdinalIgnoreCase));
      if (!alreadyRecruited)
      {
        if (recruitedChampionNames.Count >= 4)
        {
          Debug.LogError(
              "[ViewportLayoutEditor] ERROR: Cannot recruit more than 4 Champions.");
          return true;
        }

        recruitedChampionNames.Add(championName);
      }
    }

    championSheetName = championName;
    championSheetVisible = true;
    championEyeMoved = false;
    championEyeMiddle = false;
    championEyePressed = false;
    championMouthPressed = false;
    SaveSessionPrefs();

    PresentEditModePreviewToGameView();
    Repaint();
    return true;
  }

  // Hit-test only. This method does not select an image or invoke any legacy
  // F1 Champion action; it only identifies which visible front mirror was hit.
  private bool TryGetClickedChampionMirror(
      float logicalX,
      float logicalY,
      out string championName)
  {
    championName = null;
    int frameTop =
        PreviewHeight - ChampionMirrorD1FrontY - ChampionMirrorD1FrontHeight;
    if (logicalX < ChampionMirrorD1FrontX
        || logicalX >= ChampionMirrorD1FrontX + ChampionMirrorD1FrontWidth
        || logicalY < frameTop
        || logicalY >= frameTop + ChampionMirrorD1FrontHeight)
    {
      return false;
    }

    return TryGetCurrentD1FrontChampion(out championName);
  }

  private void SaveChampionPartySession()
  {
    EditorPrefs.SetBool(PrefsChampionSheetVisibleKey, championSheetVisible);
    EditorPrefs.SetString(
        PrefsChampionSheetNameKey,
        championSheetName ?? string.Empty);

    if (recruitedChampionNames == null || recruitedChampionNames.Count == 0)
    {
      EditorPrefs.SetString(PrefsRecruitedChampionsKey, string.Empty);
      return;
    }

    string[] names = recruitedChampionNames.ToArray();
    EditorPrefs.SetString(
        PrefsRecruitedChampionsKey,
        string.Join("\n", names));
  }

  private void RestoreChampionPartySession()
  {
    if (recruitedChampionNames == null)
      recruitedChampionNames = new List<string>(4);

    if (EditorPrefs.HasKey(PrefsRecruitedChampionsKey))
    {
      string saved = EditorPrefs.GetString(
          PrefsRecruitedChampionsKey,
          string.Empty);
      if (!string.IsNullOrEmpty(saved))
      {
        recruitedChampionNames.Clear();
        string[] parts = saved.Split('\n');
        for (int i = 0; i < parts.Length && recruitedChampionNames.Count < 4; i++)
        {
          if (!string.IsNullOrEmpty(parts[i]))
            recruitedChampionNames.Add(parts[i]);
        }
      }
    }

    if (EditorPrefs.HasKey(PrefsChampionSheetNameKey))
    {
      string savedName = EditorPrefs.GetString(
          PrefsChampionSheetNameKey,
          string.Empty);
      if (!string.IsNullOrEmpty(savedName))
        championSheetName = savedName;
    }

    if (EditorPrefs.HasKey(PrefsChampionSheetVisibleKey))
    {
      championSheetVisible = EditorPrefs.GetBool(
          PrefsChampionSheetVisibleKey,
          championSheetVisible);
    }

    if (championSheetVisible)
      EnsureOpenCharacterSheetHasPartySlot1();
  }

  // The open sheet must have party slot 1 before any Character Sheet pixels
  // are composed. A domain reload keeps the sheet open and can restore an
  // empty party list. Slot 1 is the sheet champion, otherwise the D1 mirror
  // still in front of the party.
  private void EnsureOpenCharacterSheetHasPartySlot1()
  {
    if (!championSheetVisible)
      return;

    if (recruitedChampionNames == null)
      recruitedChampionNames = new List<string>(4);

    if (recruitedChampionNames.Count > 0)
      return;

    if (!string.IsNullOrEmpty(championSheetName))
    {
      recruitedChampionNames.Add(championSheetName);
      SaveChampionPartySession();
      return;
    }

    EnsurePreviewMiniMapLoaded();
    if (previewChampionMirrors == null || previewChampionMirrors.Length == 0)
      return;

    if (TryGetCurrentD1FrontChampion(out string frontChampion)
        && !string.IsNullOrEmpty(frontChampion))
    {
      championSheetName = frontChampion;
      recruitedChampionNames.Add(frontChampion);
      SaveChampionPartySession();
      return;
    }

    championSheetVisible = false;
    SaveChampionPartySession();
  }

  /// <summary>
  /// Dedicated Character Sheet renderer. This is intentionally independent
  /// from every Champion Mirror / dungeon-depth render path.
  /// </summary>
  private void ComposeCharacterSheetModePreview(Color32[] pixels)
  {
    if (pixels == null || pixels.Length != PreviewWidth * PreviewHeight)
      return;

    // Character Sheet mode uses its own UI hierarchy, completely separate
    // from Champion Mirror and dungeon rendering.
    // 1) Fill the complete 320x200 preview magenta.
    Color32 magenta = new Color32(255, 0, 255, 255);
    for (int i = 0; i < pixels.Length; i++)
      pixels[i] = magenta;

    // 2) Draw a solid grey panel at screen X=0, Y=33, size 224x136.
    Color32 panelGrey = new Color32(73, 73, 73, 255);
    const int panelLeft = 0;
    const int panelTop = 33;
    for (int screenY = panelTop; screenY < panelTop + DungeonViewportHeight; screenY++)
    {
      if (screenY < 0 || screenY >= PreviewHeight)
        continue;

      int destinationY = PreviewHeight - 1 - screenY;
      int destinationRow = destinationY * PreviewWidth + panelLeft;
      for (int x = 0; x < DungeonViewportWidth; x++)
        pixels[destinationRow + x] = panelGrey;
    }

    // 3) Draw Champions_Background_67x29 at screen X=0, Y=0.
    Texture2D statusBackground = GetChampionsBackgroundTexture();
    if (statusBackground != null)
    {
      const int statusLeft = 0;
      const int statusTop = 0;
      const int statusWidth = 67;
      const int statusHeight = 29;
      Color32[] statusSource = statusBackground.GetPixels32();
      for (int sourceY = 0; sourceY < statusHeight; sourceY++)
      {
        int screenY = statusTop + (statusHeight - 1 - sourceY);
        if (screenY < 0 || screenY >= PreviewHeight)
          continue;

        int destinationY = PreviewHeight - 1 - screenY;
        int sourceRow = sourceY * statusWidth;
        int destinationRow = destinationY * PreviewWidth + statusLeft;
        System.Array.Copy(
            statusSource, sourceRow, pixels, destinationRow, statusWidth);
      }
    }

    // 4) Draw CharacterSheet_224x136 at screen X=0, Y=33.
    // STRICT: no fallback asset and no silent skip. If the exact expected asset
    // cannot be loaded as 224x136, show an explicit ERROR and stop composing
    // the Character Sheet UI.
    Texture2D sheet = GetCharacterSheetTexture();
    if (sheet == null)
    {
      PaintCharacterSheetError(
          pixels,
          "ERROR CHARACTER SHEET");
      return;
    }

    const int screenLeft = 0;
    const int screenTop = 33;
    Color32[] source = sheet.GetPixels32();
    for (int sourceY = 0; sourceY < DungeonViewportHeight; sourceY++)
    {
      int screenY = screenTop + (DungeonViewportHeight - 1 - sourceY);
      if (screenY < 0 || screenY >= PreviewHeight)
        continue;

      int destinationY = PreviewHeight - 1 - screenY;
      int sourceRow = sourceY * DungeonViewportWidth;
      int destinationRow = destinationY * PreviewWidth + screenLeft;
      for (int x = 0; x < DungeonViewportWidth; x++)
      {
        Color32 sourcePixel = source[sourceRow + x];
        if (sourcePixel.a == 0)
          continue;

        int destinationIndex = destinationRow + x;
        if (sourcePixel.a == 255)
        {
          pixels[destinationIndex] = sourcePixel;
          continue;
        }

        Color32 destinationPixel = pixels[destinationIndex];
        int alpha = sourcePixel.a;
        int inverseAlpha = 255 - alpha;
        pixels[destinationIndex] = new Color32(
            (byte)((sourcePixel.r * alpha + destinationPixel.r * inverseAlpha + 127) / 255),
            (byte)((sourcePixel.g * alpha + destinationPixel.g * inverseAlpha + 127) / 255),
            (byte)((sourcePixel.b * alpha + destinationPixel.b * inverseAlpha + 127) / 255),
            255);
      }
    }

    // 5) Draw the first recruited Champion portrait OVER Champions_Background_67x29.
    // Party slot 1 is screen X=7, Y=0. Strict: no silent skip.
    // Domain reload restores the open sheet and can restore an empty party.
    // Slot 1 is the sheet champion, then the D1 mirror still in front.
    EnsureOpenCharacterSheetHasPartySlot1();
    if (recruitedChampionNames == null || recruitedChampionNames.Count == 0)
    {
      championSheetVisible = false;
      return;
    }

    string firstChampionName = recruitedChampionNames[0];
    HeroDefinition firstHero = HeroDatabase.GetByName(firstChampionName);
    if (firstHero == null)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Recruited Champion definition not found: "
          + firstChampionName);
      PaintCharacterSheetError(pixels, "ERROR CHAMPION PORTRAIT");
    }
    else
    {
      PaintChampionSheetPortrait(pixels, firstHero);
    }

    // 6) Paint the selected Champion data and starting equipment.
    // This is the generic Character Sheet path: HeroDefinition.StartingItems
    // is resolved into equipment slots (hand/torso/legs/etc.) and rendered
    // over the transparent CharacterSheet layout. IAIDO therefore receives
    // his Samurai Sword, Ghi and Ghi Trousers from champion data; there is no
    // IAIDO-specific draw branch here.
    PaintChampionSheetStats(pixels);

    // Eye interaction overlay. The normal eye remains part of the static
    // CharacterSheet PNG; only after the player clicks it do we place the
    // moved-eye PNG 1:1 over the same 16x16 pixels.
    PaintChampionMovedEyeOverlay(pixels);
    PaintChampionMiddleEyeOverlay(pixels);

    // Eye-hold detail panel temporarily replaces the recruitment artwork.
    // On mouse release the panel disappears and the 116x73 recruitment PNG
    // is restored exactly as before.
    if (championEyePressed)
      PaintChampionEyeStatsPanel(pixels);
    else if (championMouthPressed)
      PaintChampionFoodWaterPanel(pixels);
    else
      PaintResurrectReincarnateOverlay(pixels);
  }

  // Worn-slot rectangles on Inventory_224x136. Screen Y is local Y + 33.
  // Order: head, neck, torso, legs, feet, weapon hand, left hand, quiver.
  private static readonly int[] ChampionSheetEquipSlotXY =
  {
    5, 12,
    33, 25,
    33, 45,
    33, 65,
    33, 85,
    61, 52,
    5, 32,
    5, 52
  };

  private const int ChampionSheetSlotSize = 18;
  private const int ChampionSheetInventoryScreenTop = 33;
  private const int ChampionSheetPortraitX = 7;
  private const int ChampionSheetPortraitScreenTop = 0;
  private const int ChampionSheetPortraitWidth = 32;
  private const int ChampionSheetPortraitHeight = 29;

  // The 320x200 image is the shared sheet layout. The clicked champion's
  // name, health, stamina, mana, and load are drawn over it.
  // Stamina is stored in raw units and shown divided by 10.
  // Load is the sum of that champion's carried-item weights.
  // Max load is (8 * Strength + 100) tenths of a kilogram.
  // The sheet prints that maximum as a whole kilogram, rounded up.
  // IAIDO is 444 tenths (44.4 kg); the original (10,4) North sheet
  // shows 45. An exact multiple such as 460 tenths stays 46.
  private void PaintChampionSheetStats(Color32[] pixels)
  {
    PaintChampionSheetName(pixels);
    ClearChampionSheetEquipment(pixels);
    HeroDefinition hero = HeroDatabase.GetByName(championSheetName);
    PaintChampionSheetPortrait(pixels, hero);
    PaintChampionSheetEquipment(pixels, hero);
    if (hero == null || hero.Resources == null || hero.Attributes == null)
      return;

    int health = hero.Resources.Health;
    int stamina = hero.Resources.Stamina / 10;
    int mana = hero.Resources.Mana;
    int loadTenths = 0;
    if (hero.StartingItems != null)
    {
      for (int i = 0; i < hero.StartingItems.Count; i++)
      {
        HeroStartingItem item = hero.StartingItems[i];
        if (item == null)
          continue;
        int count = item.ChargeCount > 0 ? item.ChargeCount : 1;
        loadTenths += item.WeightTenths * count;
      }
    }

    int maxLoadTenths = hero.Attributes.Strength * 8 + 100;
    int maxLoadKilograms = (maxLoadTenths + 9) / 10;

    string healthText = health + "/" + health;
    string staminaText = stamina + "/" + stamina;
    string manaText = mana + "/" + mana;
    string loadText =
        (loadTenths / 10) + "." + (loadTenths % 10)
        + "/" + maxLoadKilograms;

    // CharacterSheet_224x136.png is intentionally transparent. Therefore the
    // complete status block is runtime UI and must be painted here rather than
    // expected to exist in the PNG. Clear the full text band first so stale
    // pixels from a previously selected champion can never survive.
    Color32 panel = new Color32(73, 73, 73, 255);
    FillChampionSheetRect(pixels, 0, 143, 224, 23, panel);

    Dictionary<char, Color32[]> statusGlyphs = BuildChampionSheetStatusGlyphs();
    DrawChampionSheetText(pixels, statusGlyphs, 4, 145, "HEALTH");
    DrawChampionSheetText(pixels, statusGlyphs, 4, 153, "STAMINA");
    DrawChampionSheetText(pixels, statusGlyphs, 4, 161, "MANA");
    DrawChampionSheetText(pixels, statusGlyphs, 128, 161, "LOAD");

    DrawChampionSheetText(pixels, statusGlyphs, 61, 145, healthText);
    DrawChampionSheetText(pixels, statusGlyphs, 61, 153, staminaText);
    DrawChampionSheetText(pixels, statusGlyphs, 61, 161, manaText);
    DrawChampionSheetText(pixels, statusGlyphs, 160, 161, loadText);
    DrawChampionSheetText(pixels, statusGlyphs, 208, 161, "KG");
  }

  private void PaintChampionEyeStatsPanel(Color32[] pixels)
  {
    if (pixels == null || pixels.Length != PreviewWidth * PreviewHeight)
      return;

    HeroDefinition hero = HeroDatabase.GetByName(championSheetName);
    if (hero == null || hero.Attributes == null)
      return;

    // Same 116x73 screen rectangle as the Resurrect/Reincarnate panel.
    // Coordinates are screen-top based, matching the original 320x200 view.
    const int panelX = 103;
    const int panelY = 85;
    const int panelWidth = 116;
    const int panelHeight = 73;

    Color32 panel = new Color32(73, 73, 73, 255);
    Color32 border = new Color32(109, 109, 109, 255);
    FillChampionSheetRect(pixels, panelX, panelY, panelWidth, panelHeight, panel);
    FillChampionSheetRect(pixels, panelX, panelY, panelWidth, 1, border);
    FillChampionSheetRect(pixels, panelX, panelY + panelHeight - 1, panelWidth, 1, border);
    FillChampionSheetRect(pixels, panelX, panelY, 1, panelHeight, border);
    FillChampionSheetRect(pixels, panelX + panelWidth - 1, panelY, 1, panelHeight, border);

    Dictionary<char, Color32[]> glyphs = BuildChampionSheetStatusGlyphs();

    // The original eye panel prints the champion's non-zero class ranks first.
    // Hero skill arrays store the current base-class level as their highest
    // sub-skill level. IAIDO therefore resolves to APPRENTICE FIGHTER (3)
    // and NOVICE PRIEST (2), matching the original reference screenshot.
    int rankY = 88;
    int ranksDrawn = 0;
    ranksDrawn += DrawChampionRankLine(pixels, glyphs, hero.Skills != null ? hero.Skills.Fighter : null, "FIGHTER", rankY + ranksDrawn * 8);
    ranksDrawn += DrawChampionRankLine(pixels, glyphs, hero.Skills != null ? hero.Skills.Ninja : null, "NINJA", rankY + ranksDrawn * 8);
    ranksDrawn += DrawChampionRankLine(pixels, glyphs, hero.Skills != null ? hero.Skills.Priest : null, "PRIEST", rankY + ranksDrawn * 8);
    ranksDrawn += DrawChampionRankLine(pixels, glyphs, hero.Skills != null ? hero.Skills.Wizard : null, "WIZARD", rankY + ranksDrawn * 8);

    // Attribute block. Current and maximum are identical for the initial
    // champion definitions; later gameplay can replace either side with live
    // values without changing the layout.
    const int labelX = 105;
    const int currentX = 181;
    const int maximumX = 201;
    int statY = ranksDrawn <= 2 ? 110 : 110 + (ranksDrawn - 2) * 6;
    DrawChampionAttributeLine(pixels, glyphs, "STRENGTH", hero.Attributes.Strength, hero.Attributes.Strength, labelX, currentX, maximumX, statY + 0);
    DrawChampionAttributeLine(pixels, glyphs, "DEXTERITY", hero.Attributes.Dexterity, hero.Attributes.Dexterity, labelX, currentX, maximumX, statY + 8);
    DrawChampionAttributeLine(pixels, glyphs, "WISDOM", hero.Attributes.Wisdom, hero.Attributes.Wisdom, labelX, currentX, maximumX, statY + 16);
    DrawChampionAttributeLine(pixels, glyphs, "VITALITY", hero.Attributes.Vitality, hero.Attributes.Vitality, labelX, currentX, maximumX, statY + 24);
    DrawChampionAttributeLine(pixels, glyphs, "ANTI-MAGIC", hero.Attributes.AntiMagic, hero.Attributes.AntiMagic, labelX, currentX, maximumX, statY + 32);
    DrawChampionAttributeLine(pixels, glyphs, "ANTI-FIRE", hero.Attributes.AntiFire, hero.Attributes.AntiFire, labelX, currentX, maximumX, statY + 40);
  }

  private int DrawChampionRankLine(
      Color32[] pixels,
      Dictionary<char, Color32[]> glyphs,
      int[] levels,
      string className,
      int screenTop)
  {
    int level = 0;
    if (levels != null)
    {
      for (int i = 0; i < levels.Length; i++)
        if (levels[i] > level)
          level = levels[i];
    }

    if (level <= 0)
      return 0;

    DrawChampionSheetText(
        pixels,
        glyphs,
        105,
        screenTop,
        GetChampionRankName(level) + " " + className);
    return 1;
  }

  private static string GetChampionRankName(int level)
  {
    switch (level)
    {
      case 1: return "NEOPHYTE";
      case 2: return "NOVICE";
      case 3: return "APPRENTICE";
      case 4: return "JOURNEYMAN";
      case 5: return "CRAFTSMAN";
      case 6: return "ARTISAN";
      case 7: return "ADEPT";
      case 8: return "EXPERT";
      case 9: return "LO MASTER";
      case 10: return "UM MASTER";
      case 11: return "ON MASTER";
      case 12: return "EE MASTER";
      case 13: return "PAL MASTER";
      case 14: return "MON MASTER";
      default: return "ARCHMASTER";
    }
  }

  private void DrawChampionAttributeLine(
      Color32[] pixels,
      Dictionary<char, Color32[]> glyphs,
      string label,
      int current,
      int maximum,
      int labelX,
      int currentX,
      int maximumX,
      int screenTop)
  {
    DrawChampionSheetText(pixels, glyphs, labelX, screenTop, label);
    DrawChampionSheetText(pixels, glyphs, currentX, screenTop, current.ToString());
    DrawChampionSheetText(pixels, glyphs, maximumX, screenTop, maximum.ToString());
  }

  private static Dictionary<char, Color32[]> BuildChampionSheetStatusGlyphs()
  {
    Dictionary<char, Color32[]> glyphs = new Dictionary<char, Color32[]>();

    // Fixed 5x5 character-sheet font. Each glyph is written directly into the
    // 320x200 pixel buffer: no scaling, smoothing, bearing correction, or
    // runtime font substitution can change the status numbers.
    AddChampionSheetPatternGlyph(glyphs, '0', ".###." + "#...#" + "#...#" + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, '1', "..#.." + ".##.." + "..#.." + "..#.." + ".###.");
    AddChampionSheetPatternGlyph(glyphs, '2', ".###." + "....#" + ".###." + "#...." + "#####");
    AddChampionSheetPatternGlyph(glyphs, '3', "####." + "....#" + ".###." + "....#" + "####.");
    AddChampionSheetPatternGlyph(glyphs, '4', "#...#" + "#...#" + "#####" + "....#" + "....#");
    AddChampionSheetPatternGlyph(glyphs, '5', "#####" + "#...." + "####." + "....#" + "####.");
    AddChampionSheetPatternGlyph(glyphs, '6', ".###." + "#...." + "####." + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, '7', "#####" + "....#" + "...#." + "..#.." + ".#...");
    AddChampionSheetPatternGlyph(glyphs, '8', ".###." + "#...#" + ".###." + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, '9', ".###." + "#...#" + ".####" + "....#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, '/', "....#" + "...#." + "..#.." + ".#..." + "#....");
    AddChampionSheetPatternGlyph(glyphs, '.', "....." + "....." + "....." + "....." + "..#..");
    AddChampionSheetPatternGlyph(glyphs, ',', "....." + "....." + "....." + "..#.." + ".#...");

    AddChampionSheetPatternGlyph(glyphs, 'A', ".###." + "#...#" + "#####" + "#...#" + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'D', "####." + "#...#" + "#...#" + "#...#" + "####.");
    AddChampionSheetPatternGlyph(glyphs, 'E', "#####" + "#...." + "####." + "#...." + "#####");
    AddChampionSheetPatternGlyph(glyphs, 'G', ".###." + "#...." + "#.###" + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, 'H', "#...#" + "#...#" + "#####" + "#...#" + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'I', "#####" + "..#.." + "..#.." + "..#.." + "#####");
    AddChampionSheetPatternGlyph(glyphs, 'K', "#...#" + "#..#." + "###.." + "#..#." + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'L', "#...." + "#...." + "#...." + "#...." + "#####");
    AddChampionSheetPatternGlyph(glyphs, 'M', "#...#" + "##.##" + "#.#.#" + "#...#" + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'N', "#...#" + "##..#" + "#.#.#" + "#..##" + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'O', ".###." + "#...#" + "#...#" + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, 'P', "####." + "#...#" + "####." + "#...." + "#....");
    AddChampionSheetPatternGlyph(glyphs, 'R', "####." + "#...#" + "####." + "#..#." + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'S', ".####" + "#...." + ".###." + "....#" + "####.");
    AddChampionSheetPatternGlyph(glyphs, 'U', "#...#" + "#...#" + "#...#" + "#...#" + ".###.");
    AddChampionSheetPatternGlyph(glyphs, 'W', "#...#" + "#...#" + "#.#.#" + "##.##" + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'T', "#####" + "..#.." + "..#.." + "..#.." + "..#..");
    AddChampionSheetPatternGlyph(glyphs, 'C', ".####" + "#...." + "#...." + "#...." + ".####");
    AddChampionSheetPatternGlyph(glyphs, 'F', "#####" + "#...." + "####." + "#...." + "#....");
    AddChampionSheetPatternGlyph(glyphs, 'V', "#...#" + "#...#" + "#...#" + ".#.#." + "..#..");
    AddChampionSheetPatternGlyph(glyphs, 'X', "#...#" + ".#.#." + "..#.." + ".#.#." + "#...#");
    AddChampionSheetPatternGlyph(glyphs, 'Y', "#...#" + ".#.#." + "..#.." + "..#.." + "..#..");
    AddChampionSheetPatternGlyph(glyphs, '-', "....." + "....." + "#####" + "....." + ".....");

    return glyphs;
  }

  private void DrawChampionSheetBitmapText(
      Color32[] pixels,
      string text,
      int visibleX,
      int visibleTop,
      Color32 color)
  {
    if (pixels == null || string.IsNullOrEmpty(text))
      return;

    DungeonBitmapFont bitmapFont = FindEditModeBitmapFont();
    if (bitmapFont == null)
      return;

    // DungeonBitmapFont has the same two-pixel left bearing used by the
    // champion-name renderer. Coordinates here describe the visible ink,
    // matching the 320x200 original reference image.
    const int glyphLeftBearing = 2;
    bitmapFont.DrawText(
        pixels,
        PreviewWidth,
        PreviewHeight,
        text,
        visibleX - glyphLeftBearing,
        PreviewHeight - visibleTop - DungeonBitmapFont.DebugGlyphHeight,
        color,
        0,
        0,
        PreviewWidth,
        PreviewHeight,
        6);
  }

  private const int ChampionSheetGlyphWidth = 5;
  private const int ChampionSheetGlyphHeight = 5;
  private const int ChampionSheetGlyphAdvance = 6;

  private bool TryCaptureChampionSheetGlyphs(
      Color32[] pixels,
      out Dictionary<char, Color32[]> glyphs)
  {
    glyphs = new Dictionary<char, Color32[]>();
    // Digits and marks already drawn on the layout image.
    CaptureChampionSheetGlyph(pixels, glyphs, '6', 61, 145);
    CaptureChampionSheetGlyph(pixels, glyphs, '0', 67, 145);
    CaptureChampionSheetGlyph(pixels, glyphs, '/', 73, 145);
    CaptureChampionSheetGlyph(pixels, glyphs, '1', 61, 161);
    CaptureChampionSheetGlyph(pixels, glyphs, '9', 160, 161);
    CaptureChampionSheetGlyph(pixels, glyphs, '.', 166, 161);
    CaptureChampionSheetGlyph(pixels, glyphs, '8', 172, 161);
    CaptureChampionSheetGlyph(pixels, glyphs, '4', 190, 161);
    CaptureChampionSheetGlyph(pixels, glyphs, '2', 196, 161);
    AddChampionSheetPatternGlyph(
        glyphs, '3', ".###." + "....#" + "..##." + "....#" + ".###.");
    // Original DOS 5, measured from the (10,4) North stamina "65".
    // The bottom row is a full bar, not the rounded ".###." shape.
    AddChampionSheetPatternGlyph(
        glyphs, '5', "#####" + "#...." + "####." + "....#" + "####.");
    AddChampionSheetPatternGlyph(
        glyphs, '7', "#####" + "...#." + "..#.." + ".#..." + "#....");
    return glyphs.ContainsKey('0') && glyphs.ContainsKey('6');
  }

  private static void AddChampionSheetPatternGlyph(
      Dictionary<char, Color32[]> glyphs,
      char character,
      string pattern)
  {
    Color32 ink = new Color32(182, 182, 182, 255);
    Color32 panel = new Color32(73, 73, 73, 255);
    Color32[] glyph = new Color32[
        ChampionSheetGlyphWidth * ChampionSheetGlyphHeight];
    for (int i = 0; i < glyph.Length; i++)
      glyph[i] = i < pattern.Length && pattern[i] == '#' ? ink : panel;
    glyphs[character] = glyph;
  }

  private void PaintChampionSheetName(Color32[] pixels)
  {
    HeroDefinition hero = HeroDatabase.GetByName(championSheetName);
    string label = GetChampionSheetFullName(hero, championSheetName);

    DungeonBitmapFont bitmapFont = FindEditModeBitmapFont();
    if (bitmapFont == null || string.IsNullOrEmpty(label))
      return;

    // Zero-based screen position requested for the visible hero-name ink:
    // X=4, Y=35. The bitmap font has a 2px left bearing, so its cell origin
    // is X=2. DrawText uses bottom-origin Y, hence the conversion below.
    const int visibleNameX = 4;
    const int visibleNameTop = 35;
    const int glyphLeftBearing = 2;
    bitmapFont.DrawText(
        pixels,
        PreviewWidth,
        PreviewHeight,
        label,
        visibleNameX - glyphLeftBearing,
        PreviewHeight - visibleNameTop - DungeonBitmapFont.DebugGlyphHeight,
        new Color32(255, 182, 0, 255),
        0,
        0,
        PreviewWidth,
        PreviewHeight,
        6);
  }

  private void PaintCharacterSheetError(Color32[] pixels, string message)
  {
    DungeonBitmapFont bitmapFont = FindEditModeBitmapFont();
    if (bitmapFont == null || pixels == null || string.IsNullOrEmpty(message))
      return;

    bitmapFont.DrawText(
        pixels,
        PreviewWidth,
        PreviewHeight,
        message,
        4,
        PreviewHeight - 50 - DungeonBitmapFont.DebugGlyphHeight,
        new Color32(255, 255, 0, 255),
        0,
        0,
        PreviewWidth,
        PreviewHeight,
        6);
  }

  private static string GetChampionSheetFullName(
      HeroDefinition hero,
      string fallbackName)
  {
    string baseName = hero != null && !string.IsNullOrEmpty(hero.Name)
        ? hero.Name.Trim()
        : (fallbackName ?? string.Empty).Trim();

    if (hero == null)
      return baseName;

    // Character-sheet UI owns the full champion caption. Keep this independent
    // from Champion Mirror/F1 rendering. Prefer a full/display name supplied by
    // HeroDefinition; otherwise combine Name with its title if one is present.
    string fullName = GetHeroTextMember(
        hero,
        "FullName",
        "DisplayName",
        "LongName");
    if (!string.IsNullOrEmpty(fullName)
        && !string.Equals(
            fullName.Trim(), baseName, System.StringComparison.OrdinalIgnoreCase))
    {
      return fullName.Trim();
    }

    string title = GetHeroTextMember(
        hero,
        "Title",
        "Subtitle",
        "SubTitle",
        "Epithet");
    if (!string.IsNullOrEmpty(title))
    {
      title = title.Trim();
      if (string.IsNullOrEmpty(baseName))
        return title;
      if (baseName.IndexOf(title, System.StringComparison.OrdinalIgnoreCase) < 0)
        return baseName + " " + title;
    }

    // The Hall of Champions source identifies Zed by the short name. Preserve
    // the original full character-sheet caption when no title field is exposed
    // by the runtime HeroDefinition.
    if (string.Equals(baseName, "ZED", System.StringComparison.OrdinalIgnoreCase))
      return "ZED DUKE OF BANVILLE";

    return baseName;
  }

  private static string GetHeroTextMember(
      object instance,
      params string[] memberNames)
  {
    if (instance == null || memberNames == null)
      return string.Empty;

    System.Type type = instance.GetType();
    const System.Reflection.BindingFlags flags =
        System.Reflection.BindingFlags.Instance
        | System.Reflection.BindingFlags.Public
        | System.Reflection.BindingFlags.IgnoreCase;

    for (int i = 0; i < memberNames.Length; i++)
    {
      string memberName = memberNames[i];
      if (string.IsNullOrEmpty(memberName))
        continue;

      System.Reflection.PropertyInfo property = type.GetProperty(memberName, flags);
      if (property != null && property.PropertyType == typeof(string))
      {
        string value = property.GetValue(instance, null) as string;
        if (!string.IsNullOrEmpty(value))
          return value;
      }

      System.Reflection.FieldInfo field = type.GetField(memberName, flags);
      if (field != null && field.FieldType == typeof(string))
      {
        string value = field.GetValue(instance) as string;
        if (!string.IsNullOrEmpty(value))
          return value;
      }
    }

    return string.Empty;
  }

  private void PaintChampionSheetPortrait(Color32[] pixels, HeroDefinition hero)
  {
    if (hero == null)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Cannot render Champion portrait: hero definition is null.");
      PaintCharacterSheetError(pixels, "ERROR CHAMPION PORTRAIT");
      return;
    }

    string portraitName = hero.Name;
    Texture2D portrait = GetReadableChampionPortrait(portraitName);
    if (portrait == null)
    {
      PaintCharacterSheetError(pixels, "ERROR CHAMPION PORTRAIT");
      return;
    }

    Color32[] source = portrait.GetPixels32();
    if (source == null || source.Length != ChampionSheetPortraitWidth * ChampionSheetPortraitHeight)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Champion portrait pixel data is invalid for "
          + portraitName + ".");
      PaintCharacterSheetError(pixels, "ERROR CHAMPION PORTRAIT");
      return;
    }

    // Render the Champion's own fixed 32x29 image from Assets/Art/Champions.
    // Transparent portrait pixels must render as RGB(109,109,109).
    // Party slot 1 is screen X=7, Y=0.
    Color32 transparentBackground = new Color32(109, 109, 109, 255);
    for (int row = 0; row < ChampionSheetPortraitHeight; row++)
    {
      int sourceRow = ChampionSheetPortraitHeight - 1 - row;
      for (int column = 0; column < ChampionSheetPortraitWidth; column++)
      {
        Color32 color = source[sourceRow * ChampionSheetPortraitWidth + column];
        if (color.a == 0)
          color = transparentBackground;

        SetChampionSheetPixel(
            pixels,
            ChampionSheetPortraitX + column,
            ChampionSheetPortraitScreenTop + row,
            color);
      }
    }
  }

  private Texture2D GetReadableChampionPortrait(string championName)
  {
    string wantedKey = NormalizeChampionAssetKey(championName);
    if (string.IsNullOrEmpty(wantedKey))
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Champion portrait name is empty.");
      return null;
    }

    if (cachedReadableChampionPortraits.TryGetValue(
            wantedKey,
            out Texture2D cached)
        && cached != null)
    {
      return cached;
    }

    string folder = Path.Combine(
        Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
        ChampionArtFolder);
    if (!Directory.Exists(folder))
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Champion art folder not found: "
          + ChampionArtFolder);
      return null;
    }

    // Champion portrait assets are the hero's own 32x29 PNGs in
    // Assets/Art/Champions. Accept only the hero key itself or the explicit
    // _32x29 suffix; do not fall back to another image or folder match.
    string wantedSizedKey = wantedKey + "32X29";
    string[] files = Directory.GetFiles(folder, "*.png", SearchOption.TopDirectoryOnly);
    string match = null;
    for (int i = 0; i < files.Length; i++)
    {
      string fileKey = NormalizeChampionAssetKey(
          Path.GetFileNameWithoutExtension(files[i]));
      if (fileKey.IndexOf("MIRROR", System.StringComparison.Ordinal) >= 0)
        continue;

      if (string.Equals(fileKey, wantedKey, System.StringComparison.Ordinal)
          || string.Equals(fileKey, wantedSizedKey, System.StringComparison.Ordinal))
      {
        if (match != null)
        {
          Debug.LogError(
              "[ViewportLayoutEditor] ERROR: More than one Champion portrait matches "
              + championName + " in " + ChampionArtFolder + ".");
          return null;
        }
        match = files[i];
      }
    }

    if (match == null)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: No 32x29 Champion portrait asset found for "
          + championName + " in " + ChampionArtFolder + ".");
      return null;
    }

    byte[] pngBytes;
    try
    {
      pngBytes = File.ReadAllBytes(match);
    }
    catch (System.Exception exception)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Failed reading Champion portrait "
          + match + ": " + exception.Message);
      return null;
    }

    Texture2D readableCopy = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    readableCopy.name = "ChampionPortrait_32x29_ReadablePreview";
    readableCopy.filterMode = FilterMode.Point;
    readableCopy.wrapMode = TextureWrapMode.Clamp;
    readableCopy.hideFlags = HideFlags.HideAndDontSave;
    if (!readableCopy.LoadImage(pngBytes, false))
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Failed decoding Champion portrait PNG: "
          + match);
      DestroyImmediate(readableCopy);
      return null;
    }

    if (readableCopy.width != ChampionSheetPortraitWidth
        || readableCopy.height != ChampionSheetPortraitHeight)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Champion portrait must be exactly 32x29: "
          + match + " is " + readableCopy.width + "x" + readableCopy.height + ".");
      DestroyImmediate(readableCopy);
      return null;
    }

    cachedReadableChampionPortraits[wantedKey] = readableCopy;
    return readableCopy;
  }

  private void ClearChampionSheetEquipment(Color32[] pixels)
  {
    Texture2D inventory = GetChampionInventoryTexture();
    if (inventory == null)
      return;

    Color32[] source = inventory.GetPixels32();
    if (source == null || source.Length != inventory.width * inventory.height)
      return;

    for (int i = 0; i < ChampionSheetEquipSlotXY.Length; i += 2)
    {
      CopyInventoryRect(
          pixels,
          source,
          inventory.width,
          ChampionSheetEquipSlotXY[i],
          ChampionSheetEquipSlotXY[i + 1],
          ChampionSheetSlotSize,
          ChampionSheetSlotSize);
    }
  }

  // Temporary: silence only Halk inventory artwork errors until the PNGs are imported.
  private const bool SuppressHalkEquipmentSpriteErrors = true;

  private void PaintChampionSheetEquipment(Color32[] pixels, HeroDefinition hero)
  {
    if (hero == null)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Cannot render Champion equipment: hero definition is null.");
      return;
    }

    if (hero.StartingItems == null)
    {
      Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Champion " + hero.Name
          + " has a null StartingItems list.");
      return;
    }

    bool handUsed = false;
    bool quiverUsed = false;
    for (int i = 0; i < hero.StartingItems.Count; i++)
    {
      HeroStartingItem item = hero.StartingItems[i];
      string itemName = GetChampionStartingItemName(item);
      if (string.IsNullOrEmpty(itemName))
      {
        Debug.LogError(
            "[ViewportLayoutEditor] ERROR: Champion " + hero.Name
            + " starting item #" + i
            + " has no readable ItemName/ObjectType.");
        continue;
      }

      if (!TryGetChampionSheetEquipSlot(
              itemName,
              ref handUsed,
              ref quiverUsed,
              out int localX,
              out int localY))
      {
        Debug.LogError(
            "[ViewportLayoutEditor] ERROR: No Champion-sheet slot mapping for "
            + hero.Name + " starting item '" + itemName + "'.");
        continue;
      }

      if (!DrawChampionSheetItemIcon(
              pixels,
              localX,
              localY,
              itemName,
              SuppressHalkEquipmentSpriteErrors
                  && string.Equals(hero.Name, "HALK", System.StringComparison.OrdinalIgnoreCase)))
      {
        if (!(SuppressHalkEquipmentSpriteErrors
              && string.Equals(hero.Name, "HALK", System.StringComparison.OrdinalIgnoreCase)))
          Debug.LogError(
            "[ViewportLayoutEditor] ERROR: Failed to render "
            + hero.Name + " starting item '" + itemName
            + "' at Champion-sheet slot X=" + localX + " Y=" + localY + ".");
      }
    }
  }


  // HeroStartingItem existed in two project generations: one stores the
  // champion item label in `ItemName`, the other in `ObjectType`.  The editor
  // must accept both so the Hall of Champions data remains authoritative
  // regardless of which HeroDefinition version is currently compiled.
  private static string GetChampionStartingItemName(HeroStartingItem item)
  {
    if (item == null)
      return string.Empty;

    System.Type type = item.GetType();
    const System.Reflection.BindingFlags flags =
        System.Reflection.BindingFlags.Instance
        | System.Reflection.BindingFlags.Public
        | System.Reflection.BindingFlags.NonPublic;

    string[] memberNames = { "ItemName", "ObjectType" };
    for (int i = 0; i < memberNames.Length; i++)
    {
      System.Reflection.FieldInfo field = type.GetField(memberNames[i], flags);
      if (field != null && field.FieldType == typeof(string))
      {
        string value = field.GetValue(item) as string;
        if (!string.IsNullOrWhiteSpace(value))
          return value.Trim();
      }

      System.Reflection.PropertyInfo property =
          type.GetProperty(memberNames[i], flags);
      if (property != null
          && property.PropertyType == typeof(string)
          && property.GetIndexParameters().Length == 0)
      {
        string value = property.GetValue(item, null) as string;
        if (!string.IsNullOrWhiteSpace(value))
          return value.Trim();
      }
    }

    return string.Empty;
  }

  private static bool TryGetChampionSheetEquipSlot(
      string objectType,
      ref bool handUsed,
      ref bool quiverUsed,
      out int localX,
      out int localY)
  {
    localX = 0;
    localY = 0;
    string name = objectType.ToUpperInvariant();
    string slot = "pack";
    if (name.Contains("HELM"))
      slot = "head";
    else if (name.Contains("CHOKER") || name.Contains("CLOAK"))
      slot = "neck";
    else if (name.Contains("HOSEN"))
      slot = "feet";
    else if (name.Contains("BARBARIAN") && name.Contains("HIDE"))
      slot = "legs";
    else if (name.Contains("TROUSER")
        || name.Contains("PANTS")
        || name.Contains("HUKE")
        || name.Contains("GUNNA")
        || (name.Contains("ROBE") && name.Contains("LEG")))
      slot = "legs";
    else if (name.Contains("BOOT") || name.Contains("SANDAL"))
      slot = "feet";
    else if (name.Contains("ARROW")
        || name.Contains("STAR")
        || name.Contains("DART"))
      slot = "quiver";
    else if (name.Contains("SWORD")
        || name.Contains("AXE")
        || name.Contains("CLUB")
        || name.Contains("TORCH")
        || name.Contains("DAGGER")
        || name.Contains("STAFF")
        || name.Contains("WAND")
        || name.Contains("BOW")
        || name.Contains("SLING")
        || name.Contains("SHIELD"))
      slot = "hand";
    else if (name.Contains("SHIRT")
        || name.Contains("TUNIC")
        || name.Contains("JERKIN")
        || name.Contains("DOUBLET")
        || name.Contains("KIRTLE")
        || name.Contains("HALTER")
        || name.Contains("TABARD")
        || name.Contains("AKETON")
        || name.Contains("HIDE")
        || name.Contains("GHI")
        || (name.Contains("ROBE") && !name.Contains("LEG")))
      slot = "torso";
    else if (name.Contains("BOX"))
      slot = "magicbox";

    if (slot == "head")
    {
      // Original Champion sheet head slot: screen X=5, Y=45.
      localX = 5;
      localY = 12;
      return true;
    }

    if (slot == "neck")
    {
      localX = 33;
      localY = 25;
      return true;
    }

    if (slot == "torso")
    {
      localX = 33;
      localY = 45;
      return true;
    }

    if (slot == "legs")
    {
      localX = 33;
      localY = 65;
      return true;
    }

    if (slot == "feet")
    {
      localX = 33;
      localY = 85;
      return true;
    }

    if (slot == "magicbox")
    {
      // Original Champion sheet: carried magical box occupies the upper
      // right 18x18 carried-item slot (screen X=61, Y=65).
      localX = 61;
      localY = 32;
      return true;
    }

    if (slot == "hand")
    {
      if (!handUsed)
      {
        handUsed = true;
        localX = 61;
        localY = 52;
      }
      else
      {
        localX = 5;
        localY = 32;
      }

      return true;
    }

    if (slot == "quiver")
    {
      if (!quiverUsed)
      {
        quiverUsed = true;
        localX = 5;
        localY = 52;
      }
      else
      {
        localX = 5;
        localY = 72;
      }

      return true;
    }

    return false;
  }



  // Original DOS Halk item artwork measured from the 320x200 Champion sheet.
  // These are item-type masks, so any Champion using the same item gets the
  // same exact inventory artwork.
  private static readonly string[] ChampionSheetBerserkerHelmMask =
  {
    "ddddddmmmmmmmmmmmm",
    "ddddddmppppppppppp",
    "ddddddmppppppppppp",
    "ddddddmpppppppKKKK",
    "ddddddmppKKKKKKKKK",
