  private bool DrawChampionSheetItemIcon(
      Color32[] pixels,
      int localX,
      int localY,
      string objectType,
      bool suppressSpriteErrors = false)
  {
    // STRICT starting-item rendering: there is exactly one source of artwork --
    // the real inventory PNG for the canonical item. Do not draw a hardcoded
    // mask, generated approximation, or any other fallback. A missing or
    // invalid asset is an error and must be visible in the Unity Console.
    string spriteKey = ResolveChampionInventorySpriteKey(objectType);
    if (string.IsNullOrEmpty(spriteKey))
    {
      if (!suppressSpriteErrors)
        Debug.LogError(
          "[ViewportLayoutEditor] ERROR: Starting item '" + objectType
          + "' has no canonical inventory sprite key.");
      return false;
    }

    return TryDrawChampionSheetInventoryItemTexture(
        pixels, localX, localY, spriteKey, suppressSpriteErrors);
  }

  private bool TryDrawChampionSheetInventoryItemTexture(
      Color32[] pixels,
      int slotX,
      int slotY,
      string objectType,
      bool suppressSpriteErrors = false)
  {
    Texture2D texture = GetChampionInventoryItemTexture(objectType, suppressSpriteErrors);
    if (texture == null || !texture.isReadable)
      return false;

    // Champion equipment slots are 18x18. Native inventory icons are normally
    // 16x16, so center them with a 1px border. Exact 18x18 art is copied 1:1.
    if (texture.width <= 0 || texture.height <= 0
        || texture.width > ChampionSheetSlotSize
        || texture.height > ChampionSheetSlotSize)
    {
      return false;
    }

    int offsetX = (ChampionSheetSlotSize - texture.width) / 2;
    int offsetY = (ChampionSheetSlotSize - texture.height) / 2;
    int screenTop = ChampionSheetInventoryScreenTop + slotY + offsetY;
    Color32[] source = texture.GetPixels32();

    for (int row = 0; row < texture.height; row++)
    {
      int sourceRow = texture.height - 1 - row;
      for (int column = 0; column < texture.width; column++)
      {
        Color32 color = source[sourceRow * texture.width + column];
        if (color.a == 0)
          continue;

        SetChampionSheetPixel(
            pixels,
            slotX + offsetX + column,
            screenTop + row,
            color);
      }
    }

    return true;
  }

  private static string ResolveChampionInventorySpriteKey(string objectType)
  {
    if (string.IsNullOrEmpty(objectType))
      return string.Empty;

    // HeroDatabase starting-item names are gameplay-friendly labels, while the
    // canonical item database / inventory art uses a few different names.
    // Resolve those aliases before looking for the real inventory PNG.
    string key = NormalizeChampionAssetKey(objectType);
    switch (key)
    {
      case "ROBE":
      case "ROBEBODY":
        return "Robe (Body)";
      case "ROBELEGS":
        return "Robe (Legs)";
      case "BLUEMAGICALBOX":
      case "MAGICALBOXBLUE":
        return "Magical Box (Blue)";
      case "BERSERKERHELM":
        return "Bezerker Helm";
      case "TORCH":
        return "Torch (Unlit)";
      default:
        return objectType;
    }
  }

  private static void LogChampionInventorySpriteError(bool suppress, string message)
  {
    if (!suppress)
      Debug.LogError(message);
  }

  private Texture2D GetChampionInventoryItemTexture(
      string objectType, bool suppressSpriteErrors = false)
  {
    string spriteKey = ResolveChampionInventorySpriteKey(objectType);
    string wantedKey = NormalizeChampionAssetKey(spriteKey);
    if (string.IsNullOrEmpty(wantedKey))
    {
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Empty inventory sprite key for starting item '"
          + objectType + "'.");
      return null;
    }

    if (cachedChampionInventoryItemTextures.TryGetValue(
            wantedKey, out Texture2D cached)
        && cached != null)
    {
      return cached;
    }

    if (missingChampionInventoryItemTextureKeys.Contains(wantedKey))
      return null;

    // STRICT lookup. Valid filenames are the canonical sprite key itself or the
    // canonical key with an explicit 16x16 / 18x18 size suffix. No prefix/score
    // guessing and no alternate artwork fallback.
    string wanted16 = wantedKey + "16X16";
    string wanted18 = wantedKey + "18X18";
    string alternateWantedKey = string.Empty;
    if (string.Equals(wantedKey, "BEZERKERHELM", System.StringComparison.Ordinal))
      alternateWantedKey = "BERSERKERHELM";
    string alternateWanted16 = string.IsNullOrEmpty(alternateWantedKey)
        ? string.Empty : alternateWantedKey + "16X16";
    string alternateWanted18 = string.IsNullOrEmpty(alternateWantedKey)
        ? string.Empty : alternateWantedKey + "18X18";
    string[] guids = AssetDatabase.FindAssets(
        "t:Texture2D", new[] { "Assets" });
    System.Collections.Generic.List<string> matches =
        new System.Collections.Generic.List<string>();

    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      if (string.IsNullOrEmpty(path)
          || !path.EndsWith(".png", System.StringComparison.OrdinalIgnoreCase))
      {
        continue;
      }

      string fileKey = NormalizeChampionAssetKey(
          Path.GetFileNameWithoutExtension(path));
      bool exactPrimary =
          string.Equals(fileKey, wantedKey, System.StringComparison.Ordinal)
          || string.Equals(fileKey, wanted16, System.StringComparison.Ordinal)
          || string.Equals(fileKey, wanted18, System.StringComparison.Ordinal);
      bool exactDeclaredAlias =
          !string.IsNullOrEmpty(alternateWantedKey)
          && (string.Equals(fileKey, alternateWantedKey, System.StringComparison.Ordinal)
              || string.Equals(fileKey, alternateWanted16, System.StringComparison.Ordinal)
              || string.Equals(fileKey, alternateWanted18, System.StringComparison.Ordinal));
      if (!exactPrimary && !exactDeclaredAlias)
      {
        continue;
      }

      Texture2D imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (imported == null)
      {
        LogChampionInventorySpriteError(suppressSpriteErrors, 
            "[ViewportLayoutEditor] ERROR: Inventory sprite asset exists but Unity could not load it: "
            + path);
        continue;
      }

      if (imported.width <= 0 || imported.height <= 0
          || imported.width > ChampionSheetSlotSize
          || imported.height > ChampionSheetSlotSize)
      {
        LogChampionInventorySpriteError(suppressSpriteErrors, 
            "[ViewportLayoutEditor] ERROR: Inventory sprite for '" + spriteKey
            + "' has invalid Champion-sheet size " + imported.width + "x"
            + imported.height + ": " + path);
        continue;
      }

      matches.Add(path);
    }

    if (matches.Count == 0)
    {
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Required inventory sprite not found for starting item '"
          + objectType + "' (canonical spriteKey '" + spriteKey
          + "'). Expected an exact PNG identity anywhere under Assets: "
          + spriteKey + ".png, " + spriteKey + "_16x16.png, or "
          + spriteKey + "_18x18.png"
          + (string.IsNullOrEmpty(alternateWantedKey)
              ? "."
              : " (declared alias Berserker Helm is also accepted)."));
      return null;
    }

    if (matches.Count > 1)
    {
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Ambiguous inventory sprite for starting item '"
          + objectType + "' (canonical spriteKey '" + spriteKey
          + "'). More than one exact candidate exists: "
          + string.Join(", ", matches.ToArray()));
      return null;
    }

    string bestPath = matches[0];
    string projectRoot = Path.GetDirectoryName(Application.dataPath);
    string absolutePath = string.IsNullOrEmpty(projectRoot)
        ? bestPath
        : Path.Combine(projectRoot, bestPath);
    if (!File.Exists(absolutePath))
    {
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Inventory sprite AssetDatabase path exists but file is missing on disk: "
          + bestPath);
      return null;
    }

    byte[] pngBytes;
    try
    {
      pngBytes = File.ReadAllBytes(absolutePath);
    }
    catch (System.Exception exception)
    {
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Failed reading inventory sprite '"
          + bestPath + "': " + exception.Message);
      return null;
    }

    Texture2D readableCopy = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    readableCopy.name = "ChampionInventoryItem_" + wantedKey;
    readableCopy.filterMode = FilterMode.Point;
    readableCopy.wrapMode = TextureWrapMode.Clamp;
    readableCopy.hideFlags = HideFlags.HideAndDontSave;
    if (!readableCopy.LoadImage(pngBytes, false))
    {
      DestroyImmediate(readableCopy);
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Failed decoding inventory sprite PNG: "
          + bestPath);
      return null;
    }

    if (readableCopy.width > ChampionSheetSlotSize
        || readableCopy.height > ChampionSheetSlotSize)
    {
      int width = readableCopy.width;
      int height = readableCopy.height;
      DestroyImmediate(readableCopy);
      missingChampionInventoryItemTextureKeys.Add(wantedKey);
      LogChampionInventorySpriteError(suppressSpriteErrors, 
          "[ViewportLayoutEditor] ERROR: Decoded inventory sprite for '" + spriteKey
          + "' is too large for an 18x18 Champion slot: " + width + "x"
          + height + " at " + bestPath);
      return null;
    }

    cachedChampionInventoryItemTextures[wantedKey] = readableCopy;
    return readableCopy;
  }

  private void DrawChampionSheetMask(
      Color32[] pixels,
      int slotX,
      int slotY,
      string[] rows)
  {
    int screenTop = ChampionSheetInventoryScreenTop + slotY;
    for (int row = 0; row < rows.Length; row++)
    {
      string line = rows[row];
      for (int column = 0; column < line.Length; column++)
      {
        if (!TryGetChampionSheetMaskColor(line[column], out Color32 color))
          continue;
        SetChampionSheetPixel(
            pixels,
            slotX + column,
            screenTop + row,
            color);
      }
    }
  }

  private static bool TryGetChampionSheetMaskColor(
      char token,
      out Color32 color)
  {
    switch (token)
    {
      case 'W':
        color = new Color32(255, 255, 255, 255);
        return true;
      case 'w':
        color = new Color32(182, 182, 182, 255);
        return true;
      case 'g':
        color = new Color32(146, 146, 146, 255);
        return true;
      case 'G':
        color = new Color32(0, 219, 0, 255);
        return true;
      case 'R':
        color = new Color32(255, 0, 0, 255);
        return true;
      case 'K':
        color = new Color32(0, 0, 0, 255);
        return true;
      case 'b':
        color = new Color32(146, 73, 0, 255);
        return true;
      case 'd':
        color = new Color32(73, 73, 73, 255);
        return true;
      case 'm':
        color = new Color32(109, 109, 109, 255);
        return true;
      case 'q':
        color = new Color32(109, 36, 0, 255);
        return true;
      case 'O':
        color = new Color32(255, 182, 0, 255);
        return true;
      case 'Y':
        color = new Color32(255, 255, 0, 255);
        return true;
      case 'B':
        color = new Color32(0, 0, 255, 255);
        return true;
      case 'C':
        color = new Color32(0, 219, 219, 255);
        return true;
      case 'p':
        color = new Color32(219, 146, 109, 255);
        return true;
      default:
        color = default;
        return false;
    }
  }

  private void CaptureChampionSheetGlyph(
      Color32[] pixels,
      Dictionary<char, Color32[]> glyphs,
      char character,
      int screenX,
      int screenTop)
  {
    Color32[] glyph = new Color32[
        ChampionSheetGlyphWidth * ChampionSheetGlyphHeight];
    for (int row = 0; row < ChampionSheetGlyphHeight; row++)
    {
      for (int column = 0; column < ChampionSheetGlyphWidth; column++)
      {
        glyph[row * ChampionSheetGlyphWidth + column] =
            GetChampionSheetPixel(pixels, screenX + column, screenTop + row);
      }
    }

    glyphs[character] = glyph;
  }

  private static bool ChampionSheetTextHasGlyphs(
      Dictionary<char, Color32[]> glyphs,
      string text)
  {
    for (int i = 0; i < text.Length; i++)
    {
      char character = text[i];
      if (character == ' ')
        continue;
      if (!glyphs.ContainsKey(character))
        return false;
    }

    return true;
  }

  private void DrawChampionSheetText(
      Color32[] pixels,
      Dictionary<char, Color32[]> glyphs,
      int screenX,
      int screenTop,
      string text)
  {
    int cursor = screenX;
    for (int i = 0; i < text.Length; i++)
    {
      char character = text[i];
      if (character != ' '
          && glyphs.TryGetValue(character, out Color32[] glyph))
      {
        for (int row = 0; row < ChampionSheetGlyphHeight; row++)
        {
          for (int column = 0; column < ChampionSheetGlyphWidth; column++)
          {
            SetChampionSheetPixel(
                pixels,
                cursor + column,
                screenTop + row,
                glyph[row * ChampionSheetGlyphWidth + column]);
          }
        }
      }

      cursor += ChampionSheetGlyphAdvance;
    }
  }

  private void DrawPreviewPosePixelText(Color32[] pixels)
  {
    if (pixels == null)
      return;

    Dictionary<char, Color32[]> glyphs = BuildChampionSheetStatusGlyphs();
    string text = "LEVEL " + previewDungeonLevel + " - " + previewX + "," + previewY + " - " + previewFacing;

    const int screenX = 4;
    const int screenTop = 174;
    Color32 ink = new Color32(0, 0, 0, 255);
    Color32 generatedInk = new Color32(182, 182, 182, 255);

    int cursor = screenX;
    for (int i = 0; i < text.Length; i++)
    {
      char character = char.ToUpperInvariant(text[i]);
      if (character != ' ' && glyphs.TryGetValue(character, out Color32[] glyph))
      {
        for (int row = 0; row < ChampionSheetGlyphHeight; row++)
        {
          for (int column = 0; column < ChampionSheetGlyphWidth; column++)
          {
            Color32 source = glyph[row * ChampionSheetGlyphWidth + column];
            if (source.r == generatedInk.r
                && source.g == generatedInk.g
                && source.b == generatedInk.b)
            {
              SetChampionSheetPixel(
                  pixels,
                  cursor + column,
                  screenTop + row,
                  ink);
            }
          }
        }
      }

      cursor += ChampionSheetGlyphAdvance;
    }
  }

  private void FillChampionSheetRect(
      Color32[] pixels,
      int screenX,
      int screenTop,
      int width,
      int height,
      Color32 color)
  {
    for (int row = 0; row < height; row++)
    {
      for (int column = 0; column < width; column++)
        SetChampionSheetPixel(pixels, screenX + column, screenTop + row, color);
    }
  }

  private Color32 GetChampionSheetPixel(
      Color32[] pixels,
      int screenX,
      int screenY)
  {
    int index = ChampionSheetPixelIndex(screenX, screenY);
    if (index < 0)
      return new Color32(0, 0, 0, 255);
    return pixels[index];
  }

  private void SetChampionSheetPixel(
      Color32[] pixels,
      int screenX,
      int screenY,
      Color32 color)
  {
    int index = ChampionSheetPixelIndex(screenX, screenY);
    if (index >= 0)
      pixels[index] = color;
  }

  private int ChampionSheetPixelIndex(int screenX, int screenY)
  {
    if (screenX < 0 || screenX >= PreviewWidth
        || screenY < 0 || screenY >= PreviewHeight)
    {
      return -1;
    }

    int framebufferY = PreviewHeight - 1 - screenY;
    return framebufferY * PreviewWidth + screenX;
  }


  private Texture2D GetChampionsBackgroundTexture()
