  private void PaintChampionFoodWaterPanel(Color32[] pixels)
  {
    if (!championMouthPressed
        || pixels == null
        || pixels.Length != PreviewWidth * PreviewHeight)
    {
      return;
    }

    const int panelX = 103;
    const int panelY = 85;
    const int panelWidth = 116;
    const int panelHeight = 73;

    Color32 panel = new Color32(73, 73, 73, 255);
    Color32 border = new Color32(109, 109, 109, 255);
    FillChampionSheetRect(pixels, panelX, panelY, panelWidth, panelHeight, panel);
    FillChampionSheetRect(pixels, panelX, panelY, panelWidth, 1, border);
    FillChampionSheetRect(pixels, panelX, panelY + panelHeight - 1, panelWidth, 1, border);
    FillChampionSheetRect(pixels, panelX, panelY, 1, panelHeight, border);
    FillChampionSheetRect(pixels, panelX + panelWidth - 1, panelY, 1, panelHeight, border);

    // Initial recruitment state: the first recruited champion starts with
    // 100% FOOD and 100% WATER. Keep the fill width isolated here so later
    // gameplay code can replace 78 with a value derived from live food/water.
    const int fullBarWidth = 78;
    const int barHeight = 6;
    const int shadowHeight = 2;

    Color32 foodColour = new Color32(146, 73, 0, 255);
    Color32 waterColour = new Color32(0, 0, 255, 255);
    Color32 shadowColour = new Color32(0, 0, 0, 255);

    // FOOD: 78x6 coloured fill, then a 78x2 black shadow directly below.
    FillChampionSheetRect(pixels, 111, 102, fullBarWidth, barHeight, foodColour);
    FillChampionSheetRect(pixels, 111, 108, fullBarWidth, shadowHeight, shadowColour);

    // WATER: 78x6 coloured fill, then a 78x2 black shadow directly below.
    FillChampionSheetRect(pixels, 111, 125, fullBarWidth, barHeight, waterColour);
    FillChampionSheetRect(pixels, 111, 131, fullBarWidth, shadowHeight, shadowColour);

    // The FOOD and WATER captions remain the original 48x9 PNGs placed
    // pixel-exact at their calibrated screen coordinates.
    Texture2D foodTexture = GetChampionFoodLabelTexture();
    Texture2D waterTexture = GetChampionWaterLabelTexture();
    if (foodTexture != null)
      PaintChampionSheetOverlayTexture(pixels, foodTexture, 110, 92, foodTexture.width, foodTexture.height);
    if (waterTexture != null)
      PaintChampionSheetOverlayTexture(pixels, waterTexture, 110, 115, waterTexture.width, waterTexture.height);
  }

  private void PaintChampionSheetOverlayTexture(
      Color32[] pixels,
      Texture2D texture,
      int screenLeft,
      int screenTop,
      int width,
      int height)
  {
    if (pixels == null
        || texture == null
        || pixels.Length != PreviewWidth * PreviewHeight)
    {
      return;
    }

    // Strict 1:1 pixel placement. Do not scale, resample, reconstruct,
    // recolour, or alpha-blend these overlay PNGs. Every visible source
    // pixel is copied verbatim from the PNG into the 320x200 buffer.
    Color32[] source = texture.GetPixels32();
    for (int sourceY = 0; sourceY < height; sourceY++)
    {
      int screenY = screenTop + (height - 1 - sourceY);
      if (screenY < 0 || screenY >= PreviewHeight)
        continue;

      int destinationY = PreviewHeight - 1 - screenY;
      int sourceRow = sourceY * width;
      int destinationRow = destinationY * PreviewWidth;

      for (int sourceX = 0; sourceX < width; sourceX++)
      {
        int screenX = screenLeft + sourceX;
        if (screenX < 0 || screenX >= PreviewWidth)
          continue;

        Color32 sourcePixel = source[sourceRow + sourceX];
        if (sourcePixel.a == 0)
          continue;

        pixels[destinationRow + screenX] = sourcePixel;
      }
    }
  }

