    if (piece.Graphic == DungeonGraphicType.ChampionStatusBackground)
      return true;

    return piece.Name == "Champion Status Slot 1"
        || piece.Name == "Champion Status Slot 2"
        || piece.Name == "Champion Status Slot 3"
