  private Texture2D GetChampionMirrorSideTexture()
  {
    if (cachedChampionMirrorSideTexture != null)
      return cachedChampionMirrorSideTexture;

    Texture2D texture =
        AssetDatabase.LoadAssetAtPath<Texture2D>(ChampionMirrorSideAssetPath);
    if (texture != null && texture.width == 16 && texture.height == 35)
    {
      cachedChampionMirrorSideTexture = texture;
      return texture;
    }

    // Filename-independent fallback: the original GRAPHICS.DAT contains one
    // 16x35 Champion side-mirror image. This lets the project keep a slightly
    // different filename without changing renderer code.
    string[] guids = AssetDatabase.FindAssets(
        "t:Texture2D",
        new[] { ChampionArtFolder });
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null || candidate.width != 16 || candidate.height != 35)
        continue;

      if (path.IndexOf(
              "mirror",
              System.StringComparison.OrdinalIgnoreCase) < 0)
      {
        continue;
      }

      cachedChampionMirrorSideTexture = candidate;
      return candidate;
    }

    return null;
  }

  private static int ResolveHallOfChampionsWallOrnamentSourceId(
      WallOrnamentPlacement ornament)
  {
    if (ornament == null || ornament.wallTilePlacement)
      return -1;

    int index = ornament.ornamentOrdinal - 1;
    if (index < 0 || index >= HallOfChampionsWallOrnamentSourceIds.Length)
      return -1;

    return HallOfChampionsWallOrnamentSourceIds[index];
  }

  private void BlitWoodRingD3FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D woodRingFront = GetWoodRingGeneratedF3FrontTexture();
    if (woodRingFront == null || !woodRingFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int d2X = previewX + forwardX * 2;
    int d2Y = previewY + forwardY * 2;
    int wallTileX = previewX + forwardX * 3;
    int wallTileY = previewY + forwardY * 3;
    if (!previewMiniMap.IsInside(d1X, d1Y)
        || previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(d2X, d2Y)
        || previewMiniMap.GetTile(d2X, d2Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY))
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsWoodRingOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == d2X
            && ornament.y == d2Y
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
          pixels, woodRingFront, ornament,
          HookFrontWallOrnamentSet.f3.x,
          HookFrontWallOrnamentSet.f3.y, false);
      return;
    }
  }

