  }

  private void BlitWoodRingD2FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D woodRingFront = GetWoodRingGeneratedF2FrontTexture();
    if (woodRingFront == null || !woodRingFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int wallTileX = previewX + forwardX * 2;
    int wallTileY = previewY + forwardY * 2;
    if (!previewMiniMap.IsInside(d1X, d1Y)
        || previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY))
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsWoodRingOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == d1X
            && ornament.y == d1Y
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      // Wood Ring shares coordinate set 0 with the Hook, so the F2 front
      // uses that same measured slot.
      BlitOrnamentPieceIntoPreview(
          pixels, woodRingFront, ornament,
          HookFrontWallOrnamentSet.f2.x,
          HookFrontWallOrnamentSet.f2.y, false);
      return;
    }
  }

  private Texture2D GetWoodRingGeneratedF2FrontTexture()
  {
    if (cachedWoodRingGeneratedF2FrontTexture != null)
      return cachedWoodRingGeneratedF2FrontTexture;

    Texture2D source = GetWoodRingFrontTexture();
    if (source == null || !source.isReadable)
      return null;

    cachedWoodRingGeneratedF2FrontTexture = GenerateDmScaledWallDecoration(
        source,
        HookFrontWallOrnamentSet.f2.width,
        HookFrontWallOrnamentSet.f2.height,
        WallOrnamentMediumColorMap,
        "Wood Ring F2 Generated from F1");
    return cachedWoodRingGeneratedF2FrontTexture;
  }

  private void BlitWoodRingD1FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D woodRingFront = GetWoodRingFrontTexture();
    if (woodRingFront == null || !woodRingFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int wallTileX = previewX + forwardX;
    int wallTileY = previewY + forwardY;
    if (!previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsWoodRingOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        // Random wall-decoration bits belong to the solid wall tile itself.
        string visiblePhysicalWallFace = OppositeFacingName(previewFacing);
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        // Explicit mechanisms are stored on the passable cell and use the
        // direction from that cell toward the wall boundary.
        placementMatches =
            ornament.x == previewX
            && ornament.y == previewY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      // Initial D1-front calibration uses the same original wall-center anchor
      // as the verified 28x28 Hook: framebuffer center (112,114). Keeping the
      // anchor independent of texture size lets the native Wood Ring PNG draw
      // 1:1 without guessing or rescaling it. We can nudge X/Y after the first
      // original-vs-Unity comparison if the source artwork requires it.
      int x = 112 - (woodRingFront.width / 2);
      int y = 114 - (woodRingFront.height / 2);

      BlitOrnamentPieceIntoPreview(
          pixels, woodRingFront, ornament, x, y, false);
      return;
    }
  }

  private static bool IsWoodRingOrnament(WallOrnamentPlacement ornament)
  {
    if (ornament == null)
      return false;

    if (string.Equals(
            ornament.type,
            "WoodRing",
            System.StringComparison.OrdinalIgnoreCase)
        || string.Equals(
            ornament.type,
            "Wood Ring",
            System.StringComparison.OrdinalIgnoreCase))
    {
      return true;
    }

    return ResolveHallOfChampionsWallOrnamentSourceId(ornament) == 6;
  }

  private Texture2D GetWoodRingFrontTexture()
  {
    if (cachedWoodRingFrontTexture != null)
      return cachedWoodRingFrontTexture;

    // Do not bake dimensions into the renderer. The original native source is
    // used 1:1. Accept WoodRing_Front..., Wood_Ring_Front..., or equivalent.
    string[] guids = AssetDatabase.FindAssets(
        "t:Texture2D",
        new[] { OrnamentArtFolder });

    Texture2D fallback = null;
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      string lower = path.ToLowerInvariant();
      bool isWoodRing =
          lower.Contains("woodring")
          || (lower.Contains("wood") && lower.Contains("ring"));
      if (!isWoodRing)
        continue;

      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null)
        continue;

      if (lower.Contains("front"))
      {
        cachedWoodRingFrontTexture = candidate;
        return candidate;
      }

      if (fallback == null && !lower.Contains("side"))
        fallback = candidate;
    }

    cachedWoodRingFrontTexture = fallback;
    return fallback;
  }

  private Texture2D GetWoodRingSideTexture()
  {
    if (cachedWoodRingSideTexture != null)
      return cachedWoodRingSideTexture;

    string[] guids = AssetDatabase.FindAssets(
        "t:Texture2D",
        new[] { OrnamentArtFolder });

    Texture2D fallback = null;
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      string lower = path.ToLowerInvariant();
      bool isWoodRing =
          lower.Contains("woodring")
          || (lower.Contains("wood") && lower.Contains("ring"));
      if (!isWoodRing || !lower.Contains("side"))
        continue;

      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null)
        continue;

      if (candidate.width == 14 && candidate.height == 19)
      {
        cachedWoodRingSideTexture = candidate;
        return candidate;
      }

      if (fallback == null)
        fallback = candidate;
    }

    cachedWoodRingSideTexture = fallback;
    return fallback;
  }

  private Texture2D GetWoodRingSide2Texture()
  {
    if (cachedWoodRingSide2Texture != null)
      return cachedWoodRingSide2Texture;

    // The F1 side extract is two pixels wide at the top, so a shrink cannot
    // rebuild the square top the original draws at (4,6) North. This 5x10
    // is that original result, at screen top-left (66, 73).
    Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>(
        "Assets/Art/Ornaments/Wood_Ring_Side2_5x10.png");
    if (texture != null && texture.width == 5 && texture.height == 10)
    {
      cachedWoodRingSide2Texture = texture;
      return texture;
    }

    return null;
  }

  private Texture2D GetWoodRingSide3Texture()
  {
    if (cachedWoodRingSide3Texture != null)
      return cachedWoodRingSide3Texture;

    // As with Side2, the distant Wood Ring side view is original authored
    // distance artwork. Shrinking the F1 side extract cannot reproduce the
    // exact 3x5 shape seen at (4,7) North.
    Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>(
        "Assets/Art/Ornaments/Wood_Ring_Side3_3x5.png");
    if (texture != null && texture.width == 3 && texture.height == 5)
    {
      cachedWoodRingSide3Texture = texture;
      return texture;
    }

    return null;
  }

  /// <summary>
  /// Loads resolved Level 0 wall/floor ornaments from the generated all-level
  /// placement database. This is the authoritative path when the database is
  /// present; the old Hall-specific derivation remains only as fallback.
  /// </summary>
  private bool LoadPreviewFeaturesFromDatabase()
  {
    if (!File.Exists(DungeonFeaturePlacementsPath))
      return false;

    try
    {
      DungeonFeaturePlacementDatabase database =
          DungeonFeaturePlacementDatabase.LoadFromFile(
              DungeonFeaturePlacementsPath);
      if (database == null || database.ornamentPlacements == null)
        return false;

      List<WallOrnamentPlacement> wallOrnaments =
          new List<WallOrnamentPlacement>();
      previewPuddleFloors.Clear();
      previewMossFloors.Clear();

      for (int i = 0; i < database.ornamentPlacements.Length; i++)
      {
        DungeonOrnamentPlacement placement =
            database.ornamentPlacements[i];
        if (placement == null
            || placement.level != previewDungeonLevel
            || placement.resolved == null
            || string.IsNullOrEmpty(placement.resolved.type))
        {
          continue;
        }

        if (string.Equals(
                placement.domain,
                "Floor",
                System.StringComparison.OrdinalIgnoreCase))
        {
          if (string.Equals(
                  placement.resolved.type,
                  "Puddle",
                  System.StringComparison.OrdinalIgnoreCase))
          {
            previewPuddleFloors.Add(
                PackPreviewTile(
                    placement.normalisedX,
                    placement.normalisedY));
          }
          else if (string.Equals(
                       placement.resolved.type,
                       "Moss",
                       System.StringComparison.OrdinalIgnoreCase))
          {
            previewMossFloors.Add(
                PackPreviewTile(
                    placement.normalisedX,
                    placement.normalisedY));
          }
          continue;
        }

        if (!string.Equals(
                placement.domain,
                "Wall",
                System.StringComparison.OrdinalIgnoreCase))
        {
          continue;
        }

        string wallName = NormaliseFeatureFaceName(
            placement.normalisedFace);
        if (string.IsNullOrEmpty(wallName))
          continue;

        wallOrnaments.Add(
            new WallOrnamentPlacement
            {
              type = NormaliseFeatureTypeName(placement.resolved.type),
              ornamentOrdinal = placement.ornamentOrdinal,
              x = placement.normalisedX,
              y = placement.normalisedY,
              wall = wallName,
              wallTilePlacement = true
            });
      }

      previewWallOrnaments = wallOrnaments.ToArray();
      return true;
    }
    catch (System.Exception ex)
    {
      Debug.LogWarning(
          "ViewEdit feature database load failed; using Hall fallback: "
          + ex.Message);
      return false;
    }
  }

  private static string NormaliseFeatureTypeName(string type)
  {
    if (string.Equals(
            type,
            "WallGrate",
            System.StringComparison.OrdinalIgnoreCase))
      return "Grate";

    // The placement database uses AltarOfVi, while the live altar renderers
    // use ViAltar as their canonical type name. Normalise the database name
    // here so D1/D2/D3 all see the same type.
    if (string.Equals(
            type,
            "AltarOfVi",
            System.StringComparison.OrdinalIgnoreCase))
      return "ViAltar";

    return type;
  }

  private static string NormaliseFeatureFaceName(string face)
  {
    if (string.IsNullOrEmpty(face))
      return null;

    switch (char.ToUpperInvariant(face[0]))
    {
      case 'N': return "North";
      case 'E': return "East";
      case 'S': return "South";
      case 'W': return "West";
      default: return null;
    }
  }

  private void LoadPreviewPuddleFloors()
  {
    previewPuddleFloors.Clear();
    if (previewMiniMap == null)
      return;

    // Original engine corridor rule:
    // randomIndex = Hash(2000 + x*32 + y,
    //                    3000 + level*64 + width + height, 30).
    // If randomIndex < RandomFloorOrnamentCount, ordinal = index + 1.
    // Hall of Champions local floor-ornament ordinal 2 is Puddle.
    int value2 = 3000 + previewMiniMap.Width + previewMiniMap.Height;

    for (int y = 0; y < previewMiniMap.Height; y++)
    {
      for (int x = 0; x < previewMiniMap.Width; x++)
      {
        DungeonTile tile = previewMiniMap.GetTile(x, y);
        if (tile == null
            || tile.SourceType != DungeonSourceTileType.Floor
            || (tile.Raw & 0x08) == 0)
        {
          continue;
        }

        int randomIndex = HallOfChampionsRandomOrnamentHash(
            2000 + (x << 5) + y,
            value2,
            HallOfChampionsRandomOrnamentModulo);
        if (randomIndex >= HallOfChampionsRandomFloorOrnamentCount)
          continue;

        int ordinal = randomIndex + 1;
        if (ordinal == HallOfChampionsPuddleFloorOrnamentOrdinal)
          previewPuddleFloors.Add(PackPreviewTile(x, y));
      }
    }
  }

  private static int PackPreviewTile(int x, int y)
  {
    return (y << 8) | (x & 0xFF);
  }

  private bool IsPreviewPuddleFloor(int x, int y)
  {
    return previewPuddleFloors.Contains(PackPreviewTile(x, y))
        && IsPreviewFeatureEnabled(MakePreviewFeatureKey("Puddle", x, y, null));
  }

  private bool IsPreviewMossFloor(int x, int y)
  {
    return previewMossFloors.Contains(PackPreviewTile(x, y))
        && IsPreviewFeatureEnabled(MakePreviewFeatureKey("Moss", x, y, null));
  }


