  private bool IsStairsDownF1NeededForCurrentPose()
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int stairsX = previewX + forwardX;
    int stairsY = previewY + forwardY;

    return previewMiniMap.IsInside(stairsX, stairsY)
        && previewMiniMap.GetTile(stairsX, stairsY)
            .TryGetStairsDirection(out bool stairsUp)
        && !stairsUp
        && IsPreviewFeatureEnabled(
            MakePreviewFeatureKey("StairsDown", stairsX, stairsY, null));
  }

  /// <summary>
  /// True when a down-stairs tile is immediately to the player's right.
  /// This is geometry-relative and contains no map-coordinate special case.
  /// </summary>
  // A single authoritative D1-right stairs projection lookup is shared by
  // the wall painter and ViewEdit. Right is the clockwise perpendicular of
  // forward in map coordinates (Y increases towards South).
  private bool TryGetStairsDownS1Cell(out int mapX, out int mapY)
  {
    mapX = 0;
    mapY = 0;
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return false;

    // The same D1-right cell sampling used by the wall engine. Never
    // reimplement the coordinate transform or infer a stairs sprite.
    Viewport17Cell cell = SampleViewport17Cell(1, 1);
    // An immediately adjacent solid wall occludes the diagonal stairs.
    // This applies to every map position and facing, not only the test pose.
    if (!cell.IsInside || !cell.IsStairsDown
        || IsViewport17Solid(SampleViewport17Cell(1, 0)))
      return false;

    mapX = cell.MapX;
    mapY = cell.MapY;
    return true;
  }

  private bool IsStairsDownRightD1ForCurrentPose()
  {
    if (!stairsS1PreviewEnabled
        || !TryGetStairsDownS1Cell(out int mapX, out int mapY))
      return false;
    return IsPreviewFeatureEnabled(
        MakePreviewFeatureKey("StairsDown", mapX, mapY, null));
  }

  /// <summary>
  /// Replace the RightF0 screen slot with the exact original down-stairs
  /// D1-right wall projection. The asset already contains the original
  /// depth/palette pixels and is therefore blitted 1:1 with no scaling or
  /// colour conversion.
  /// </summary>
  private void BlitStairsDownRightD1IntoPreview(Color32[] pixels)
  {
    if (pixels == null)
      return;

    if (!IsStairsDownRightD1ForCurrentPose())
      return;

    // Exact project asset path. Do not use a filename search here; this
    // reference crop is intentionally tied to the Stairs folder.
    Texture2D stairsWall = AssetDatabase.LoadAssetAtPath<Texture2D>(
        "Assets/Art/Walls/Stairs/Stairs_Down_Front_D1_32x91.png");

    if (stairsWall == null)
    {
      Debug.LogError(
          "STAIRS RIGHT D1: Stairs_Down_Front_D1_32x91.png was not found.");
      return;
    }

    if (stairsWall.width != 32 || stairsWall.height != 91)
    {
      Debug.LogError(
          "STAIRS RIGHT D1: asset loaded but imported size is "
          + stairsWall.width + "x" + stairsWall.height
          + " (expected 32x91).");
      return;
    }

    if (!stairsWall.isReadable)
    {
      string stairsPath = AssetDatabase.GetAssetPath(stairsWall);
      TextureImporter importer = AssetImporter.GetAtPath(stairsPath) as TextureImporter;
      if (importer != null)
      {
        importer.isReadable = true;
        importer.mipmapEnabled = false;
        importer.filterMode = FilterMode.Point;
        importer.SaveAndReimport();
        stairsWall = AssetDatabase.LoadAssetAtPath<Texture2D>(stairsPath);
      }
    }

    if (stairsWall == null || !stairsWall.isReadable)
    {
      Debug.LogError(
          "STAIRS RIGHT D1: asset is still not readable after importer refresh.");
      return;
    }

    // IMPORTANT: this exact reference crop is positioned in the native
    // 224x136 dungeon viewport. Do not convert its Y against the 320x200
    // output buffer; that places it 64 pixels too high.
    int destinationY = DungeonViewportHeight - stairsS1TopY - stairsWall.height;

    BlitPieceIntoPreview(
        pixels,
        stairsWall,
        stairsS1X,
        destinationY,
        stairsS1Mirror);
  }

  // Generic S1-left projection: one cell forward and one cell left.
  // Use the same map-cell sampler as the established S1-right projection.
  // No player-position or facing exceptions.
  private bool IsStairsDownS1LeftReferencePose()
  {
    if (!stairsS1LeftPreviewEnabled
        || !TryGetStairsDownS1LeftCell(out int mapX, out int mapY))
      return false;
    return IsPreviewFeatureEnabled(
        MakePreviewFeatureKey("StairsDown", mapX, mapY, null));
  }

  // D1-left: same stairs tile can be viewed from the opposite side.
  private bool TryGetStairsDownS1LeftCell(out int mapX, out int mapY)
  {
    mapX = 0;
    mapY = 0;
    EnsurePreviewMiniMapLoaded();

    if (previewMiniMap == null)
    {
      return false;
    }

    Viewport17Cell diagonal = SampleViewport17Cell(-1, 1);
    Viewport17Cell nearLeft = SampleViewport17Cell(-1, 0);
    bool adjacentSolid = IsViewport17Solid(nearLeft);
    bool hasDownStairs = diagonal.IsInside && diagonal.IsStairsDown;
    bool passes = hasDownStairs && !adjacentSolid;
    if (!passes)
      return false;
    mapX = diagonal.MapX;
    mapY = diagonal.MapY;
    return true;
  }

  private void BlitStairsDownLeftD1IntoPreview(Color32[] pixels)
  {
    if (pixels == null)
      return;
    // Render only when the sampled D1-left map cell contains enabled down stairs.
    if (!IsStairsDownS1LeftReferencePose())
      return;
    Texture2D texture = AssetDatabase.LoadAssetAtPath<Texture2D>(
        StairsDownRightD1AssetPath);
    if (texture == null || texture.width != 32 || texture.height != 91)
    {
      Debug.LogError("STAIRS S1 LEFT: missing or invalid 32x91 PNG at "
          + StairsDownRightD1AssetPath);
      return;
    }
    if (!texture.isReadable)
    {
      Debug.LogError("STAIRS S1 LEFT: PNG texture must be Read/Write enabled: "
          + StairsDownRightD1AssetPath);
      return;
    }
    int destinationY = DungeonViewportHeight - stairsS1LeftTopY - texture.height;
    BlitPieceIntoPreview(pixels, texture, stairsS1LeftX,
        destinationY, stairsS1LeftMirror);
  }

  private static string MakePreviewFeatureKey(
      string family,
      int mapX,
      int mapY,
      string wall)
  {
    return (family ?? string.Empty)
        + ":" + mapX
        + ":" + mapY
        + ":" + (wall ?? string.Empty);
  }

  private bool IsPreviewFeatureEnabled(string key)
  {
    return string.IsNullOrEmpty(key)
        || !previewDisabledFeatureKeys.Contains(key);
  }

  private void SetPreviewFeatureEnabled(string key, bool enabled)
  {
    if (string.IsNullOrEmpty(key))
      return;

    if (enabled)
      previewDisabledFeatureKeys.Remove(key);
    else
      previewDisabledFeatureKeys.Add(key);
  }

  private void ApplyPreviewFeatureRenderOverrides(
      string key,
      ref int x,
      ref int y,
      ref bool mirror)
  {
    if (string.IsNullOrEmpty(key))
      return;

    if (previewFeaturePositionOverrides.TryGetValue(key, out Vector2Int pos))
    {
      x = pos.x;
      y = pos.y;
    }

    if (previewFeatureMirrorOverrides.TryGetValue(key, out bool mirrorOverride))
      mirror = mirrorOverride;
  }

  private bool TryGetChampionMirrorViewProjection(
      ChampionMirrorPlacement mirror,
      out int renderX,
      out int renderY,
      out bool renderMirror)
  {
    renderX = 0;
    renderY = 0;
    renderMirror = false;

    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || mirror == null
        || string.IsNullOrEmpty(mirror.wall))
    {
      return false;
    }

    DungeonMap.GetForwardOffset(previewFacing, out int forwardX, out int forwardY);
    DungeonMap.GetRightOffset(previewFacing, out int rightX, out int rightY);

    string frontWallSide = FacingName(OppositePreviewFacing(previewFacing));
    string leftWallSide = FacingName(TurnPreviewFacingRight(previewFacing));
    string rightWallSide = FacingName(TurnPreviewFacingLeft(previewFacing));
    string parallelWallSide = FacingName(previewFacing);

    int d1CenterX = previewX + forwardX;
    int d1CenterY = previewY + forwardY;
    int d2CenterX = previewX + forwardX * 2;
    int d2CenterY = previewY + forwardY * 2;
    int d3CenterX = previewX + forwardX * 3;
    int d3CenterY = previewY + forwardY * 3;

    // F0-right glimpse.
    int f0RightX = previewX + rightX;
    int f0RightY = previewY + rightY;
    if (mirror.x == f0RightX
        && mirror.y == f0RightY
        && string.Equals(mirror.wall, parallelWallSide, System.StringComparison.OrdinalIgnoreCase)
        && PreviewTileIsWall(f0RightX, f0RightY))
    {
      renderX = championMirrorD0RightPreviewX;
      renderY = ChampionMirrorD0RightY;
      renderMirror = championMirrorD0RightPreviewMirror;
      return true;
    }

    // D1 front.
    if (mirror.x == d1CenterX
        && mirror.y == d1CenterY
        && string.Equals(mirror.wall, frontWallSide, System.StringComparison.OrdinalIgnoreCase)
        && PreviewTileIsWall(d1CenterX, d1CenterY))
    {
      renderX = ChampionMirrorD1FrontX;
      renderY = ChampionMirrorD1FrontY;
      renderMirror = false;
      return true;
    }

    // D1 side frames require an open D1 center.
    if (PreviewTileIsOpen(d1CenterX, d1CenterY))
    {
      int d1LeftX = d1CenterX - rightX;
      int d1LeftY = d1CenterY - rightY;
      if (mirror.x == d1LeftX
          && mirror.y == d1LeftY
          && string.Equals(mirror.wall, leftWallSide, System.StringComparison.OrdinalIgnoreCase))
      {
        renderX = ChampionMirrorD1LeftX;
        renderY = ChampionMirrorD1Y;
        renderMirror = false;
        return true;
      }

      int d1RightX = d1CenterX + rightX;
      int d1RightY = d1CenterY + rightY;
      if (mirror.x == d1RightX
          && mirror.y == d1RightY
          && string.Equals(mirror.wall, rightWallSide, System.StringComparison.OrdinalIgnoreCase))
      {
        renderX = ChampionMirrorD1RightX;
        renderY = ChampionMirrorD1Y;
        renderMirror = true;
        return true;
      }
    }

    // D2 front lanes use an open D1 center, and lateral lanes also need the
    // corresponding D1 side lane open.
    if (PreviewTileIsOpen(d1CenterX, d1CenterY))
    {
      for (int lane = -1; lane <= 1; lane++)
      {
        if (lane != 0)
        {
          int d1LaneX = d1CenterX + rightX * lane;
          int d1LaneY = d1CenterY + rightY * lane;
          if (!PreviewTileIsOpen(d1LaneX, d1LaneY))
            continue;
        }

        int d2X = d2CenterX + rightX * lane;
        int d2Y = d2CenterY + rightY * lane;
        if (mirror.x == d2X
            && mirror.y == d2Y
            && string.Equals(mirror.wall, frontWallSide, System.StringComparison.OrdinalIgnoreCase)
            && PreviewTileIsWall(d2X, d2Y))
        {
          renderX = lane < 0
              ? ChampionMirrorD2FrontLeftX
              : lane > 0
                  ? ChampionMirrorD2FrontRightX
                  : ChampionMirrorD2FrontX;
          renderY = ChampionMirrorFrontWallOrnamentSet.f2.y;
          renderMirror = false;
          return true;
        }
      }
    }

    // D2 side mirrors require the center sight line to stay open through D2.
    if (PreviewTileIsOpen(d1CenterX, d1CenterY)
        && PreviewTileIsOpen(d2CenterX, d2CenterY))
    {
      int d2LeftX = d2CenterX - rightX;
      int d2LeftY = d2CenterY - rightY;
      if (mirror.x == d2LeftX
          && mirror.y == d2LeftY
          && string.Equals(mirror.wall, leftWallSide, System.StringComparison.OrdinalIgnoreCase))
      {
        renderX = ChampionMirrorD2LeftX;
        renderY = ChampionMirrorD2SideY;
        renderMirror = false;
        return true;
      }

      int d2RightX = d2CenterX + rightX;
      int d2RightY = d2CenterY + rightY;
      if (mirror.x == d2RightX
          && mirror.y == d2RightY
          && string.Equals(mirror.wall, rightWallSide, System.StringComparison.OrdinalIgnoreCase))
      {
        renderX = ChampionMirrorD2RightX;
        renderY = ChampionMirrorD2SideY;
        renderMirror = true;
        return true;
      }
    }

    // D3 front center.
    if (mirror.x == d3CenterX
        && mirror.y == d3CenterY
        && string.Equals(mirror.wall, frontWallSide, System.StringComparison.OrdinalIgnoreCase))
    {
      renderX = ChampionMirrorD3FrontX;
      renderY = ChampionMirrorD3FrontY;
      renderMirror = false;
      return true;
    }

    if (PreviewTileIsOpen(d1CenterX, d1CenterY)
        && PreviewTileIsOpen(d2CenterX, d2CenterY)
        && PreviewTileIsOpen(d3CenterX, d3CenterY))
    {
      int d3LeftX = d3CenterX - rightX;
      int d3LeftY = d3CenterY - rightY;
      if (mirror.x == d3LeftX
          && mirror.y == d3LeftY
          && string.Equals(mirror.wall, leftWallSide, System.StringComparison.OrdinalIgnoreCase)
          && PreviewTileIsWall(d3LeftX, d3LeftY))
      {
        renderX = ChampionMirrorD3LeftX;
        renderY = ChampionMirrorD3LeftY;
        renderMirror = false;
        return true;
      }

      int d3RightX = d3CenterX + rightX;
      int d3RightY = d3CenterY + rightY;
      if (mirror.x == d3RightX
          && mirror.y == d3RightY
          && string.Equals(mirror.wall, rightWallSide, System.StringComparison.OrdinalIgnoreCase)
          && PreviewTileIsWall(d3RightX, d3RightY))
      {
        renderX = ChampionMirrorD3RightF3X;
        renderY = ChampionMirrorD3RightF3Y;
        renderMirror = true;
        return true;
      }
    }

    // D3 second side lane / oblique projections.
    int d1LeftOpenX = d1CenterX - rightX;
    int d1LeftOpenY = d1CenterY - rightY;
    int d2LeftOpenX = d2CenterX - rightX;
    int d2LeftOpenY = d2CenterY - rightY;
    int d3LeftOpenX = d3CenterX - rightX;
    int d3LeftOpenY = d3CenterY - rightY;
    int d3L2X = d3CenterX - rightX * 2;
    int d3L2Y = d3CenterY - rightY * 2;
    if (PreviewTileIsOpen(d1CenterX, d1CenterY)
        && PreviewTileIsOpen(d1LeftOpenX, d1LeftOpenY)
        && PreviewTileIsOpen(d2LeftOpenX, d2LeftOpenY)
        && PreviewTileIsOpen(d3LeftOpenX, d3LeftOpenY)
        && PreviewTileIsWall(d3L2X, d3L2Y)
        && mirror.x == d3L2X
        && mirror.y == d3L2Y
        && string.Equals(mirror.wall, leftWallSide, System.StringComparison.OrdinalIgnoreCase))
    {
      renderX = ChampionMirrorD3LeftL2X;
      renderY = ChampionMirrorD3LeftL2Y;
      renderMirror = false;
      return true;
    }

    int d1RightOpenX = d1CenterX + rightX;
    int d1RightOpenY = d1CenterY + rightY;
    int d2RightOpenX = d2CenterX + rightX;
    int d2RightOpenY = d2CenterY + rightY;
    int d3RightOpenX = d3CenterX + rightX;
    int d3RightOpenY = d3CenterY + rightY;
    int d3R2X = d3CenterX + rightX * 2;
    int d3R2Y = d3CenterY + rightY * 2;
    if (PreviewTileIsOpen(d1CenterX, d1CenterY)
        && PreviewTileIsOpen(d1RightOpenX, d1RightOpenY)
        && PreviewTileIsOpen(d2RightOpenX, d2RightOpenY)
        && PreviewTileIsOpen(d3RightOpenX, d3RightOpenY)
        && PreviewTileIsWall(d3R2X, d3R2Y)
        && mirror.x == d3R2X
        && mirror.y == d3R2Y
        && string.Equals(mirror.wall, rightWallSide, System.StringComparison.OrdinalIgnoreCase))
    {
      renderX = ChampionMirrorD3RightX;
      renderY = ChampionMirrorD3RightY;
      renderMirror = true;
      return true;
    }

    return false;
  }

  private bool TryGetGrateViewProjection(
      WallOrnamentPlacement ornament,
      out string projectionName,
      out bool renderMirror)
  {
    projectionName = null;
    renderMirror = false;
    if (!IsGrateOrnament(ornament) || previewMiniMap == null)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    // Front F1.
    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    if (previewMiniMap.IsInside(d1X, d1Y)
        && previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall)
    {
      bool match = ornament.wallTilePlacement
          ? ornament.x == d1X
              && ornament.y == d1Y
              && string.Equals(
                  ornament.wall,
                  visiblePhysicalWallFace,
                  System.StringComparison.OrdinalIgnoreCase)
          : ornament.x == previewX
              && ornament.y == previewY
              && string.Equals(
                  ornament.wall,
                  viewedWallSide,
                  System.StringComparison.OrdinalIgnoreCase);
      if (match)
      {
        projectionName = "Grate - Front F1";
        renderMirror = false;
        return true;
      }
    }

    // Front F2.
    int d2X = previewX + forwardX * 2;
    int d2Y = previewY + forwardY * 2;
    if (previewMiniMap.IsInside(d1X, d1Y)
        && previewMiniMap.GetTile(d1X, d1Y).Type != DungeonTileType.Wall
        && previewMiniMap.IsInside(d2X, d2Y)
        && previewMiniMap.GetTile(d2X, d2Y).Type == DungeonTileType.Wall)
    {
      bool match = ornament.wallTilePlacement
          ? ornament.x == d2X
              && ornament.y == d2Y
              && string.Equals(
                  ornament.wall,
                  visiblePhysicalWallFace,
                  System.StringComparison.OrdinalIgnoreCase)
          : ornament.x == d1X
              && ornament.y == d1Y
              && string.Equals(
                  ornament.wall,
                  viewedWallSide,
                  System.StringComparison.OrdinalIgnoreCase);
      if (match)
      {
        projectionName = "Grate - Front F2";
        renderMirror = false;
        return true;
      }
    }

    // Front F3.
    int d3X = previewX + forwardX * 3;
    int d3Y = previewY + forwardY * 3;
    if (previewMiniMap.IsInside(d1X, d1Y)
        && previewMiniMap.GetTile(d1X, d1Y).Type != DungeonTileType.Wall
        && previewMiniMap.IsInside(d2X, d2Y)
        && previewMiniMap.GetTile(d2X, d2Y).Type != DungeonTileType.Wall
        && previewMiniMap.IsInside(d3X, d3Y)
        && previewMiniMap.GetTile(d3X, d3Y).Type == DungeonTileType.Wall)
    {
      bool match = ornament.wallTilePlacement
          ? ornament.x == d3X
              && ornament.y == d3Y
              && string.Equals(
                  ornament.wall,
                  visiblePhysicalWallFace,
                  System.StringComparison.OrdinalIgnoreCase)
          : ornament.x == d2X
              && ornament.y == d2Y
              && string.Equals(
                  ornament.wall,
                  viewedWallSide,
                  System.StringComparison.OrdinalIgnoreCase);
      if (match)
      {
        projectionName = "Grate - Front F3";
        renderMirror = false;
        return true;
      }
    }

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    // Side projections at D1..D3. These intentionally use the same geometry
    // tests as the grate renderer so ViewEdit lists only an image that can
    // actually be drawn in the current pose.
    for (int depth = 1; depth <= 3; depth++)
    {
      bool corridorOpen = true;
      for (int step = 1; step <= depth; step++)
      {
        int cx = previewX + forwardX * step;
        int cy = previewY + forwardY * step;
        if (!previewMiniMap.IsInside(cx, cy)
            || previewMiniMap.GetTile(cx, cy).Type == DungeonTileType.Wall)
        {
          corridorOpen = false;
          break;
        }
      }
      if (!corridorOpen)
        continue;

      int centerX = previewX + forwardX * depth;
      int centerY = previewY + forwardY * depth;
      int leftWallX = centerX - rightX;
      int leftWallY = centerY - rightY;
      int rightWallX = centerX + rightX;
      int rightWallY = centerY + rightY;

      bool leftWallExists =
          previewMiniMap.IsInside(leftWallX, leftWallY)
          && previewMiniMap.GetTile(leftWallX, leftWallY).Type
              == DungeonTileType.Wall;
      bool rightWallExists =
          previewMiniMap.IsInside(rightWallX, rightWallY)
          && previewMiniMap.GetTile(rightWallX, rightWallY).Type
              == DungeonTileType.Wall;

      bool matchesLeft = ornament.wallTilePlacement
          ? leftWallExists
              && ornament.x == leftWallX
              && ornament.y == leftWallY
              && string.Equals(
                  ornament.wall,
                  leftPhysicalFace,
                  System.StringComparison.OrdinalIgnoreCase)
          : leftWallExists
              && ornament.x == centerX
              && ornament.y == centerY
              && string.Equals(
                  ornament.wall,
                  leftBoundaryDirection,
                  System.StringComparison.OrdinalIgnoreCase);

      if (matchesLeft)
      {
        projectionName = "Grate - Side" + depth;
        renderMirror = false;
        return true;
      }

      bool matchesRight = ornament.wallTilePlacement
          ? rightWallExists
              && ornament.x == rightWallX
              && ornament.y == rightWallY
              && string.Equals(
                  ornament.wall,
                  rightPhysicalFace,
                  System.StringComparison.OrdinalIgnoreCase)
          : rightWallExists
              && ornament.x == centerX
              && ornament.y == centerY
              && string.Equals(
                  ornament.wall,
                  rightBoundaryDirection,
                  System.StringComparison.OrdinalIgnoreCase);

      if (matchesRight)
      {
        projectionName = "Grate - Side" + depth;
        renderMirror = true;
        return true;
      }
    }

    return false;
  }

  private bool TryGetWallOrnamentCalibrationDefaults(
      WallOrnamentPlacement ornament,
      out int renderX,
      out int renderY,
      out bool renderMirror)
  {
    renderX = 0;
    renderY = 0;
    renderMirror = false;
    if (ornament == null || previewMiniMap == null)
      return false;

    if (IsGrateOrnament(ornament))
    {
      if (!TryGetGrateViewProjection(
              ornament, out string projectionName, out renderMirror))
        return false;

      if (projectionName == "Grate - Front F1")
      { renderX = GrateD1FrontX; renderY = GrateD1FrontY; return true; }
      if (projectionName == "Grate - Front F2")
      { renderX = GrateD2FrontX; renderY = GrateD2FrontY; return true; }
      if (projectionName == "Grate - Front F3")
      { renderX = GrateD3FrontX; renderY = GrateD3FrontY; return true; }
      if (projectionName == "Grate - Side1")
      {
        renderX = renderMirror ? GrateD1SideRightX : GrateD1SideLeftX;
        renderY = GrateD1SideY;
        return true;
      }
      if (projectionName == "Grate - Side2")
      {
        renderX = renderMirror ? GrateD2SideRightX : GrateD2SideLeftX;
        renderY = GrateD2SideY;
        return true;
      }
      if (projectionName == "Grate - Side3")
      {
        renderX = renderMirror ? GrateD3SideRightX : GrateD3SideLeftX;
        renderY = GrateD3SideY;
        return true;
      }
      return false;
    }

    int maxFrontDepth = IsWoodRingOrnament(ornament) ? 3
        : IsHookOrnament(ornament) ? 2
        : IsSlimeOrnament(ornament) ? 3
        : IsManaclesOrnament(ornament) ? 3
        : IsViAltarOrnament(ornament) ? 3 : 0;
    int maxSideDepth = IsWoodRingOrnament(ornament) ? 3
        : IsHookOrnament(ornament) ? 3
        : IsSlimeOrnament(ornament) ? 2
        : IsManaclesOrnament(ornament) ? 2
        : IsViAltarOrnament(ornament) ? 0 : 0;
    if (maxFrontDepth == 0)
      return false;

    if (IsWoodRingOrnament(ornament)
        && TryGetOriginalSouthWoodRingLeftDepth(ornament, out int southViewDepth))
    {
      renderMirror = false;
      if (southViewDepth == 1)
      {
        renderX = WoodRingD1SideLeftX;
        renderY = WoodRingD1SideY;
        return true;
      }
      if (southViewDepth == 2)
      {
        renderX = WoodRingD2SideLeftX;
        renderY = WoodRingD2SideY;
        return true;
      }
      if (southViewDepth == 3)
      {
        renderX = WoodRingD3SideLeftX;
        renderY = WoodRingD3SideY;
        return true;
      }
    }

    if (!TryGetStandardWallOrnamentProjectionInCurrentPose(
            ornament,
            maxFrontDepth,
            maxSideDepth,
            out int mapX,
            out int mapY,
            out string mapFace))
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing, out int forwardX, out int forwardY);
    int depthFromPlayer =
        (mapX - previewX) * forwardX + (mapY - previewY) * forwardY;
    string frontFace = FacingName(previewFacing);
    bool isFront = string.Equals(
        mapFace, frontFace, System.StringComparison.OrdinalIgnoreCase);

    if (isFront)
    {
      int frontDepth = depthFromPlayer + 1;
      renderMirror = false;
      if (IsWoodRingOrnament(ornament))
      {
        if (frontDepth == 1)
        {
          Texture2D t = GetWoodRingFrontTexture();
          if (t == null) return false;
          renderX = 112 - (t.width / 2);
          renderY = 114 - (t.height / 2);
          return true;
        }
        if (frontDepth == 2)
        { renderX = HookFrontWallOrnamentSet.f2.x; renderY = HookFrontWallOrnamentSet.f2.y; return true; }
        if (frontDepth == 3)
        { renderX = HookFrontWallOrnamentSet.f3.x; renderY = HookFrontWallOrnamentSet.f3.y; return true; }
      }
      if (IsHookOrnament(ornament))
      {
        if (frontDepth == 1) { renderX = HookD1FrontX; renderY = HookD1FrontY; return true; }
        if (frontDepth == 2) { renderX = HookD2FrontX; renderY = HookD2FrontY; return true; }
      }
      if (IsSlimeOrnament(ornament))
      {
        if (frontDepth == 1)
        {
          Texture2D t = GetSlimeFrontTexture();
          if (t == null) return false;
          renderX = 112 - (t.width / 2);
          renderY = 55 - (t.height / 2);
          return true;
        }
        if (frontDepth == 2)
        {
          Texture2D t = GetSlimeGeneratedF2FrontTexture();
          if (t == null) return false;
          renderX = (DungeonViewportWidth - t.width) / 2;
          renderY = SlimeD2SideY;
          return true;
        }
        if (frontDepth == 3)
        {
          renderX = SlimeD3FrontX;
          renderY = SlimeD3FrontY;
          return true;
        }
      }
      if (IsManaclesOrnament(ornament))
      {
        if (frontDepth == 1)
        {
          Texture2D t = GetManaclesF1Texture();
          if (t == null) return false;
          renderX = (DungeonViewportWidth - t.width) / 2;
          renderY = 77;
          return true;
        }
        if (frontDepth == 2) { renderX = ManaclesD2FrontX; renderY = ManaclesD2FrontY; return true; }
        if (frontDepth == 3) { renderX = ManaclesD3FrontX; renderY = ManaclesD3FrontY; return true; }
      }
      if (IsViAltarOrnament(ornament))
      {
        if (frontDepth == 1) { renderX = ViAltarD1FrontX; renderY = ViAltarD1FrontY; return true; }
        if (frontDepth == 2)
        {
          renderX = ViAltarEngineF2FrontX;
          renderY = ViAltarEngineF2FrontY;
          return true;
        }
        if (frontDepth == 3)
        {
          renderX = ViAltarEngineF3FrontX;
          renderY = ViAltarEngineF3FrontY;
          return true;
        }
      }
      return false;
    }

    int sideDepth = depthFromPlayer;
    string leftFace = FacingName(TurnPreviewFacingLeft(previewFacing));
    bool isLeft = string.Equals(
        mapFace, leftFace, System.StringComparison.OrdinalIgnoreCase);

    if (IsWoodRingOrnament(ornament))
    {
      // Facing south, the (3,4) East wood ring stays on the left.
      // 4,4 South is D1 left, 4,3 South is D2 left, 4,2 South is D3 left.
      if (TryGetOriginalSouthWoodRingLeftDepth(ornament, out int southDepth))
      {
        renderMirror = false;
        if (southDepth == 1)
        {
          renderX = WoodRingD1SideLeftX;
          renderY = WoodRingD1SideY;
          return true;
        }
        if (southDepth == 2)
        {
          renderX = WoodRingD2SideLeftX;
          renderY = WoodRingD2SideY;
          return true;
        }
        if (southDepth == 3)
        {
          renderX = WoodRingD3SideLeftX;
          renderY = WoodRingD3SideY;
          return true;
        }
      }

      renderMirror = !isLeft;
      if (sideDepth == 1) { renderX = isLeft ? WoodRingD1SideLeftX : WoodRingD1SideRightX; renderY = WoodRingD1SideY; return true; }
      if (sideDepth == 2) { renderX = isLeft ? WoodRingD2SideLeftX : WoodRingD2SideRightX; renderY = WoodRingD2SideY; return true; }
      if (sideDepth == 3) { renderX = isLeft ? WoodRingD3SideLeftX : WoodRingD3SideRightX; renderY = WoodRingD3SideY; return true; }
    }
    if (IsHookOrnament(ornament))
    {
      if (sideDepth == 1)
      {
        renderMirror = !isLeft;
        renderX = isLeft ? HookD1SideLeftX : HookD1SideRightX;
        renderY = HookD1SideY;
        return true;
      }
      if (sideDepth == 2)
      {
        renderMirror = isLeft;
        renderX = isLeft ? HookD2SideLeftX : HookD2SideRightX;
        renderY = HookD2SideY;
        return true;
      }
      if (sideDepth == 3)
      {
        renderMirror = isLeft;
        renderX = isLeft ? HookD3SideLeftX : HookD3SideRightX;
        renderY = HookD3SideY;
        return true;
      }
    }
    if (IsSlimeOrnament(ornament))
    {
      if (sideDepth == 1)
      {
        renderMirror = !isLeft;
        renderX = isLeft ? SlimeD1SideLeftX : SlimeD1SideRightX;
        renderY = SlimeD1SideY;
        return true;
      }
      if (sideDepth == 2)
      {
        renderMirror = isLeft;
        renderX = isLeft ? SlimeD2SideLeftX : SlimeD2SideRightX;
        renderY = SlimeD2SideY;
        return true;
      }
    }
    if (IsManaclesOrnament(ornament))
    {
      renderMirror = !isLeft;
      if (sideDepth == 1) { renderX = isLeft ? ManaclesD1SideLeftX : ManaclesD1SideRightX; renderY = ManaclesD1SideY; return true; }
      if (sideDepth == 2) { renderX = isLeft ? ManaclesD2SideLeftX : ManaclesD2SideRightX; renderY = ManaclesD2SideY; return true; }
    }

    return false;
  }

  private bool TryGetWallOrnamentProjectionOverrideDescriptor(
      WallOrnamentPlacement ornament,
      out string overrideKey,
      out string projectionSuffix)
  {
    overrideKey = null;
    projectionSuffix = null;
    if (ornament == null || previewMiniMap == null)
      return false;

    string family = IsWoodRingOrnament(ornament) ? "WoodRing"
        : IsHookOrnament(ornament) ? "Hook"
        : IsSlimeOrnament(ornament) ? "Slime"
        : IsManaclesOrnament(ornament) ? "Manacles"
        : IsViAltarOrnament(ornament) ? "ViAltar"
        : IsGrateOrnament(ornament) ? "Grate"
        : null;
    if (string.IsNullOrEmpty(family))
      return false;

    if (IsGrateOrnament(ornament))
    {
      if (!TryGetGrateViewProjection(
              ornament, out string grateProjectionName, out _))
        return false;

      string grateSlot = grateProjectionName == "Grate - Front F1" ? "F1"
          : grateProjectionName == "Grate - Front F2" ? "F2"
          : grateProjectionName == "Grate - Front F3" ? "F3"
          : grateProjectionName == "Grate - Side1" ? "S1"
          : grateProjectionName == "Grate - Side2" ? "S2"
          : grateProjectionName == "Grate - Side3" ? "S3"
          : null;
      if (string.IsNullOrEmpty(grateSlot))
        return false;

      overrideKey = "OrnamentProjection:" + family + ":" + grateSlot;
      projectionSuffix = " / " + grateSlot;
      return true;
    }

    int maxFrontDepth = IsWoodRingOrnament(ornament) ? 3
        : IsHookOrnament(ornament) ? 2
        : IsSlimeOrnament(ornament) ? 3
        : IsManaclesOrnament(ornament) ? 3
        : IsViAltarOrnament(ornament) ? 3 : 0;
    int maxSideDepth = IsWoodRingOrnament(ornament) ? 3
        : IsHookOrnament(ornament) ? 3
        : IsSlimeOrnament(ornament) ? 2
        : IsManaclesOrnament(ornament) ? 2
        : IsViAltarOrnament(ornament) ? 0 : 0;
    if (maxFrontDepth == 0)
      return false;

    if (IsWoodRingOrnament(ornament)
        && TryGetOriginalSouthWoodRingLeftDepth(ornament, out int southViewDepth))
    {
      overrideKey = "OrnamentProjection:WoodRing:S" + southViewDepth;
      projectionSuffix = " / S" + southViewDepth;
      return true;
    }

    if (!TryGetStandardWallOrnamentProjectionInCurrentPose(
            ornament,
            maxFrontDepth,
            maxSideDepth,
            out int mapX,
            out int mapY,
            out string mapFace))
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing, out int forwardX, out int forwardY);
    int depthFromPlayer =
        (mapX - previewX) * forwardX + (mapY - previewY) * forwardY;
    string frontFace = FacingName(previewFacing);
    bool isFront = string.Equals(
        mapFace, frontFace, System.StringComparison.OrdinalIgnoreCase);

    string slot;
    if (isFront)
    {
      int frontDepth = depthFromPlayer + 1;
      if (frontDepth < 1 || frontDepth > maxFrontDepth)
        return false;
      slot = "F" + frontDepth;
    }
    else
    {
      int sideDepth = depthFromPlayer;
      if (IsWoodRingOrnament(ornament)
          && TryGetOriginalSouthWoodRingLeftDepth(ornament, out int southDepth))
        sideDepth = southDepth;
      if (sideDepth < 1 || sideDepth > maxSideDepth)
        return false;
      slot = "S" + sideDepth;
    }

    overrideKey = "OrnamentProjection:" + family + ":" + slot;
    projectionSuffix = " / " + slot;
    return true;
  }

  private static string ShortDirectionLabel(string direction)
  {
    if (string.IsNullOrEmpty(direction))
      return direction;

    switch (direction.Trim().ToLowerInvariant())
    {
      case "north": return "N";
      case "south": return "S";
      case "east":  return "E";
      case "west":  return "W";
      default:      return direction;
    }
  }

  private bool DrawWallOrnamentCalibrationRow(
      WallOrnamentPlacement ornament,
      string displayName)
  {
    if (!TryGetWallOrnamentCalibrationDefaults(
            ornament, out int codedX, out int codedY, out bool codedMirror))
      return false;

    string key = MakePreviewFeatureKey(
        "Ornament", ornament.x, ornament.y, ornament.wall);
    string projectionSuffix = null;
    bool hasGenericProjection =
        TryGetWallOrnamentProjectionOverrideDescriptor(
            ornament,
            out string projectionKey,
            out string resolvedProjectionSuffix);
    if (hasGenericProjection)
    {
      key = projectionKey;
      projectionSuffix = resolvedProjectionSuffix;
    }

    // The accepted generic reference becomes the baseline. Red indicates only
    // values that differ from this accepted reference.
    int defaultX = codedX;
    int defaultY = codedY;
    bool defaultMirror = codedMirror;
    if (hasGenericProjection)
      ApplyAcceptedOrnamentReference(
          key, ref defaultX, ref defaultY, ref defaultMirror);

    int x = defaultX;
    int y = defaultY;
    bool mirror = defaultMirror;
    ApplyPreviewFeatureRenderOverrides(key, ref x, ref y, ref mirror);

    if (!string.IsNullOrEmpty(projectionSuffix)
        && (displayName == null || !displayName.Contains(projectionSuffix)))
    {
      displayName += projectionSuffix;
    }

    EditorGUILayout.BeginHorizontal();
    float savedLabelWidth = EditorGUIUtility.labelWidth;

    GUIStyle featureStyle = new GUIStyle(EditorStyles.boldLabel);
    featureStyle.normal.textColor = Color.yellow;
    featureStyle.hover.textColor = Color.yellow;
    featureStyle.focused.textColor = Color.yellow;
    // Keep every ornament row aligned, but make the caption column only as
    // wide as the longest normal ornament label instead of leaving a large gap.
    float ornamentCaptionColumnWidth =
        featureStyle.CalcSize(
            new GUIContent("WoodRing [1,17] (S) / S1")).x;
    GUILayout.Label(
        displayName,
        featureStyle,
        GUILayout.Width(ornamentCaptionColumnWidth));

    // Hook toggles use the placement visibility key checked by the renderer.
    if (IsHookOrnament(ornament))
    {
      string hookVisibilityKey = MakePreviewFeatureKey(
          "Ornament", ornament.x, ornament.y, ornament.wall);
      bool wasEnabled = IsPreviewFeatureEnabled(hookVisibilityKey);
      bool nowEnabled = EditorGUILayout.ToggleLeft(
          "Set", wasEnabled, GUILayout.Width(76f));
      if (nowEnabled != wasEnabled)
      {
        SetPreviewFeatureEnabled(hookVisibilityKey, nowEnabled);
        RefreshEditModePreview();
        RepaintGameViews();
        Repaint();
      }
    }

    EditorGUIUtility.labelWidth =
        EditorStyles.label.CalcSize(new GUIContent("X")).x;
    int editX = x;
    bool xChanged = DrawIntStepperInline(
        "X", ref editX, snap, x != defaultX, true, 24f, 24f);

    EditorGUIUtility.labelWidth =
        EditorStyles.label.CalcSize(new GUIContent("Y")).x;
    int editY = y;
    bool yChanged = DrawIntStepperInline(
        "Y", ref editY, snap, y != defaultY, true, 24f, 24f);

    GUILayout.Space(6f);
    bool editMirror = EditorGUILayout.ToggleLeft(
        "Mirror", mirror, GUILayout.Width(66f));
    bool mirrorChanged = editMirror != mirror;
    bool applyClicked = false;
    if (hasGenericProjection)
    {
      applyClicked = GUILayout.Button(
          "Apply",
          GUILayout.Width(58f),
          GUILayout.ExpandWidth(false));
    }
    NoteContentRight();

    EditorGUIUtility.labelWidth = savedLabelWidth;
    EditorGUILayout.EndHorizontal();

    if (applyClicked)
    {
      // Apply is the acceptance action: the current X/Y/Mirror become the new
      // persistent generic reference for this ornament family + projection.
      if (SaveAcceptedOrnamentReference(key, editX, editY, editMirror))
      {
        previewFeaturePositionOverrides.Remove(key);
        previewFeatureMirrorOverrides.Remove(key);
        previewPositionChangedThisFrame = true;
        previewMirrorChangedThisFrame = true;
        RefreshEditModePreview();
        RepaintGameViews();
        Repaint();
      }
      return true;
    }

    bool changed = false;
    if (mirrorChanged)
    {
      if (editMirror == defaultMirror)
        previewFeatureMirrorOverrides.Remove(key);
      else
        previewFeatureMirrorOverrides[key] = editMirror;
      previewMirrorChangedThisFrame = true;
      changed = true;
    }
    if ((xChanged && editX != x) || (yChanged && editY != y))
    {
      if (editX == defaultX && editY == defaultY)
        previewFeaturePositionOverrides.Remove(key);
      else
        previewFeaturePositionOverrides[key] = new Vector2Int(editX, editY);
      previewPositionChangedThisFrame = true;
      changed = true;
    }

    if (changed)
    {
      RefreshEditModePreview();
      RepaintGameViews();
      Repaint();
    }

    return true;
  }

  private bool DrawGrateFeatureRow(WallOrnamentPlacement ornament)
  {
    if (!TryGetGrateViewProjection(
            ornament, out string projectionName, out _))
      return false;

    string name = projectionName + " [" + ornament.x + "," + ornament.y + "] (" + ShortDirectionLabel(FacingName(previewFacing)) + ")";
    return DrawWallOrnamentCalibrationRow(ornament, name);
  }

