  private bool IsViAltarOrnament(WallOrnamentPlacement ornament)
  {
    return ornament != null
        && (string.Equals(ornament.type, "ViAltar", System.StringComparison.OrdinalIgnoreCase)
            || string.Equals(ornament.type, "AltarOfVi", System.StringComparison.OrdinalIgnoreCase));
  }

  private bool TryGetViAltarS1Projection(
      WallOrnamentPlacement ornament,
      out int anchorX,
      out int anchorY,
      out string viewFacing,
      out bool defaultMirror)
  {
    anchorX = 0;
    anchorY = 0;
    viewFacing = null;
    defaultMirror = false;

    if (!IsViAltarOrnament(ornament) || previewMiniMap == null)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    // S1 is the first side projection: one open tile directly ahead, with
    // the altar mounted on either side boundary of that forward tile.
    int centerX = previewX + forwardX;
    int centerY = previewY + forwardY;
    if (!previewMiniMap.IsInside(centerX, centerY)
        || previewMiniMap.GetTile(centerX, centerY).Type == DungeonTileType.Wall)
    {
      return false;
    }

    int leftWallX = centerX - rightX;
    int leftWallY = centerY - rightY;
    int rightWallX = centerX + rightX;
    int rightWallY = centerY + rightY;

    bool leftWallExists =
        previewMiniMap.IsInside(leftWallX, leftWallY)
        && previewMiniMap.GetTile(leftWallX, leftWallY).Type
            == DungeonTileType.Wall;
    bool rightWallExists =
        previewMiniMap.IsInside(rightWallX, rightWallY)
        && previewMiniMap.GetTile(rightWallX, rightWallY).Type
            == DungeonTileType.Wall;

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    bool matchesLeft = ornament.wallTilePlacement
        ? leftWallExists
            && ornament.x == leftWallX
            && ornament.y == leftWallY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase)
        : leftWallExists
            && ornament.x == centerX
            && ornament.y == centerY
            && string.Equals(
                ornament.wall,
                leftBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);

    if (matchesLeft)
    {
      anchorX = centerX;
      anchorY = centerY;
      viewFacing = FacingName(previewFacing);
      // Verified S1 orientation: opposite-side projection uses the stored S1 asset.
      defaultMirror = false;
      return true;
    }

    bool matchesRight = ornament.wallTilePlacement
        ? rightWallExists
            && ornament.x == rightWallX
            && ornament.y == rightWallY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase)
        : rightWallExists
            && ornament.x == centerX
            && ornament.y == centerY
            && string.Equals(
                ornament.wall,
                rightBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);

    if (matchesRight)
    {
      anchorX = centerX;
      anchorY = centerY;
      viewFacing = FacingName(previewFacing);
      // Verified S1 reference: 3,17 East / altar 4,17 must render mirrored.
      defaultMirror = true;
      return true;
    }

    return false;
  }

  private bool TryGetViAltarS3Projection(
      WallOrnamentPlacement ornament,
      out int anchorX,
      out int anchorY,
      out string viewFacing,
      out bool defaultMirror)
  {
    anchorX = 0;
    anchorY = 0;
    viewFacing = null;
    defaultMirror = false;

    if (!IsViAltarOrnament(ornament) || previewMiniMap == null)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    // S3 is the third side projection. All three center corridor tiles must
    // remain open before the side wall at distance three can be visible.
    for (int distance = 1; distance <= 3; distance++)
    {
      int openX = previewX + forwardX * distance;
      int openY = previewY + forwardY * distance;
      if (!previewMiniMap.IsInside(openX, openY)
          || previewMiniMap.GetTile(openX, openY).Type == DungeonTileType.Wall)
      {
        return false;
      }
    }

    int centerX = previewX + forwardX * 3;
    int centerY = previewY + forwardY * 3;
    int leftWallX = centerX - rightX;
    int leftWallY = centerY - rightY;
    int rightWallX = centerX + rightX;
    int rightWallY = centerY + rightY;

    bool leftWallExists =
        previewMiniMap.IsInside(leftWallX, leftWallY)
        && previewMiniMap.GetTile(leftWallX, leftWallY).Type
            == DungeonTileType.Wall;
    bool rightWallExists =
        previewMiniMap.IsInside(rightWallX, rightWallY)
        && previewMiniMap.GetTile(rightWallX, rightWallY).Type
            == DungeonTileType.Wall;

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    bool matchesLeft = ornament.wallTilePlacement
        ? leftWallExists
            && ornament.x == leftWallX
            && ornament.y == leftWallY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase)
        : leftWallExists
            && ornament.x == centerX
            && ornament.y == centerY
            && string.Equals(
                ornament.wall,
                leftBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);

    if (matchesLeft)
    {
      anchorX = centerX;
      anchorY = centerY;
      viewFacing = FacingName(previewFacing);
      defaultMirror = false;
      return true;
    }

    bool matchesRight = ornament.wallTilePlacement
        ? rightWallExists
            && ornament.x == rightWallX
            && ornament.y == rightWallY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase)
        : rightWallExists
            && ornament.x == centerX
            && ornament.y == centerY
            && string.Equals(
                ornament.wall,
                rightBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);

    if (matchesRight)
    {
      anchorX = centerX;
      anchorY = centerY;
      viewFacing = FacingName(previewFacing);
      defaultMirror = true;
      return true;
    }

    return false;
  }

