  private bool TryGetStandardWallOrnamentProjectionInCurrentPose(
      WallOrnamentPlacement ornament,
      int maxFrontDepth,
      int maxSideDepth,
      out int dungeonFeatureX,
      out int dungeonFeatureY,
      out string dungeonFeatureFace)
  {
    dungeonFeatureX = ornament != null ? ornament.x : 0;
    dungeonFeatureY = ornament != null ? ornament.y : 0;
    dungeonFeatureFace = null;
    if (ornament == null || previewMiniMap == null)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    string viewedWallSide = FacingName(previewFacing);
    string visibleFrontFace = OppositeFacingName(previewFacing);

    // Front F1..F3. This is the same map geometry used by the ornament
    // renderers: every nearer center cell must be open, then the ornament
    // must belong to the front wall boundary at the requested depth.
    for (int depth = 1; depth <= Mathf.Min(3, maxFrontDepth); depth++)
    {
      bool corridorOpen = true;
      for (int step = 1; step < depth; step++)
      {
        int cx = previewX + forwardX * step;
        int cy = previewY + forwardY * step;
        if (!PreviewTileIsOpen(cx, cy))
        {
          corridorOpen = false;
          break;
        }
      }
      if (!corridorOpen)
        continue;

      int wallX = previewX + forwardX * depth;
      int wallY = previewY + forwardY * depth;
      if (!previewMiniMap.IsInside(wallX, wallY))
        continue;

      // F1 renderers require an actual wall directly ahead. F2/F3 use the
      // authoritative ornament placement after the nearer sight line is open.
      if (depth == 1 && !PreviewTileIsWall(wallX, wallY))
        continue;

      if (ornament.wallTilePlacement)
      {
        if (ornament.x == wallX
            && ornament.y == wallY
            && string.Equals(
                ornament.wall,
                visibleFrontFace,
                System.StringComparison.OrdinalIgnoreCase))
        {
          // Dungeon Features/ViewEdit describes the accessible corridor
          // square and the direction from that square toward the wall. The
          // renderer stores random ornaments on the solid wall tile itself.
          dungeonFeatureX = wallX - forwardX;
          dungeonFeatureY = wallY - forwardY;
          dungeonFeatureFace = viewedWallSide;
          return true;
        }
      }
      else
      {
        int storageX = previewX + forwardX * (depth - 1);
        int storageY = previewY + forwardY * (depth - 1);
        if (ornament.x == storageX
            && ornament.y == storageY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase))
        {
          dungeonFeatureX = storageX;
          dungeonFeatureY = storageY;
          dungeonFeatureFace = viewedWallSide;
          return true;
        }
      }
    }

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    // Side S1..S3. This mirrors the renderer exactly: the center corridor
    // must stay open through the requested depth and only the immediate wall
    // to the left/right of that center lane can carry the visible ornament.
    for (int depth = 1; depth <= Mathf.Min(3, maxSideDepth); depth++)
    {
      bool corridorOpen = true;
      for (int step = 1; step <= depth; step++)
      {
        int cx = previewX + forwardX * step;
        int cy = previewY + forwardY * step;
        if (!PreviewTileIsOpen(cx, cy))
        {
          corridorOpen = false;
          break;
        }
      }
      if (!corridorOpen)
        continue;

      int centerX = previewX + forwardX * depth;
      int centerY = previewY + forwardY * depth;
      int leftWallX = centerX - rightX;
      int leftWallY = centerY - rightY;
      int rightWallX = centerX + rightX;
      int rightWallY = centerY + rightY;

      bool leftWallExists = PreviewTileIsWall(leftWallX, leftWallY);
      bool rightWallExists = PreviewTileIsWall(rightWallX, rightWallY);

      if (ornament.wallTilePlacement)
      {
        if (leftWallExists
            && ornament.x == leftWallX
            && ornament.y == leftWallY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase))
        {
          dungeonFeatureX = centerX;
          dungeonFeatureY = centerY;
          dungeonFeatureFace = leftBoundaryDirection;
          return true;
        }

        if (rightWallExists
            && ornament.x == rightWallX
            && ornament.y == rightWallY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase))
        {
          dungeonFeatureX = centerX;
          dungeonFeatureY = centerY;
          dungeonFeatureFace = rightBoundaryDirection;
          return true;
        }
      }
      else
      {
        if (ornament.x == centerX && ornament.y == centerY)
        {
          if (leftWallExists
              && string.Equals(
                  ornament.wall,
                  leftBoundaryDirection,
                  System.StringComparison.OrdinalIgnoreCase))
          {
            dungeonFeatureX = centerX;
            dungeonFeatureY = centerY;
            dungeonFeatureFace = leftBoundaryDirection;
            return true;
          }

          if (rightWallExists
              && string.Equals(
                  ornament.wall,
                  rightBoundaryDirection,
                  System.StringComparison.OrdinalIgnoreCase))
          {
            dungeonFeatureX = centerX;
            dungeonFeatureY = centerY;
            dungeonFeatureFace = rightBoundaryDirection;
            return true;
          }
        }
      }
    }

    return false;
  }

  private bool IsStandardWallOrnamentProjectionVisibleInCurrentPose(
      WallOrnamentPlacement ornament,
      int maxFrontDepth,
      int maxSideDepth)
  {
    return TryGetStandardWallOrnamentProjectionInCurrentPose(
        ornament,
        maxFrontDepth,
        maxSideDepth,
        out _,
        out _,
        out _);
  }

  private bool TryGetStandardWallOrnamentDungeonFeatureFace(
      WallOrnamentPlacement ornament,
      out string dungeonFeatureFace)
  {
    dungeonFeatureFace = null;

    if (IsWoodRingOrnament(ornament))
    {
      return TryGetStandardWallOrnamentProjectionInCurrentPose(
          ornament, 3, 3, out _, out _, out dungeonFeatureFace);
    }

    if (IsHookOrnament(ornament))
    {
      return TryGetStandardWallOrnamentProjectionInCurrentPose(
          ornament, 2, 3, out _, out _, out dungeonFeatureFace);
    }

    if (IsSlimeOrnament(ornament))
    {
      return TryGetStandardWallOrnamentProjectionInCurrentPose(
          ornament, 3, 2, out _, out _, out dungeonFeatureFace);
    }

    return false;
  }

  private bool IsWoodRingProjectionVisibleInCurrentPose(
      WallOrnamentPlacement ornament)
  {
    return IsWoodRingOrnament(ornament)
        && (IsStandardWallOrnamentProjectionVisibleInCurrentPose(ornament, 3, 3)
            || TryGetOriginalSouthWoodRingLeftDepth(ornament, out _));
  }

  // Verified original reference: this east-facing Hook is not visible from
  // (4,14) South. Keep ViewEdit and the renderer in agreement.
  // This is a reference-pose exclusion, not yet a generic occlusion algorithm.
  private bool IsHookHiddenAtStairsS2Reference(WallOrnamentPlacement ornament)
  {
    if (!IsStairsdownS2CalibrationPose() || !IsHookOrnament(ornament))
      return false;

    // ViewEdit labels the projected dungeon-feature face, not necessarily
    // the ornament's storage tile/face. Match the same projected coordinates
    // here so the renderer and ViewEdit suppress the same Hook.
    return TryGetStandardWallOrnamentProjectionInCurrentPose(
        ornament, 2, 3, out int featureX, out int featureY,
        out string featureFace)
        && featureX == 4 && featureY == 15
        && string.Equals(featureFace, "East",
            System.StringComparison.OrdinalIgnoreCase);
  }

  private bool IsHookProjectionVisibleInCurrentPose(WallOrnamentPlacement ornament)
  {
    return IsHookOrnament(ornament)
        && !IsHookHiddenAtStairsS2Reference(ornament)
        && IsStandardWallOrnamentProjectionVisibleInCurrentPose(ornament, 2, 3);
  }

  private bool IsSlimeProjectionVisibleInCurrentPose(WallOrnamentPlacement ornament)
  {
    return IsSlimeOrnament(ornament)
        && !IsSlimeHiddenInCurrentPose(ornament)
        && IsStandardWallOrnamentProjectionVisibleInCurrentPose(ornament, 3, 2);
  }

  // Original 4,3 South and 4,4 South do not show the (5,5) West slime.
  private bool IsSlimeHiddenInCurrentPose(WallOrnamentPlacement ornament)
  {
    return ornament != null
        && IsSlimeOrnament(ornament)
        && previewFacing == DungeonFacing.South
        && previewX == 4
        && (previewY == 3 || previewY == 4)
        && ornament.x == 5
        && ornament.y == 5
        && string.Equals(
            ornament.wall,
            "West",
            System.StringComparison.OrdinalIgnoreCase);
  }


  private void DrawCurrentPoseFeatureRows()
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return;

    // Loose-item calibrations from the original Level 0 DUNGEON.DAT.
    DrawFloorItemRows();

    // Champion Mirrors. Only rows that correspond to a mirror projection the
    // renderer can actually draw for this pose are shown. X/Y are framebuffer
    // map coordinates and are temporary per-pose identifiers.
    if (previewChampionMirrors != null)
    {
      for (int i = 0; i < previewChampionMirrors.Length; i++)
      {
        ChampionMirrorPlacement mirror = previewChampionMirrors[i];
        if (mirror == null)
          continue;

        DrawChampionMirrorFeatureRow(mirror);
      }
    }

    // Ordinary wall ornaments.
    if (previewWallOrnaments != null)
    {
      for (int i = 0; i < previewWallOrnaments.Length; i++)
      {
        WallOrnamentPlacement ornament = previewWallOrnaments[i];
        if (ornament == null || IsHookHiddenAtStairsS2Reference(ornament))
          continue;

        // Vi Altar side projections use exact geometry before the broad
        // feature-cone filter.
        if (DrawViAltarS3CalibrationRow(ornament))
          continue;
        if (DrawViAltarS2CalibrationRow(ornament))
          continue;
        if (DrawViAltarS1CalibrationRow(ornament))
          continue;

        if (!IsMapCellInCurrentFeatureCone(ornament.x, ornament.y))
          continue;

        // Wood Rings must obey the exact same F1/F2/F3 and S1/S2/S3 wall
        // geometry as their renderer. The broad feature cone is only a cheap
        // neighbourhood prefilter and must never create a ViewEdit row by itself.
        if (IsWoodRingOrnament(ornament)
            && !IsWoodRingProjectionVisibleInCurrentPose(ornament))
        {
          continue;
        }

        // Hooks must obey the exact same front/side projection geometry as
        // the renderer.  The broad feature cone also contains outer cells
        // that are not valid Hook projection slots (for example 5,15 West
        // from pose 3,17 East), so those must not become ViewEdit rows.
        if (IsHookOrnament(ornament)
            && !IsHookProjectionVisibleInCurrentPose(ornament))
        {
          continue;
        }

        // Slime rows must obey the exact same F1/F2/F3/S1/S2 geometry as the
        // Slime renderer. The broad feature cone can include adjacent cells
        // that are not drawable Slime projection slots (for example 2,18
        // North from pose 2,17 East), so those must not appear in ViewEdit.
        if (IsSlimeOrnament(ornament)
            && !IsSlimeProjectionVisibleInCurrentPose(ornament))
        {
          continue;
        }

        // Grates have their own rendered-projection ViewEdit row. Only show
        // the grate if this exact ornament is actually drawable in this pose.
        if (IsGrateOrnament(ornament))
        {
          DrawGrateFeatureRow(ornament);
          continue;
        }

        // Champion Mirrors have their own dedicated ViewEdit row above.
        // Do not also show the generic wall-ornament entry for the same
        // physical mirror, otherwise ViewEdit contains two redundant rows.
        if (!string.IsNullOrEmpty(ornament.type)
            && ornament.type.IndexOf(
                "ChampionMirror",
                System.StringComparison.OrdinalIgnoreCase) >= 0)
        {
          bool hasDedicatedMirror = false;
          if (previewChampionMirrors != null)
          {
            for (int m = 0; m < previewChampionMirrors.Length; m++)
            {
              ChampionMirrorPlacement mirror = previewChampionMirrors[m];
              if (mirror == null)
                continue;

              if (mirror.x == ornament.x
                  && mirror.y == ornament.y
                  && string.Equals(
                      mirror.wall,
                      ornament.wall,
                      System.StringComparison.OrdinalIgnoreCase))
              {
                hasDedicatedMirror = true;
                break;
              }
            }
          }

          if (hasDedicatedMirror)
            continue;
        }

        string key = MakePreviewFeatureKey(
            "Ornament", ornament.x, ornament.y, ornament.wall);

        // A Manacles row should exist only when the Manacles are actually
        // visible in the current pose. This mirrors BlitManaclesD1FrontIntoPreview:
        // wall-tile Manacles must be on the wall cell directly in front of the
        // party and on the physical wall face visible from the current facing.
        //
        // Example:
        //   pose 4,9 West  -> wall storage 3,9 East -> visible as F1
        //   pose 4,9 North -> same Manacles are not on the front wall -> hidden
        //
        // ViewEdit displays viewpoint coordinates/facing rather than the
        // underlying storage-wall coordinates.
        int displayMapX = ornament.x;
        int displayMapY = ornament.y;
        string displayWall = ornament.wall;

        // For the standard wall ornaments, use the exact projection geometry
        // that made the ornament visible to derive the Dungeon Features/minimap
        // wall direction. This keeps the label absolute to the map instead of
        // blindly flipping every stored wall face or deriving it from the
        // player's relative view.
        int standardFrontDepth = IsWoodRingOrnament(ornament)
            ? 3
            : IsHookOrnament(ornament) ? 2 : IsSlimeOrnament(ornament) ? 3 : 0;
        int standardSideDepth = IsWoodRingOrnament(ornament)
            ? 3
            : IsHookOrnament(ornament) ? 3 : IsSlimeOrnament(ornament) ? 2 : 0;
        if (standardFrontDepth > 0
            && TryGetStandardWallOrnamentProjectionInCurrentPose(
                ornament,
                standardFrontDepth,
                standardSideDepth,
                out int projectedDungeonFeatureX,
                out int projectedDungeonFeatureY,
                out string projectedDungeonFeatureFace))
        {
          displayMapX = projectedDungeonFeatureX;
          displayMapY = projectedDungeonFeatureY;
          displayWall = projectedDungeonFeatureFace;
        }

        string manaclesDepthLabel = null;
        if (IsManaclesOrnament(ornament))
        {
          DungeonMap.GetForwardOffset(
              previewFacing,
              out int manaclesForwardX,
              out int manaclesForwardY);

          if (ornament.wallTilePlacement)
          {
            int directFrontWallX = previewX + manaclesForwardX;
            int directFrontWallY = previewY + manaclesForwardY;
            int f2FrontWallX = previewX + manaclesForwardX * 2;
            int f2FrontWallY = previewY + manaclesForwardY * 2;
            int f3FrontWallX = previewX + manaclesForwardX * 3;
            int f3FrontWallY = previewY + manaclesForwardY * 3;
            string visibleFace = OppositeFacingName(previewFacing);
            bool visibleAsF1 =
                ornament.x == directFrontWallX
                && ornament.y == directFrontWallY
                && string.Equals(
                    ornament.wall,
                    visibleFace,
                    System.StringComparison.OrdinalIgnoreCase);
            bool d1Open =
                previewMiniMap != null
                && previewMiniMap.IsInside(directFrontWallX, directFrontWallY)
                && previewMiniMap.GetTile(
                    directFrontWallX, directFrontWallY).Type
                    != DungeonTileType.Wall;
            bool d2Open =
                d1Open
                && previewMiniMap.IsInside(f2FrontWallX, f2FrontWallY)
                && previewMiniMap.GetTile(
                    f2FrontWallX, f2FrontWallY).Type
                    != DungeonTileType.Wall;
            bool visibleAsF2 =
                d1Open
                && ornament.x == f2FrontWallX
                && ornament.y == f2FrontWallY
                && string.Equals(
                    ornament.wall,
                    visibleFace,
                    System.StringComparison.OrdinalIgnoreCase);
            bool visibleAsF3 =
                d2Open
                && ornament.x == f3FrontWallX
                && ornament.y == f3FrontWallY
                && string.Equals(
                    ornament.wall,
                    visibleFace,
                    System.StringComparison.OrdinalIgnoreCase);

            bool visibleAsS1 = false;
            if (!visibleAsF1 && !visibleAsF2 && !visibleAsF3 && d1Open)
            {
              DungeonMap.GetRightOffset(
                  previewFacing,
                  out int manaclesRightX,
                  out int manaclesRightY);
              int leftWallX = directFrontWallX - manaclesRightX;
              int leftWallY = directFrontWallY - manaclesRightY;
              int rightWallX = directFrontWallX + manaclesRightX;
              int rightWallY = directFrontWallY + manaclesRightY;
              string leftFace = FacingName(TurnPreviewFacingRight(previewFacing));
              string rightFace = FacingName(TurnPreviewFacingLeft(previewFacing));
              visibleAsS1 =
                  (ornament.x == leftWallX
                      && ornament.y == leftWallY
                      && string.Equals(
                          ornament.wall,
                          leftFace,
                          System.StringComparison.OrdinalIgnoreCase))
                  || (ornament.x == rightWallX
                      && ornament.y == rightWallY
                      && string.Equals(
                          ornament.wall,
                          rightFace,
                          System.StringComparison.OrdinalIgnoreCase));
            }

            bool visibleAsS2 = false;
            if (!visibleAsF1 && !visibleAsF2 && !visibleAsF3 && !visibleAsS1 && d2Open)
            {
              DungeonMap.GetRightOffset(
                  previewFacing,
                  out int manaclesRightX,
                  out int manaclesRightY);
              int leftWallX = f2FrontWallX - manaclesRightX;
              int leftWallY = f2FrontWallY - manaclesRightY;
              int rightWallX = f2FrontWallX + manaclesRightX;
              int rightWallY = f2FrontWallY + manaclesRightY;
              string leftFace = FacingName(TurnPreviewFacingRight(previewFacing));
              string rightFace = FacingName(TurnPreviewFacingLeft(previewFacing));
              visibleAsS2 =
                  (ornament.x == leftWallX
                      && ornament.y == leftWallY
                      && string.Equals(
                          ornament.wall,
                          leftFace,
                          System.StringComparison.OrdinalIgnoreCase))
                  || (ornament.x == rightWallX
                      && ornament.y == rightWallY
                      && string.Equals(
                          ornament.wall,
                          rightFace,
                          System.StringComparison.OrdinalIgnoreCase));
            }

            if (!visibleAsF1 && !visibleAsF2 && !visibleAsF3
                && !visibleAsS1 && !visibleAsS2)
              continue;

            displayMapX = previewX;
            displayMapY = previewY;
            displayWall = FacingName(previewFacing);
            manaclesDepthLabel = visibleAsS1
                ? " / S1"
                : visibleAsS2
                    ? " / S2"
                    : visibleAsF1
                        ? " / F1"
                        : visibleAsF2 ? " / F2" : " / F3";
          }
          else
          {
            bool visibleInCurrentPose =
                ornament.x == previewX
                && ornament.y == previewY
                && string.Equals(
                    ornament.wall,
                    FacingName(previewFacing),
                    System.StringComparison.OrdinalIgnoreCase);

            if (!visibleInCurrentPose)
              continue;
          }
        }

        string name = string.IsNullOrEmpty(ornament.type)
            ? "Ornament"
            : ornament.type;

        // Show the dungeon-map position used by ViewEdit separately from the
        // following X/Y pixel calibration controls.
        name += " [" + displayMapX + "," + displayMapY + "]";

        if (!string.IsNullOrEmpty(displayWall))
          name += " (" + ShortDirectionLabel(displayWall) + ")";

        // ViewEdit labels use the current-view depth classification.
        // F1 is the wall one step ahead; F2 is two steps ahead.
        if (manaclesDepthLabel != null)
          name += manaclesDepthLabel;
        else if (IsManaclesOrnament(ornament)
            && displayMapX == previewX
            && displayMapY == previewY
            && string.Equals(
                displayWall,
                FacingName(previewFacing),
                System.StringComparison.OrdinalIgnoreCase))
        {
          name += " / F1";
        }

        DrawWallOrnamentCalibrationRow(ornament, name);
      }
    }

    // Floor puddles are ornaments too, but they are stored separately from
    // wallOrnaments in the parsed map data. Only list projections that the
    // puddle renderer can actually draw in the current pose. In particular,
    // there is no F0 puddle projection, so a puddle beside/under the player
    // must not appear in ViewEdit just because it is nearby on the map.
    DungeonMap.GetForwardOffset(
        previewFacing,
        out int puddleForwardX,
        out int puddleForwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int puddleRightX,
        out int puddleRightY);

    for (int depth = 1; depth <= 3; depth++)
    {
      int minLane = depth == 3 ? 0 : -1;
      int maxLane = depth == 3 ? 0 : 1;

      for (int lane = minLane; lane <= maxLane; lane++)
      {
        int x = previewX + puddleForwardX * depth + puddleRightX * lane;
        int y = previewY + puddleForwardY * depth + puddleRightY * lane;
        if (!IsPuddleProjectionVisibleInCurrentPose(x, y, depth, lane))
          continue;

        string key = MakePreviewFeatureKey("Puddle", x, y, null);
        DrawFeatureChecklistRow(
            x,
            y,
            "Puddle",
            key,
            new Color(0.3f, 0.75f, 1f));
      }
    }

    // Moss is a resolved floor ornament from the same database as puddles.
    // The current first implementation exposes the front F1/F2/F3 projections;
    // side projections can be added/calibrated separately if the original
    // reference requires them.
    DungeonMap.GetForwardOffset(
        previewFacing,
        out int mossForwardX,
        out int mossForwardY);

    for (int depth = 1; depth <= 3; depth++)
    {
      int x = previewX + mossForwardX * depth;
      int y = previewY + mossForwardY * depth;
      if (!previewMiniMap.IsInside(x, y)
          || !IsPreviewMossFloor(x, y)
          || !IsMossProjectionVisibleInCurrentPose(x, y, depth, 0))
      {
        continue;
      }

      Texture2D mossTexture =
          depth == 1 ? GetMossF1Texture()
          : depth == 2 ? GetMossF2Texture()
          : GetMossF3Texture();
      if (mossTexture == null)
        continue;

      int screenTop =
          depth == 1 ? MossF1ScreenTop
          : depth == 2 ? MossF2ScreenTop
          : MossF3ScreenTop;

      int codedX = (DungeonViewportWidth - mossTexture.width) / 2;
      int codedY = PreviewHeight - screenTop - mossTexture.height;
      string slot = "F" + depth;
      string name =
          "Moss [" + x + "," + y + "] ("
          + ShortDirectionLabel(FacingName(previewFacing))
          + ") / " + slot;

      DrawFloorOrnamentCalibrationRow(
          x,
          y,
          "Moss",
          slot,
          codedX,
          codedY,
          name);
    }

    // Stairs use the renderer's exact projection geometry. The current
    // stairs renderer has an F1 front projection only: the stairs tile must
    // be exactly one cell directly ahead. Do not list stairs merely because
    // they fall somewhere inside the broad ViewEdit neighbourhood/cone.
    DungeonMap.GetForwardOffset(
        previewFacing,
        out int stairsForwardX,
        out int stairsForwardY);

    int visibleStairsX = previewX + stairsForwardX;
    int visibleStairsY = previewY + stairsForwardY;
    if (previewMiniMap.IsInside(visibleStairsX, visibleStairsY))
    {
      DungeonTile visibleStairsTile =
          previewMiniMap.GetTile(visibleStairsX, visibleStairsY);
      if (visibleStairsTile != null
          && visibleStairsTile.TryGetStairsDirection(out bool stairsUp))
      {
        string family = stairsUp ? "StairsUp" : "StairsDown";
        string key = MakePreviewFeatureKey(
            family, visibleStairsX, visibleStairsY, null);

        if (stairsUp)
        {
          DrawFeatureChecklistRow(
              visibleStairsX,
              visibleStairsY,
              "Stairs Up",
              key,
              Color.magenta);
        }
        else
        {
          DrawStairsDownFeatureChecklistRow(
              visibleStairsX, visibleStairsY, key);
        }
      }
    }

    // Stairsdown S2 calibration for the verified (4,14) South view.
    // The D0L controls for (4,15) South are preserved unchanged.
    if (IsStairsdownS2CalibrationPose())
      DrawStairsdownS2CalibrationRow();
    // F2 North reference (4,16): independent S2 20x39 calibration.
    if (previewX == 4 && previewY == 16 && previewFacing == DungeonFacing.North)
      DrawStairsdownS2F2NorthCalibrationRow();
    // North S0 reference: independent calibration; does not modify South S2 or South S0.
    if (previewX == 4 && previewY == 15 && previewFacing == DungeonFacing.North)
      DrawStairsdownS2LeftCalibrationRow();

    // Always expose the calibration control at the reference pose, even if
    // stair-map detection is not yet correct. The draw path remains gated
    // independently; ViewEdit must make missing elements inspectable.
    if (previewX == 4 && previewY == 17 && previewFacing == DungeonFacing.North)
      DrawStairsS0D2NorthCalibrationRow();
    if (previewX == 4 && previewY == 13 && previewFacing == DungeonFacing.South)
      DrawStairsS3RightSouthCalibrationRow();

    if (IsPressurePadF1ReferencePose())
      DrawPressurePadF1CalibrationRow();
    if (IsStairsUpF1ReferencePose())
      DrawStairsUpF1CalibrationRow();
    if (IsStairsUpFrontS1ReferencePose())
      DrawStairsUpFrontS1CalibrationRow();
    if (IsStairsUpFrontS1LeftReferencePose())
      DrawStairsUpFrontS1LeftCalibrationRow();
    if (IsStairsUpFrontS2ReferencePose())
      DrawStairsUpFrontS2CalibrationRow();
    if (IsStairsUpFrontS2RightReferencePose())
      DrawStairsUpFrontS2RightCalibrationRow();
    if (IsStairsUpFrontS3ReferencePose())
      DrawStairsUpFrontS3CalibrationRow();
    if (IsStairsUpFrontS3RightReferencePose())
      DrawStairsUpFrontS3RightCalibrationRow();
    if (IsStairsUpS2ReferencePose())
    {
      DrawStairsUpS2CalibrationRow(false);
      DrawStairsUpS2CalibrationRow(true);
    }
    if (IsStairsLevel0S0ReferencePose())
    {
      DrawStairsLevel0S0CalibrationRow(false);
      DrawStairsLevel0S0CalibrationRow(true);
    }

    // D0L side artwork is visible when the stairs-down tile is immediately
    // to the player's right (the calibrated 4,15 South view). Use the same
    // relative map sampler as the wall renderer; do not require the player
    // to be standing on the stair tile.
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap != null)
    {
      Viewport17Cell stairsD0LCell = SampleViewport17Cell(1, 0);
      if (stairsD0LCell.IsInside && stairsD0LCell.IsStairsDown)
        DrawStairsDownD0LCalibrationRow();
    }

    // S1 is the D1-right viewport cell: one step forward, one step right.
    // IsStairsDown is the same classification the minimap and wall sampler
    // already use for this cell.
    if (TryGetStairsDownS1Cell(out int stairsS1XMap, out int stairsS1YMap))
      DrawStairsDownS1CalibrationRow(stairsS1XMap, stairsS1YMap);
    // Show the S1-left controls only for a map-defined, enabled stair.
    if (TryGetStairsDownS1LeftCell(out int leftStairsX, out int leftStairsY)
        && IsPreviewFeatureEnabled(MakePreviewFeatureKey(
            "StairsDown", leftStairsX, leftStairsY, null)))
      DrawStairsDownS1LeftCalibrationRow(leftStairsX, leftStairsY);
  }

  // Same-tile right-side down-stairs detail. Detection matches its ViewEdit row.
  private void BlitStairsDownD0LIntoPreview(Color32[] pixels)
  {
    if (pixels == null || !stairsD0LEnabled)
      return;

    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return;

    Viewport17Cell stairCell = SampleViewport17Cell(1, 0);
    if (!stairCell.IsInside || !stairCell.IsStairsDown)
      return;

    const string assetPath = "Assets/Art/Walls/Stairs/Stairs_Side_D0L_16x13.png";
    Texture2D sprite = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
    if (sprite == null)
    {
      Debug.LogError("STAIRS D0L: missing asset: " + assetPath);
      return;
    }
    if (sprite.width != 16 || sprite.height != 13)
    {
      Debug.LogError("STAIRS D0L: expected 16x13, got "
          + sprite.width + "x" + sprite.height + " at " + assetPath);
      return;
    }
    if (!sprite.isReadable)
    {
      Debug.LogError("STAIRS D0L: enable Read/Write on " + assetPath);
      return;
    }

    BlitPieceIntoPreview(pixels, sprite, stairsD0LX,
        DisplayYToUnityY(stairsD0LTopY, sprite.height), stairsD0LMirror);
  }

  // S0 left-side calibration at (4,15) North. Uses the same 16x13 artwork
