      EditorPrefs.SetBool(PressurePadF1Prefs + "Enabled", pressurePadF1Enabled);
      RefreshEditModePreview();
      RepaintGameViews();
      Repaint();
      if (updated != source)
        AssetDatabase.ImportAsset(sourcePath, ImportAssetOptions.ForceUpdate);
