  /// <summary>
  /// Down-stairs front when the cell one step ahead is a stairs tile
  /// whose raw direction bit is down.
  /// </summary>
  private void BlitStairsDownF1IntoPreview(Color32[] pixels)
  {
    if (pixels == null
        || !stairsDownF1PreviewEnabled
        || !IsStairsDownF1NeededForCurrentPose())
    {
      return;
    }

    Texture2D stairs = AssetDatabase.LoadAssetAtPath<Texture2D>(
        StairsDownF1AssetPath);
    if (stairs == null
        || stairs.width != 152
        || stairs.height != 92
        || !stairs.isReadable)
    {
      return;
    }

    int destinationY =
        DisplayYToUnityY(stairsDownF1PreviewDisplayY, stairs.height);

    BlitPieceIntoPreview(
        pixels,
        stairs,
        stairsDownF1PreviewX,
        destinationY,
        false);
  }

  private enum FloorItemDepth
  {
    SameTile = 0,
    OneAhead = 1,
    TwoAhead = 2
  }

  private static bool TryGetFloorItemSubSquareOffset(
      string cell,
      out int offsetX,
      out int offsetY)
  {
    // Dungeon Master N/E/S/W floor-item positions are corner slots.
    // Map Y increases south: N=NW, E=NE, S=SE, W=SW.
    offsetX = 0;
    offsetY = 0;
    switch ((cell ?? string.Empty).ToUpperInvariant())
    {
      case "N": offsetX = -1; offsetY = -1; return true;
      case "E": offsetX =  1; offsetY = -1; return true;
      case "S": offsetX =  1; offsetY =  1; return true;
      case "W": offsetX = -1; offsetY =  1; return true;
      default: return false;
    }
  }

  private static void GetFloorItemViewBasis(
      DungeonFacing facing,
      out int forwardX,
      out int forwardY,
      out int rightX,
      out int rightY)
  {
    switch (facing)
    {
      case DungeonFacing.North:
        forwardX = 0; forwardY = -1; rightX = 1; rightY = 0; break;
      case DungeonFacing.East:
        forwardX = 1; forwardY = 0; rightX = 0; rightY = 1; break;
      case DungeonFacing.South:
        forwardX = 0; forwardY = 1; rightX = -1; rightY = 0; break;
      default: // West
        forwardX = -1; forwardY = 0; rightX = 0; rightY = -1; break;
    }
  }

  private FloorItemPlacement[] GetCurrentFloorItems()
  {
    return previewDungeonLevel == 0
        ? HallOfChampionsFloorItems
        : new FloorItemPlacement[0];
  }

  private bool TryProjectFloorItem(
      FloorItemPlacement item,
      out FloorItemDepth depth,
      out bool isRight)
  {
    depth = FloorItemDepth.SameTile;
    isRight = false;
    if (item == null || previewMiniMap == null)
      return false;

    GetFloorItemViewBasis(
        previewFacing,
        out int forwardX,
        out int forwardY,
        out int rightX,
        out int rightY);

    int dx = item.x - previewX;
    int dy = item.y - previewY;
    int forwardDistance = dx * forwardX + dy * forwardY;
    int lateralTileDistance = dx * rightX + dy * rightY;

    // This pass handles the center corridor tile at the current square and
    // the next two map squares. Side-tile floor items can be added later as
    // a separate occlusion-aware projection, without coordinate hardcodes.
    if (lateralTileDistance != 0 || forwardDistance < 0 || forwardDistance > 2)
      return false;

    // A nearer wall hides the floor item. From 4,7 South the apple at 4,9
    // is behind the wall at 4,8 and must not be drawn on that wall.
    for (int step = 1; step <= forwardDistance; step++)
    {
      int stepX = previewX + forwardX * step;
      int stepY = previewY + forwardY * step;
      if (!PreviewTileIsOpen(stepX, stepY))
        return false;
    }

    if (!TryGetFloorItemSubSquareOffset(
            item.cell,
            out int cornerX,
            out int cornerY))
      return false;

    int cornerAhead = cornerX * forwardX + cornerY * forwardY;
    int cornerLateral = cornerX * rightX + cornerY * rightY;

    // On the party's own square only the front half of the floor is visible.
    if (forwardDistance == 0 && cornerAhead <= 0)
      return false;
    if (cornerLateral == 0)
      return false;

    isRight = cornerLateral > 0;
    depth = forwardDistance == 0
        ? FloorItemDepth.SameTile
        : forwardDistance == 1
            ? FloorItemDepth.OneAhead
            : FloorItemDepth.TwoAhead;
    return true;
  }

  private string GetFloorItemFeatureKey(FloorItemPlacement item)
  {
    return MakePreviewFeatureKey(
        "Item-" + item.type,
        item.x,
        item.y,
        item.cell);
  }

  private Texture2D GetFloorItemTexture(FloorItemPlacement item)
  {
    if (item == null)
      return null;

    if (string.Equals(item.type, "Apple", System.StringComparison.OrdinalIgnoreCase))
    {
      if (cachedAppleGroundTexture == null)
        cachedAppleGroundTexture = AssetDatabase.LoadAssetAtPath<Texture2D>(AppleGroundAssetPath);
      return cachedAppleGroundTexture;
    }

    if (string.Equals(item.type, "Bread", System.StringComparison.OrdinalIgnoreCase))
    {
      if (cachedBreadGroundTexture == null)
        cachedBreadGroundTexture = AssetDatabase.LoadAssetAtPath<Texture2D>(BreadGroundAssetPath);
      return cachedBreadGroundTexture;
    }

    return null;
  }

  private void BlitFloorItemsIntoPreview(Color32[] pixels)
  {
    if (pixels == null)
      return;

    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return;

    FloorItemPlacement[] items = GetCurrentFloorItems();
    for (int i = 0; i < items.Length; i++)
    {
      FloorItemPlacement item = items[i];
      if (!TryProjectFloorItem(item, out FloorItemDepth depth, out bool isRight))
        continue;
      if (!IsPreviewFeatureEnabled(GetFloorItemFeatureKey(item)))
        continue;

      Texture2D texture = GetFloorItemTexture(item);
      if (texture == null || !texture.isReadable || texture.width <= 0 || texture.height <= 0)
        continue;

      BlitProjectedFloorItem(pixels, item, texture, depth, isRight);
    }
  }

  private void BlitProjectedFloorItem(
      Color32[] pixels,
      FloorItemPlacement item,
      Texture2D texture,
      FloorItemDepth depth,
      bool isRight)
  {
    bool apple = string.Equals(item.type, "Apple", System.StringComparison.OrdinalIgnoreCase);
    bool bread = string.Equals(item.type, "Bread", System.StringComparison.OrdinalIgnoreCase);
    if (!apple && !bread)
      return;

    if (depth == FloorItemDepth.SameTile)
    {
      int x = apple
          ? (isRight ? appleF0RightPreviewX : appleF0FrontPreviewX)
          : (isRight ? breadF0RightPreviewX : breadF0LeftPreviewX);
      int top = apple
          ? (isRight ? appleF0RightPreviewScreenTop : appleF0FrontPreviewScreenTop)
          : (isRight ? breadF0RightPreviewScreenTop : breadF0LeftPreviewScreenTop);
      BlitPieceIntoPreview(pixels, texture, x, PreviewHeight - top - texture.height, false);
      return;
    }

    if (depth == FloorItemDepth.OneAhead)
    {
      int width = apple ? AppleF2Width : BreadF2Width;
      int height = apple ? AppleF2Height : BreadF2Height;
      int x = apple
          ? (isRight ? appleF2RightPreviewX : appleF2LeftPreviewX)
          : (isRight ? breadF2RightPreviewX : breadF2LeftPreviewX);
      int top = apple
          ? (isRight ? appleF2RightPreviewScreenTop : appleF2LeftPreviewScreenTop)
          : (isRight ? breadF2RightPreviewScreenTop : breadF2LeftPreviewScreenTop);
      BlitPieceScaledIntoPreview(
          pixels, texture, x, PreviewHeight - top - height, width, height, false,
          skipCyanTransparencyKey: apple,
          colorMap: WallOrnamentMediumColorMap);
      return;
    }

    // F3 is calibrated from the Apple source today. Keep the generic map
    // projection active, but do not invent an unverified Bread F3 pixel slot.
    if (!apple)
      return;

    int f3X = isRight ? appleF3RightPreviewX : appleF3LeftPreviewX;
    int f3Top = isRight ? appleF3RightPreviewScreenTop : appleF3LeftPreviewScreenTop;
    BlitPieceScaledIntoPreview(
        pixels, texture, f3X, PreviewHeight - f3Top - AppleF3Height,
        AppleF3Width, AppleF3Height, false,
        skipCyanTransparencyKey: true,
        colorMap: WallOrnamentFarColorMap);
  }

  private void DrawFloorItemRows()
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null)
      return;

    FloorItemPlacement[] items = GetCurrentFloorItems();
    for (int i = 0; i < items.Length; i++)
    {
      FloorItemPlacement item = items[i];
      if (!TryProjectFloorItem(item, out FloorItemDepth depth, out bool isRight))
        continue;

      // Bread F3 has no verified pixel calibration yet, so it is not drawn
      // and should not appear as an active ViewEdit feature row.
      if (depth == FloorItemDepth.TwoAhead
          && string.Equals(item.type, "Bread", System.StringComparison.OrdinalIgnoreCase))
        continue;

      string key = GetFloorItemFeatureKey(item);
      EditorGUILayout.BeginHorizontal();

      float savedLabelWidth = EditorGUIUtility.labelWidth;
      EditorGUIUtility.labelWidth = EditorStyles.label.CalcSize(new GUIContent("X")).x;
      using (new EditorGUI.DisabledScope(true))
      {
        EditorGUILayout.IntField("X", item.x, GUILayout.Width(FloorItemMapCoordFieldWidth));
        EditorGUIUtility.labelWidth = EditorStyles.label.CalcSize(new GUIContent("Y")).x;
        EditorGUILayout.IntField("Y", item.y, GUILayout.Width(FloorItemMapCoordFieldWidth));
      }
      EditorGUIUtility.labelWidth = savedLabelWidth;

      string depthLabel = depth == FloorItemDepth.SameTile
          ? "F1"
          : depth == FloorItemDepth.OneAhead ? "F2" : "F3";
      GUILayout.Label(
          item.type + " [" + item.cell + "] - " + depthLabel + " " + (isRight ? "Right" : "Left"),
          EditorStyles.boldLabel,
          GUILayout.Width(210f));

      bool enabledBefore = IsPreviewFeatureEnabled(key);
      bool enabledAfter = DrawCompactMouseOnlyToggle("Set", enabledBefore, false);
      EditorGUILayout.EndHorizontal();

      if (enabledAfter != enabledBefore)
      {
        SetPreviewFeatureEnabled(key, enabledAfter);
        previewEnabledChangedThisFrame = true;
        RefreshEditModePreview();
        RepaintGameViews();
        Repaint();
      }
    }
  }

  private bool IsFloorOrnamentProjectionVisibleInCurrentPose(
      HashSet<int> floorOrnamentTiles,
      int mapX,
      int mapY,
      int depth,
      int lane)
  {
    if (floorOrnamentTiles == null
        || previewMiniMap == null
        || !previewMiniMap.IsInside(mapX, mapY)
        || !floorOrnamentTiles.Contains(PackPreviewTile(mapX, mapY)))
      return false;

    // Center floor ornaments can be seen at F1/F2/F3 only while every nearer
    // center tile remains open.
    if (lane == 0)
    {
      if (depth < 1 || depth > 3)
        return false;

      DungeonMap.GetForwardOffset(
          previewFacing,
          out int centerForwardX,
          out int centerForwardY);

      for (int nearerDepth = 1; nearerDepth < depth; nearerDepth++)
      {
        int nearerX = previewX + centerForwardX * nearerDepth;
        int nearerY = previewY + centerForwardY * nearerDepth;
        if (!PreviewTileIsOpen(nearerX, nearerY))
          return false;
      }

      return true;
    }

    if (Mathf.Abs(lane) != 1 || depth < 1 || depth > 2)
      return false;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    int side = lane < 0 ? -1 : 1;
    int f0SideX = previewX + rightX * side;
    int f0SideY = previewY + rightY * side;
    bool f0SideOpen =
        previewMiniMap.IsInside(f0SideX, f0SideY)
        && previewMiniMap.GetTile(f0SideX, f0SideY).Type != DungeonTileType.Wall;
    if (!f0SideOpen)
      return false;

    if (depth == 1)
      return true;

    int f1SideX = previewX + forwardX + rightX * side;
    int f1SideY = previewY + forwardY + rightY * side;
    return previewMiniMap.IsInside(f1SideX, f1SideY)
        && previewMiniMap.GetTile(f1SideX, f1SideY).Type != DungeonTileType.Wall;
  }

  private bool IsPuddleProjectionVisibleInCurrentPose(
      int mapX,
      int mapY,
      int depth,
      int lane)
  {
    return IsFloorOrnamentProjectionVisibleInCurrentPose(
        previewPuddleFloors,
        mapX,
        mapY,
        depth,
        lane);
  }

  private bool IsMossProjectionVisibleInCurrentPose(
      int mapX,
      int mapY,
      int depth,
      int lane)
  {
    return IsFloorOrnamentProjectionVisibleInCurrentPose(
        previewMossFloors,
        mapX,
        mapY,
        depth,
        lane);
  }

  private Texture2D GetMossF1Texture()
  {
    if (cachedMossF1Texture != null)
      return cachedMossF1Texture;

    TextureImporter importer =
        AssetImporter.GetAtPath(MossF1AssetPath) as TextureImporter;
    if (importer != null)
    {
      bool changed = false;
      if (!importer.isReadable)
      {
        importer.isReadable = true;
        changed = true;
      }
      if (importer.filterMode != FilterMode.Point)
      {
        importer.filterMode = FilterMode.Point;
        changed = true;
      }
      if (importer.mipmapEnabled)
      {
        importer.mipmapEnabled = false;
        changed = true;
      }
      if (changed)
        importer.SaveAndReimport();
    }

    cachedMossF1Texture =
        AssetDatabase.LoadAssetAtPath<Texture2D>(MossF1AssetPath);
    return cachedMossF1Texture;
  }

  private Texture2D GetMossF2Texture()
  {
    if (cachedMossF2Texture != null)
      return cachedMossF2Texture;

    Texture2D source = GetMossF1Texture();
    if (source == null || !source.isReadable)
      return null;

    cachedMossF2Texture = GenerateDmScaledWallDecoration(
        source,
        MossF2Width,
        MossF2Height,
        WallOrnamentMediumColorMap,
        "Moss F2 Generated from F1");
    return cachedMossF2Texture;
  }

  private Texture2D GetMossF3Texture()
  {
    if (cachedMossF3Texture != null
        && cachedMossF3Texture.isReadable
        && cachedMossF3Texture.width == 8
        && cachedMossF3Texture.height == 2)
    {
      return cachedMossF3Texture;
    }

    // The imported sprite sheet does not expose these 8x2 pixels to
    // GetPixels32. Read the PNG into a temporary readable texture.
    string projectRoot = Path.GetDirectoryName(Application.dataPath);
    string absolutePath = string.IsNullOrEmpty(projectRoot)
        ? MossF3AssetPath
        : Path.Combine(projectRoot, MossF3AssetPath);
    if (!File.Exists(absolutePath))
      return null;

    byte[] pngBytes = File.ReadAllBytes(absolutePath);
    Texture2D readableCopy = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    readableCopy.name = "MossF3_ReadablePreview";
    readableCopy.filterMode = FilterMode.Point;
    readableCopy.wrapMode = TextureWrapMode.Clamp;
    readableCopy.hideFlags = HideFlags.HideAndDontSave;
    if (!readableCopy.LoadImage(pngBytes, false)
        || readableCopy.width != 8
        || readableCopy.height != 2)
    {
      DestroyImmediate(readableCopy);
      return null;
    }

    cachedMossF3Texture = readableCopy;
    return cachedMossF3Texture;
  }

  private void BlitMossIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (pixels == null
        || previewMiniMap == null
        || previewMossFloors.Count == 0)
    {
      return;
    }

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    // Far to near.
    for (int depth = 3; depth >= 1; depth--)
    {
      int mapX = previewX + forwardX * depth;
      int mapY = previewY + forwardY * depth;

      if (!previewMiniMap.IsInside(mapX, mapY)
          || !IsPreviewMossFloor(mapX, mapY)
          || !IsMossProjectionVisibleInCurrentPose(mapX, mapY, depth, 0))
      {
        continue;
      }

      Texture2D texture =
          depth == 1 ? GetMossF1Texture()
          : depth == 2 ? GetMossF2Texture()
          : GetMossF3Texture();
      if (texture == null || !texture.isReadable)
        continue;

      int screenTop =
          depth == 1 ? MossF1ScreenTop
          : depth == 2 ? MossF2ScreenTop
          : MossF3ScreenTop;

      int x = (DungeonViewportWidth - texture.width) / 2;
      int y = PreviewHeight - screenTop - texture.height;
      bool mirror = false;

      string key = "OrnamentProjection:Moss:F" + depth;
      ApplyAcceptedOrnamentReference(key, ref x, ref y, ref mirror);
      ApplyPreviewFeatureRenderOverrides(key, ref x, ref y, ref mirror);

      BlitPieceIntoPreview(pixels, texture, x, y, mirror);
    }
  }

  private void BlitPuddlesIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null || previewPuddleFloors.Count == 0)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    int f1X = previewX + forwardX;
    int f1Y = previewY + forwardY;
    int f2X = previewX + forwardX * 2;
    int f2Y = previewY + forwardY * 2;
    int f3X = previewX + forwardX * 3;
    int f3Y = previewY + forwardY * 3;

    if (IsPuddleProjectionVisibleInCurrentPose(f3X, f3Y, 3, 0))
    {
      BlitPuddleFloor(
          pixels, f3X, f3Y, PuddleF3AssetPath, ref cachedPuddleF3Texture,
          PuddleF3ScreenTop, true, 0, false);
    }

    // Side-floor puddles must have an unobstructed same-side sight line.
    // D1 side tiles need the adjacent F0 side open. D2 side tiles need both
    // the adjacent F0 side and the F1 side cell open; otherwise a nearer side
    // wall hides the floor ornament behind it.
    int f0LeftX = previewX - rightX;
    int f0LeftY = previewY - rightY;
    int f0RightX = previewX + rightX;
    int f0RightY = previewY + rightY;
    int f1LeftX = f1X - rightX;
    int f1LeftY = f1Y - rightY;
    int f1RightX = f1X + rightX;
    int f1RightY = f1Y + rightY;

    bool f0LeftOpen =
        previewMiniMap.IsInside(f0LeftX, f0LeftY)
        && previewMiniMap.GetTile(f0LeftX, f0LeftY).Type != DungeonTileType.Wall;
    bool f0RightOpen =
        previewMiniMap.IsInside(f0RightX, f0RightY)
        && previewMiniMap.GetTile(f0RightX, f0RightY).Type != DungeonTileType.Wall;
    bool f1LeftOpen =
        previewMiniMap.IsInside(f1LeftX, f1LeftY)
        && previewMiniMap.GetTile(f1LeftX, f1LeftY).Type != DungeonTileType.Wall;
    bool f1RightOpen =
        previewMiniMap.IsInside(f1RightX, f1RightY)
        && previewMiniMap.GetTile(f1RightX, f1RightY).Type != DungeonTileType.Wall;

    if (f0LeftOpen && f1LeftOpen)
    {
      BlitPuddleFloor(
          pixels, f2X - rightX, f2Y - rightY, PuddleS2AssetPath,
          ref cachedPuddleS2Texture, PuddleS2ScreenTop, false,
          PuddleS2LeftScreenX, false);
    }

    if (f0RightOpen && f1RightOpen)
    {
      BlitPuddleFloor(
          pixels, f2X + rightX, f2Y + rightY, PuddleS2AssetPath,
          ref cachedPuddleS2Texture, PuddleS2ScreenTop, false,
          PuddleS2LeftScreenX, true);
    }

    if (IsPuddleProjectionVisibleInCurrentPose(f2X, f2Y, 2, 0))
    {
      BlitPuddleFloor(
          pixels, f2X, f2Y, PuddleF2AssetPath, ref cachedPuddleF2Texture,
          PuddleF2ScreenTop, true, 0, false);
    }

    if (f0LeftOpen)
    {
      BlitPuddleF1Side(
          pixels, f1X - rightX, f1Y - rightY, false);
    }

    if (f0RightOpen)
    {
      BlitPuddleF1Side(
          pixels, f1X + rightX, f1Y + rightY, true);
    }
    if (IsPuddleProjectionVisibleInCurrentPose(f1X, f1Y, 1, 0))
    {
      BlitPuddleFloor(
          pixels, f1X, f1Y, PuddleF1AssetPath, ref cachedPuddleF1Texture,
          PuddleF1ScreenTop, true, 0, false);
    }
  }


  private void BlitPuddleF1Side(
      Color32[] pixels,
      int mapX,
      int mapY,
      bool rightSide)
  {
    if (!previewMiniMap.IsInside(mapX, mapY)
        || !IsPreviewPuddleFloor(mapX, mapY))
    {
      return;
    }

    Texture2D texture = GetPuddleTexture(
        PuddleF1SideAssetPath,
        ref cachedPuddleF1SideTexture);
    if (texture == null || !texture.isReadable || texture.width <= 0)
      return;

    int x = rightSide
        ? DungeonViewportWidth - texture.width
        : 0;
    int y = PreviewHeight - PuddleF1ScreenTop - texture.height + 1;

    BlitPieceIntoPreview(pixels, texture, x, y, rightSide);
  }

  private void BlitPuddleFloor(
      Color32[] pixels,
      int mapX,
      int mapY,
      string assetPath,
      ref Texture2D cache,
      int screenTop,
      bool centerInViewport,
      int leftScreenX,
      bool mirror)
  {
    if (!previewMiniMap.IsInside(mapX, mapY)
        || !IsPreviewPuddleFloor(mapX, mapY))
    {
      return;
    }

    Texture2D texture = GetPuddleTexture(assetPath, ref cache);
    if (texture == null || !texture.isReadable || texture.width <= 0)
      return;

    int x = centerInViewport
        ? (DungeonViewportWidth - texture.width) / 2
        : leftScreenX;
    if (mirror)
      x = DungeonViewportWidth - leftScreenX - texture.width;

    int y = PreviewHeight - screenTop - texture.height;
    BlitPieceIntoPreview(pixels, texture, x, y, mirror);
  }

  private Texture2D GetPuddleTexture(string assetPath, ref Texture2D cache)
  {
    if (cache != null)
      return cache;

    cache = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
    return cache;
  }


  private Texture2D GetViAltarS1Texture()
  {
    if (cachedViAltarS1Texture != null)
      return cachedViAltarS1Texture;

    const string exactPath =
        "Assets/Art/Ornaments/Altar_of_Vi_S1_20x48.png";

    TextureImporter importer =
        AssetImporter.GetAtPath(exactPath) as TextureImporter;
    if (importer != null && !importer.isReadable)
    {
      importer.isReadable = true;
      importer.SaveAndReimport();
    }

    cachedViAltarS1Texture =
        AssetDatabase.LoadAssetAtPath<Texture2D>(exactPath);
    return cachedViAltarS1Texture;
  }

  private Texture2D GetViAltarS3Texture()
  {
    if (cachedViAltarS3Texture != null)
      return cachedViAltarS3Texture;

    TextureImporter importer =
        AssetImporter.GetAtPath(ViAltarS3AssetPath) as TextureImporter;
    if (importer != null)
    {
      bool changed = false;
      if (!importer.isReadable)
      {
        importer.isReadable = true;
        changed = true;
      }
      if (importer.filterMode != FilterMode.Point)
      {
        importer.filterMode = FilterMode.Point;
        changed = true;
      }
      if (importer.mipmapEnabled)
      {
        importer.mipmapEnabled = false;
        changed = true;
      }
      if (changed)
        importer.SaveAndReimport();
    }

    cachedViAltarS3Texture =
        AssetDatabase.LoadAssetAtPath<Texture2D>(ViAltarS3AssetPath);
    if (cachedViAltarS3Texture != null)
    {
      cachedViAltarS3Texture.filterMode = FilterMode.Point;
      cachedViAltarS3Texture.wrapMode = TextureWrapMode.Clamp;
    }
    return cachedViAltarS3Texture;
  }

  private void BlitViAltarS3IntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D altar = GetViAltarS3Texture();
    if (altar == null || !altar.isReadable)
      return;

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (!TryGetViAltarS3Projection(
              ornament,
              out int anchorX,
              out int anchorY,
              out string viewFacing,
              out bool defaultMirror))
      {
        continue;
      }

      string key = "OrnamentProjection:ViAltar:S3";
      if (!IsPreviewFeatureEnabled(key))
        continue;

      int x = ViAltarS3RightX;
      int y = ViAltarS3Y;
      bool mirror = defaultMirror;
      ApplyAcceptedOrnamentReference(key, ref x, ref y, ref mirror);
      ApplyPreviewFeatureRenderOverrides(key, ref x, ref y, ref mirror);

      // Generic S3 render: every Vi Altar that resolves through the S3
      // projection uses this exact 6x19 crop at 1:1. The crop already contains
      // the original far-distance palette, so do not scale or palette-remap it.
      // defaultMirror comes from the projected wall side (right=ON, left=OFF).
      BlitPieceIntoPreview(pixels, altar, x, y, mirror);
    }
  }

