  private Texture2D GetViAltarFrontTexture()
  {
    if (cachedViAltarFrontTexture != null)
      return cachedViAltarFrontTexture;

    string[] guids = AssetDatabase.FindAssets(
        "t:Texture2D",
        new[] { "Assets" });

    Texture2D best = null;
    int bestScore = int.MinValue;
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      Texture2D candidate =
          AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null
          || candidate.width != 96
          || candidate.height != 56)
      {
        continue;
      }

      string lower = Path.GetFileNameWithoutExtension(path)
          .ToLowerInvariant();
      if (!lower.Contains("altar") || !lower.Contains("vi"))
        continue;

      int score = 100;
      if (lower.Contains("altar_of_vi")) score += 50;
      if (lower.Contains("96x56") || lower.Contains("96,56")) score += 25;
      if (score <= bestScore)
        continue;

      best = candidate;
      bestScore = score;
    }

    cachedViAltarFrontTexture = best;
    return cachedViAltarFrontTexture;
  }


  // Original Dungeon Master wall-ornament distance colour maps recovered
  // from the wall-decoration data. These maps are shared by the generic
  // wall-ornament renderer; the ornament's coordinate set supplies the target
  // rectangle, while the depth selects Medium (F2) or Far (F3).
  // Stored values 0,10,20,...150 become final 4-bit palette indices / 10.
  private static readonly byte[] WallOrnamentMediumColorMap =
  {
    0, 12, 1, 3,
    4, 3, 6, 7,
    5, 9, 10, 11,
    0, 2, 14, 13
  };

  private static readonly byte[] WallOrnamentFarColorMap =
  {
    0, 0, 12, 3,
    4, 3, 0, 6,
    3, 9, 10, 11,
    0, 1, 0, 2
  };

  private struct WallOrnamentDepthSlot
  {
    public int width;
    public int height;
    public int x;
    public int y;

    public WallOrnamentDepthSlot(int width, int height, int x, int y)
    {
      this.width = width;
      this.height = height;
      this.x = x;
      this.y = y;
    }
  }

  private struct WallOrnamentCoordinateSet
  {
    public WallOrnamentDepthSlot f1;
    public WallOrnamentDepthSlot f2;
    public WallOrnamentDepthSlot f3;

    public WallOrnamentCoordinateSet(
        WallOrnamentDepthSlot f1,
        WallOrnamentDepthSlot f2,
        WallOrnamentDepthSlot f3)
    {
      this.f1 = f1;
      this.f2 = f2;
      this.f3 = f3;
    }
  }




  // Generic wall-ornament coordinate profile: Champion Mirror front.
  // F2 is the first non-altar validation of the shared renderer.
  // F3 is recorded here for the next test, but its existing path is left
  // untouched in this change.
  private static readonly WallOrnamentCoordinateSet ChampionMirrorFrontWallOrnamentSet =
      new WallOrnamentCoordinateSet(
          new WallOrnamentDepthSlot(
              ChampionMirrorD1FrontWidth,
              ChampionMirrorD1FrontHeight,
              ChampionMirrorD1FrontX,
              ChampionMirrorD1FrontY),
          new WallOrnamentDepthSlot(
              ChampionMirrorD2FrontWidth,
              ChampionMirrorD2FrontHeight,
              ChampionMirrorD2FrontX,
              ChampionMirrorD2FrontY),
          new WallOrnamentDepthSlot(
              ChampionMirrorD3FrontWidth,
              ChampionMirrorD3FrontHeight,
              ChampionMirrorD3FrontX,
              ChampionMirrorD3FrontY));


  // Generic wall-ornament coordinate profile: Hook front.
  // F2 is generated from the single 28x28 F1 source.
  private static readonly WallOrnamentCoordinateSet HookFrontWallOrnamentSet =
      new WallOrnamentCoordinateSet(
          new WallOrnamentDepthSlot(
              28, 28, HookD1FrontX, HookD1FrontY),
          new WallOrnamentDepthSlot(
              HookD2FrontWidth,
              HookD2FrontHeight,
              HookD2FrontX,
              HookD2FrontY),
          new WallOrnamentDepthSlot(
              HookD3FrontWidth,
              HookD3FrontHeight,
              HookD3FrontX,
              HookD3FrontY));

  /// <summary>
  /// Shared generated wall-ornament path.
  /// The source art stays ornament-specific, but the scaling/palette algorithm
  /// is common. The coordinate set supplies the depth-specific destination size.
  /// </summary>
  private static Texture2D GenerateWallOrnamentForDepth(
      Texture2D source,
      WallOrnamentDepthSlot slot,
      byte[] colorMap,
      string textureName)
  {
    return GenerateDmScaledWallDecoration(
        source,
        slot.width,
        slot.height,
        colorMap,
        textureName);
  }

  private static void BlitWallOrnamentIntoPreview(
      Color32[] dest,
      Texture2D source,
      int destinationX,
      int destinationY,
      bool mirrorHorizontally = false)
  {
    if (source == null || !source.isReadable)
      return;

    Color32[] sourcePixels = source.GetPixels32();

    for (int sourceY = 0; sourceY < source.height; sourceY++)
    {
      int targetY = destinationY + sourceY;
      if (targetY < 0 || targetY >= PreviewHeight)
        continue;

      for (int column = 0; column < source.width; column++)
      {
        int sourceX = mirrorHorizontally
            ? source.width - 1 - column
            : column;
        int targetX = destinationX + column;

        // Generic dungeon-wall rule: never paint into the HUD/right UI area.
        if (targetX < 0 || targetX >= DungeonViewportWidth)
          continue;

        Color32 sourceColour =
            sourcePixels[sourceY * source.width + sourceX];
        if (sourceColour.a == 0)
          continue;

        dest[targetY * PreviewWidth + targetX] = sourceColour;
      }
    }
  }

