  /// <summary>
  /// Applies a Dungeon Master distance colour map to an already-sized wall
  /// decoration. Pixel positions are preserved 1:1; there is no scaling.
  /// </summary>
  private static Texture2D ApplyDmWallDecorationColorMap(
      Texture2D source,
      byte[] colorMap,
      string textureName)
  {
    if (source == null
        || !source.isReadable
        || colorMap == null
        || colorMap.Length < 16)
    {
      return null;
    }

    Color32[] sourcePixels = source.GetPixels32();
    Color32[] targetPixels = new Color32[sourcePixels.Length];
    Color32[] brightPalette = DungeonViewportLightPalettes[0];

    for (int i = 0; i < sourcePixels.Length; i++)
    {
      Color32 sourcePixel = sourcePixels[i];
      if (sourcePixel.a == 0)
      {
        targetPixels[i] = new Color32(0, 0, 0, 0);
        continue;
      }

      int sourcePaletteIndex = FindExactDmPaletteIndexOrNearest(
          sourcePixel,
          brightPalette);
      int mappedPaletteIndex = colorMap[sourcePaletteIndex];
      mappedPaletteIndex = Mathf.Clamp(mappedPaletteIndex, 0, 15);

      // Original wall-decoration blit uses palette index 10 as transparent.
      if (mappedPaletteIndex == 10)
      {
        targetPixels[i] = new Color32(0, 0, 0, 0);
        continue;
      }

      Color32 mapped = brightPalette[mappedPaletteIndex];
      mapped.a = sourcePixel.a;
      targetPixels[i] = mapped;
    }

    Texture2D generated = new Texture2D(
        source.width,
        source.height,
        TextureFormat.RGBA32,
        false);
    generated.name = textureName;
    generated.filterMode = FilterMode.Point;
    generated.wrapMode = TextureWrapMode.Clamp;
    generated.SetPixels32(targetPixels);
    generated.Apply(false, false);
    return generated;
  }


  /// <summary>
  /// Unity-friendly port of CSBwin Graphics.cpp ShrinkBLT for an already
  /// unpacked RGBA source texture. The original routine samples a 4-bit
  /// planar bitmap with 16.16 fixed-point stepping. We reproduce the exact
  /// source-coordinate sequence and colour-map lookup, then emulate the
  /// original wall-decoration blit transparency key (palette index 10).
  /// </summary>
  private static Texture2D CropWallDecorationToOpaqueBounds(Texture2D source)
  {
    if (source == null || !source.isReadable)
      return source;

    Color32[] pixels = source.GetPixels32();
    int width = source.width;
    int height = source.height;
    int minX = width;
    int minY = height;
    int maxX = -1;
    int maxY = -1;

    for (int y = 0; y < height; y++)
    {
      int row = y * width;
      for (int x = 0; x < width; x++)
      {
        if (pixels[row + x].a == 0)
          continue;

        if (x < minX)
          minX = x;
        if (x > maxX)
          maxX = x;
        if (y < minY)
          minY = y;
        if (y > maxY)
          maxY = y;
      }
    }

    if (maxX < minX || maxY < minY)
      return source;

    int cropWidth = maxX - minX + 1;
    int cropHeight = maxY - minY + 1;
    if (cropWidth == width && cropHeight == height)
      return source;

    Color32[] croppedPixels = new Color32[cropWidth * cropHeight];
    for (int y = 0; y < cropHeight; y++)
    {
      int sourceRow = (minY + y) * width + minX;
      int targetRow = y * cropWidth;
      for (int x = 0; x < cropWidth; x++)
        croppedPixels[targetRow + x] = pixels[sourceRow + x];
    }

    Texture2D cropped = new Texture2D(
        cropWidth,
        cropHeight,
        TextureFormat.RGBA32,
        false);
    cropped.name = source.name + " Opaque";
    cropped.filterMode = FilterMode.Point;
    cropped.wrapMode = TextureWrapMode.Clamp;
    cropped.SetPixels32(croppedPixels);
    cropped.Apply(false, false);
    return cropped;
  }

  private static Texture2D GenerateDmScaledWallDecoration(
      Texture2D source,
      int targetWidth,
      int targetHeight,
      byte[] colorMap,
      string textureName,
      int? roundBiasOverride = null)
  {
    if (source == null
        || !source.isReadable
        || targetWidth <= 0
        || targetHeight <= 0
        || colorMap == null
        || colorMap.Length < 16)
    {
      return null;
    }

    Color32[] sourcePixels = source.GetPixels32();
    Color32[] targetPixels = new Color32[targetWidth * targetHeight];

    // CSBwin ShrinkBLT:
    // step = (((sourceSize << 10) / destinationSize) << 6)
    //      = floor(sourceSize * 65536 / destinationSize)
    // The integer source coordinate is the upper 16 bits of the accumulator.
    // F2 keeps the rounded start (step/2 + 0x7fff). F3 uses step/2 alone:
    // the extra round pulls in the gray highlight row (which the far map
    // turns black) and the green pixels beside the yellow gems.
    int stepX = ((source.width << 10) / targetWidth) << 6;
    int stepY = ((source.height << 10) / targetHeight) << 6;
    bool farDistance = ReferenceEquals(colorMap, WallOrnamentFarColorMap);
    int roundBias = roundBiasOverride ?? (farDistance ? 0 : 0x7fff);
    int startX = (stepX >> 1) + roundBias;
    int startY = (stepY >> 1) + roundBias;

    Color32[] brightPalette = DungeonViewportLightPalettes[0];

    for (int y = 0; y < targetHeight; y++)
    {
      int sourceY = (startY + y * stepY) >> 16;
      sourceY = Mathf.Clamp(sourceY, 0, source.height - 1);
      int sourceRow = sourceY * source.width;
      int targetRow = y * targetWidth;

      for (int x = 0; x < targetWidth; x++)
      {
        int sourceX = (startX + x * stepX) >> 16;
        sourceX = Mathf.Clamp(sourceX, 0, source.width - 1);

        Color32 sourcePixel = sourcePixels[sourceRow + sourceX];
        if (sourcePixel.a == 0)
        {
          targetPixels[targetRow + x] = new Color32(0, 0, 0, 0);
          continue;
        }

        int sourcePaletteIndex = FindExactDmPaletteIndexOrNearest(
            sourcePixel,
            brightPalette);
        int mappedPaletteIndex = colorMap[sourcePaletteIndex];
        mappedPaletteIndex = Mathf.Clamp(mappedPaletteIndex, 0, 15);

        // CSBwin DrawWallDecoration() does not blit the ShrinkBLT result
        // opaquely. It calls TAG0088b2(..., transparentColor: 10).
        // Therefore palette index 10 in the distance-scaled bitmap is a
        // transparency key and must reveal the wall behind the ornament.
        if (mappedPaletteIndex == 10)
        {
          targetPixels[targetRow + x] = new Color32(0, 0, 0, 0);
          continue;
        }

        Color32 mapped = brightPalette[mappedPaletteIndex];
        mapped.a = sourcePixel.a;
        targetPixels[targetRow + x] = mapped;
      }
    }

    if (farDistance)
      MatchFarTopRowBlackToNeighbors(targetPixels, targetWidth, targetHeight);

    Texture2D generated = new Texture2D(
        targetWidth,
        targetHeight,
        TextureFormat.RGBA32,
        false);
    generated.name = textureName;
    generated.filterMode = FilterMode.Point;
    generated.wrapMode = TextureWrapMode.Clamp;
    generated.SetPixels32(targetPixels);
    generated.Apply(false, false);
    return generated;
  }

  /// <summary>
  /// The far-distance map turns a few gray samples on the top edge black.
  /// Those pixels should keep the colour of the other pixels on that row.
  /// A fully black top row is cleared so the wall colour shows through.
  /// </summary>
  private static void MatchFarTopRowBlackToNeighbors(
      Color32[] pixels,
      int width,
      int height)
  {
    int row = (height - 1) * width;
    for (int x = 0; x < width; x++)
    {
      Color32 pixel = pixels[row + x];
      if (pixel.a == 0 || pixel.r != 0 || pixel.g != 0 || pixel.b != 0)
        continue;

      bool found = false;
      Color32 replacement = pixel;
      for (int distance = 1; distance < width; distance++)
      {
        int left = x - distance;
        if (left >= 0 && IsOpaqueNonBlack(pixels[row + left]))
        {
          replacement = pixels[row + left];
          found = true;
          break;
        }

        int right = x + distance;
        if (right < width && IsOpaqueNonBlack(pixels[row + right]))
        {
          replacement = pixels[row + right];
          found = true;
          break;
        }
      }

      pixels[row + x] = found
          ? replacement
          : new Color32(0, 0, 0, 0);
    }
  }

  private static bool IsOpaqueNonBlack(Color32 pixel)
  {
    return pixel.a != 0
        && (pixel.r != 0 || pixel.g != 0 || pixel.b != 0);
  }

  /// <summary>
  /// Recover exact original DM palette indices whenever the RGBA source pixel
  /// matches a known stage-1 palette colour. This is shared by generated wall
  /// ornaments; nearest-colour matching is only a fallback for unexpected RGBs.
  /// </summary>
  private static int FindExactDmPaletteIndexOrNearest(
      Color32 source,
      Color32[] palette)
  {
    if (TryGetExactDmPaletteIndex(source, out int exactPaletteIndex))
      return exactPaletteIndex;

    return FindNearestDmPaletteIndexFallback(source, palette);
  }

  private static bool TryGetExactDmPaletteIndex(
      Color32 source,
      out int paletteIndex)
  {
    // Ignore alpha for the source-palette lookup. Imported textures may carry
    // alpha 254 on some opaque pixels, but their RGB still identifies the
    // exact original DM palette colour.
    int rgb = (source.r << 16) | (source.g << 8) | source.b;
    switch (rgb)
    {
      case (0 << 16) | (0 << 8) | 0:
        paletteIndex = 0;
        return true;
      case (109 << 16) | (109 << 8) | 109:
        paletteIndex = 1;
        return true;
      case (146 << 16) | (146 << 8) | 146:
        paletteIndex = 2;
        return true;
      case (0 << 16) | (146 << 8) | 0:
        paletteIndex = 6;
        return true;
      case (0 << 16) | (219 << 8) | 0:
        paletteIndex = 7;
        return true;
      case (255 << 16) | (0 << 8) | 0:
        paletteIndex = 8;
        return true;
      case (219 << 16) | (146 << 8) | 109:
        paletteIndex = 10;
        return true;
      case (255 << 16) | (255 << 8) | 0:
        paletteIndex = 11;
        return true;
      case (73 << 16) | (73 << 8) | 73:
        paletteIndex = 12;
        return true;
      case (182 << 16) | (182 << 8) | 182:
        paletteIndex = 13;
        return true;
      case (255 << 16) | (255 << 8) | 255:
        paletteIndex = 15;
        return true;
      default:
        paletteIndex = 0;
        return false;
    }
  }

  private static int FindNearestDmPaletteIndexFallback(
      Color32 source,
      Color32[] palette)
  {
    int bestPaletteIndex = 0;
    int bestDistance = int.MaxValue;

    for (int paletteIndex = 0; paletteIndex < 16; paletteIndex++)
    {
      Color32 candidate = palette[paletteIndex];
      int dr = source.r - candidate.r;
      int dg = source.g - candidate.g;
      int db = source.b - candidate.b;
      int distance = dr * dr + dg * dg + db * db;
      if (distance >= bestDistance)
        continue;

      bestDistance = distance;
      bestPaletteIndex = paletteIndex;
      if (distance == 0)
        break;
    }

    return bestPaletteIndex;
  }

  private Texture2D GetSlimeGeneratedF2FrontTexture()
  {
    if (cachedSlimeGeneratedF2FrontTexture != null)
      return cachedSlimeGeneratedF2FrontTexture;

    Texture2D source = GetSlimeFrontTexture();
    if (source == null || !source.isReadable)
      return null;

    // Generic Dungeon Master F2 ornament scale: derive the medium-distance
    // front image from the native F1 source. Position is calibrated separately
    // in ViewEdit; the source artwork itself is never resized on disk.
    int width = Mathf.Max(1, Mathf.RoundToInt(source.width * (2f / 3f)));
    int height = Mathf.Max(1, Mathf.RoundToInt(source.height * (2f / 3f)));

    cachedSlimeGeneratedF2FrontTexture = GenerateDmScaledWallDecoration(
        source,
        width,
        height,
        WallOrnamentMediumColorMap,
        "Slime F2 Generated from F1");
    return cachedSlimeGeneratedF2FrontTexture;
  }

  private Texture2D GetSlimeGeneratedF3FrontTexture()
  {
    if (cachedSlimeGeneratedF3FrontTexture != null)
      return cachedSlimeGeneratedF3FrontTexture;

    Texture2D source = GetSlimeFrontTexture();
    if (source == null || !source.isReadable)
      return null;

    cachedSlimeGeneratedF3FrontTexture = GenerateDmScaledWallDecoration(
        source,
        SlimeD3FrontWidth,
        SlimeD3FrontHeight,
        WallOrnamentFarColorMap,
        "Slime F3 Generated from F1");
    return cachedSlimeGeneratedF3FrontTexture;
  }

  private void BlitSlimeD3FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D slimeFront = GetSlimeGeneratedF3FrontTexture();
    if (slimeFront == null || !slimeFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int d2X = previewX + forwardX * 2;
    int d2Y = previewY + forwardY * 2;
    int wallTileX = previewX + forwardX * 3;
    int wallTileY = previewY + forwardY * 3;

    // F3 front is visible only through open D1 and D2 cells.
    if (!previewMiniMap.IsInside(d1X, d1Y)
        || previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(d2X, d2Y)
        || previewMiniMap.GetTile(d2X, d2Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY))
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsSlimeOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == d2X
            && ornament.y == d2Y
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
          pixels, slimeFront, ornament, SlimeD3FrontX, SlimeD3FrontY, false);
      return;
    }
  }

  private void BlitSlimeD2FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D slimeFront = GetSlimeGeneratedF2FrontTexture();
    if (slimeFront == null || !slimeFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int wallTileX = previewX + forwardX * 2;
    int wallTileY = previewY + forwardY * 2;

    // F2 front is visible only through an open D1 cell.
    if (!previewMiniMap.IsInside(d1X, d1Y)
        || previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY))
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsSlimeOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == d1X
            && ornament.y == d1Y
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      // Initial generic F2 slot. X/Y are intentionally exposed in ViewEdit
      // so the original screenshot can be used for exact pixel calibration.
      int x = (DungeonViewportWidth - slimeFront.width) / 2;
      int y = SlimeD2SideY;

      BlitOrnamentPieceIntoPreview(
          pixels, slimeFront, ornament, x, y, false);
      return;
    }
  }

  private void BlitSlimeD1FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D slimeFront = GetSlimeFrontTexture();
    if (slimeFront == null || !slimeFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int wallTileX = previewX + forwardX;
    int wallTileY = previewY + forwardY;
    if (!previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsSlimeOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        string visiblePhysicalWallFace = OppositeFacingName(previewFacing);
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == previewX
            && ornament.y == previewY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      // Same D1 front wall-center anchor used by the verified Hook/Wood Ring.
      // Native Slime front PNG is drawn 1:1.
      // Original-vs-Unity comparison at (4,5) East showed the sprite shape
      // and X position were already exact, but Unity was 59 screen pixels too
      // high. Preview framebuffer Y runs opposite the screen direction here,
      // so move the ornament anchor from Y=114 down to framebuffer Y=55.
      int x = 112 - (slimeFront.width / 2);
      int y = 55 - (slimeFront.height / 2);

      BlitOrnamentPieceIntoPreview(
          pixels, slimeFront, ornament, x, y, false);
      return;
    }
  }

  private static bool IsSlimeOrnament(WallOrnamentPlacement ornament)
  {
    if (ornament == null)
      return false;

    if (string.Equals(
            ornament.type,
            "Slime",
            System.StringComparison.OrdinalIgnoreCase))
    {
      return true;
    }

    return ResolveHallOfChampionsWallOrnamentSourceId(ornament) == 33;
  }

  private Texture2D GetSlimeFrontTexture()
  {
    if (cachedSlimeFrontTexture != null)
      return cachedSlimeFrontTexture;

    string[] guids = AssetDatabase.FindAssets(
        "Slime t:Texture2D",
        new[] { OrnamentArtFolder });

    Texture2D fallback = null;
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      string lower = path.ToLowerInvariant();
      if (!lower.Contains("slime"))
        continue;

      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null)
        continue;

      if (lower.Contains("front"))
      {
        cachedSlimeFrontTexture = candidate;
        return candidate;
      }

      if (fallback == null && !lower.Contains("side"))
        fallback = candidate;
    }

    cachedSlimeFrontTexture = fallback;
    return fallback;
  }

  private Texture2D GetSlimeSide1Texture()
  {
    if (cachedSlimeSide1Texture != null)
      return cachedSlimeSide1Texture;

    Texture2D exact = AssetDatabase.LoadAssetAtPath<Texture2D>(
        SlimeSide1AssetPath);
    if (exact != null && exact.width == 16 && exact.height == 10)
    {
      cachedSlimeSide1Texture = exact;
      return exact;
    }

    string[] guids = AssetDatabase.FindAssets(
        "Slime t:Texture2D",
        new[] { OrnamentArtFolder });
    for (int i = 0; i < guids.Length; i++)
    {
      string assetPath = AssetDatabase.GUIDToAssetPath(guids[i]);
      string lower = assetPath.ToLowerInvariant();
      if (!lower.Contains("slime") || !lower.Contains("side"))
        continue;

      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
      if (candidate != null
          && candidate.width == 16
          && candidate.height == 10)
      {
        cachedSlimeSide1Texture = candidate;
        return candidate;
      }
    }

    return null;
  }

  private Texture2D GetSlimeSide2Texture()
  {
    if (cachedSlimeSide2Texture != null)
      return cachedSlimeSide2Texture;

    Texture2D source = GetSlimeSide1Texture();
    if (source == null || !source.isReadable)
      return null;

    cachedSlimeSide2Texture = GenerateDmScaledWallDecoration(
        source,
        4,
        3,
        WallOrnamentMediumColorMap,
        "Slime Side F2 Generated from F1");
    return cachedSlimeSide2Texture;
  }

  private void BlitSlimeD1SidesIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D side1 = GetSlimeSide1Texture();
    if (side1 == null
        || !side1.isReadable
        || side1.width != 16
        || side1.height != 10)
    {
      return;
    }

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    int frontX = previewX + forwardX;
    int frontY = previewY + forwardY;
    if (!previewMiniMap.IsInside(frontX, frontY)
        || previewMiniMap.GetTile(frontX, frontY).Type == DungeonTileType.Wall)
    {
      return;
    }

    int leftWallTileX = frontX - rightX;
    int leftWallTileY = frontY - rightY;
    int rightWallTileX = frontX + rightX;
    int rightWallTileY = frontY + rightY;

    bool leftWallExists =
        previewMiniMap.IsInside(leftWallTileX, leftWallTileY)
        && previewMiniMap.GetTile(leftWallTileX, leftWallTileY).Type
            == DungeonTileType.Wall;
    bool rightWallExists =
        previewMiniMap.IsInside(rightWallTileX, rightWallTileY)
        && previewMiniMap.GetTile(rightWallTileX, rightWallTileY).Type
            == DungeonTileType.Wall;

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));

    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    bool leftDrawn = false;
    bool rightDrawn = false;

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsSlimeOrnament(ornament) || IsSlimeHiddenInCurrentPose(ornament))
        continue;

      bool matchesLeft;
      bool matchesRight;
      if (ornament.wallTilePlacement)
      {
        matchesLeft =
            leftWallExists
            && ornament.x == leftWallTileX
            && ornament.y == leftWallTileY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == rightWallTileX
            && ornament.y == rightWallTileY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        matchesLeft =
            leftWallExists
            && ornament.x == frontX
            && ornament.y == frontY
            && string.Equals(
                ornament.wall,
                leftBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == frontX
            && ornament.y == frontY
            && string.Equals(
                ornament.wall,
                rightBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (matchesLeft && !leftDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side1, ornament, SlimeD1SideLeftX, SlimeD1SideY, false);
        leftDrawn = true;
      }

      if (matchesRight && !rightDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side1, ornament, SlimeD1SideRightX, SlimeD1SideY, true);
        rightDrawn = true;
      }

      if (leftDrawn && rightDrawn)
        return;
    }
  }

