      if (matchesRight && !rightDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side3, ornament, WoodRingD3SideRightX, WoodRingD3SideY, true);
        rightDrawn = true;
      }

      if (leftDrawn && rightDrawn)
        return;
