  private void BlitHookSidesAtDistance(
      Color32[] pixels,
      int distance,
      int destWidth,
      int destHeight,
      int leftX,
      int rightX,
      int y)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0
        || distance < 2
        || distance > 3)
    {
      return;
    }

    Texture2D side = distance == 3
        ? GetHookSide3Texture()
        : GetHookSide2Texture();
    if (side == null
        || !side.isReadable
        || side.width != destWidth
        || side.height != destHeight)
    {
      return;
    }

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightOffsetX,
        out int rightOffsetY);

    int d1CenterX = previewX + forwardX;
    int d1CenterY = previewY + forwardY;
    int d2CenterX = previewX + forwardX * 2;
    int d2CenterY = previewY + forwardY * 2;
    int d3CenterX = previewX + forwardX * 3;
    int d3CenterY = previewY + forwardY * 3;

    if (!PreviewTileIsOpen(d1CenterX, d1CenterY)
        || !PreviewTileIsOpen(d2CenterX, d2CenterY)
        || (distance >= 3 && !PreviewTileIsOpen(d3CenterX, d3CenterY)))
    {
      return;
    }

    int laneCenterX = distance == 3 ? d3CenterX : d2CenterX;
    int laneCenterY = distance == 3 ? d3CenterY : d2CenterY;
    int leftWallTileX = laneCenterX - rightOffsetX;
    int leftWallTileY = laneCenterY - rightOffsetY;
    int rightWallTileX = laneCenterX + rightOffsetX;
    int rightWallTileY = laneCenterY + rightOffsetY;

    bool leftWallExists = PreviewTileIsWall(leftWallTileX, leftWallTileY);
    bool rightWallExists = PreviewTileIsWall(rightWallTileX, rightWallTileY);

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    bool leftDrawn = false;
    bool rightDrawn = false;

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsHookOrnament(ornament))
        continue;

      bool matchesLeft;
      bool matchesRight;
      if (ornament.wallTilePlacement)
      {
        matchesLeft =
            leftWallExists
            && ornament.x == leftWallTileX
            && ornament.y == leftWallTileY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == rightWallTileX
            && ornament.y == rightWallTileY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        matchesLeft =
            leftWallExists
            && ornament.x == laneCenterX
            && ornament.y == laneCenterY
            && string.Equals(
                ornament.wall,
                leftBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == laneCenterX
            && ornament.y == laneCenterY
            && string.Equals(
                ornament.wall,
                rightBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (matchesLeft && !leftDrawn)
      {
        // Supplied D2/D3 art is the right-wall crop, so the left slot is mirrored.
        BlitOrnamentPieceIntoPreview(
            pixels, side, ornament, leftX, y, true);
        leftDrawn = true;
      }

      if (matchesRight && !rightDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side, ornament, rightX, y, false);
        rightDrawn = true;
      }

      if (leftDrawn && rightDrawn)
        return;
    }
  }

