            == DungeonTileType.Wall;
    bool rightWallExists =
        previewMiniMap.IsInside(rightWallTileX, rightWallTileY)
        && previewMiniMap.GetTile(rightWallTileX, rightWallTileY).Type
            == DungeonTileType.Wall;

    // Physical faces on the solid wall tiles.
    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));

    // Equivalent directions when an explicit Sensor is stored on the
    // passable D1 center tile instead of on the wall tile itself.
    string leftBoundaryDirection =
        FacingName(TurnPreviewFacingLeft(previewFacing));
    string rightBoundaryDirection =
        FacingName(TurnPreviewFacingRight(previewFacing));

    bool leftDrawn = false;
    bool rightDrawn = false;

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (ornament == null)
        continue;
      if (IsWoodRingOrnament(ornament)
          && TryGetOriginalSouthWoodRingLeftDepth(ornament, out int southDepth))
      {
        if (southDepth == 1 && !leftDrawn)
        {
          Texture2D ring = GetWoodRingSideTexture();
          if (ring != null
              && ring.isReadable
              && ring.width == 14
              && ring.height == 19)
          {
            BlitOrnamentPieceIntoPreview(
                pixels,
                ring,
                ornament,
                WoodRingD1SideLeftX,
                WoodRingD1SideY,
                false);
            leftDrawn = true;
          }
        }
        continue;
      }

      // Hook uses native 16x19 1:1; Wood Ring keeps its 14x19 cutout.
      Texture2D sideTexture = null;
      int sideY = HookD1SideY;
      int sideLeftX = HookD1SideLeftX;
      int sideRightX = HookD1SideRightX;
      int expectedWidth = 16;
      int expectedHeight = 19;
      if (IsHookOrnament(ornament))
      {
        sideTexture = GetHookSideTexture();
      }
      else if (IsWoodRingOrnament(ornament))
      {
        sideTexture = GetWoodRingSideTexture();
        sideY = WoodRingD1SideY;
        sideLeftX = WoodRingD1SideLeftX;
        sideRightX = WoodRingD1SideRightX;
        expectedWidth = 14;
      }
      else
      {
        continue;
      }

      if (sideTexture == null
          || !sideTexture.isReadable
          || sideTexture.width != expectedWidth
          || sideTexture.height != expectedHeight)
      {
        continue;
      }

      bool matchesLeft;
      bool matchesRight;
      if (ornament.wallTilePlacement)
      {
        matchesLeft =
            leftWallExists
            && ornament.x == leftWallTileX
            && ornament.y == leftWallTileY
            && string.Equals(
                ornament.wall,
                leftPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == rightWallTileX
            && ornament.y == rightWallTileY
            && string.Equals(
                ornament.wall,
                rightPhysicalFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        matchesLeft =
            leftWallExists
            && ornament.x == frontX
            && ornament.y == frontY
            && string.Equals(
                ornament.wall,
                leftBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
        matchesRight =
            rightWallExists
            && ornament.x == frontX
            && ornament.y == frontY
            && string.Equals(
                ornament.wall,
                rightBoundaryDirection,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (matchesLeft && !leftDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, sideTexture, ornament, sideLeftX, sideY, false);
        leftDrawn = true;
      }

      if (matchesRight && !rightDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, sideTexture, ornament, sideRightX, sideY, true);
        rightDrawn = true;
      }

      if (leftDrawn && rightDrawn)
        return;
    }
  }

  private void BlitHookD2FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D hookFront = GetHookGeneratedF2FrontTexture();
    if (hookFront == null || !hookFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int wallTileX = previewX + forwardX * 2;
    int wallTileY = previewY + forwardY * 2;

    // The authoritative ornament database already tells us that the feature
    // belongs to a wall face. For F2 projection we only need an open D1 view
    // corridor and the ornament's normalized D2 position. Do not require the
    // minimap tile classifier to also call the D2 coordinate a Wall; that extra
    // gate can incorrectly hide valid wall ornaments.
    if (!previewMiniMap.IsInside(d1X, d1Y)
        || previewMiniMap.GetTile(d1X, d1Y).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY))
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsHookOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        // Explicit mechanisms at F2 are stored on the open cell one step
        // before the decorated wall boundary.
        placementMatches =
            ornament.x == d1X
            && ornament.y == d1Y
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
          pixels, hookFront, ornament,
          HookFrontWallOrnamentSet.f2.x, HookFrontWallOrnamentSet.f2.y, false);
      return;
    }
  }

  private void BlitManaclesD2SidesIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D side = GetManaclesGeneratedD2SideTexture();
    if (side == null || !side.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);
    DungeonMap.GetRightOffset(
        previewFacing,
        out int rightX,
        out int rightY);

    int d1X = previewX + forwardX;
    int d1Y = previewY + forwardY;
    int d2X = previewX + forwardX * 2;
    int d2Y = previewY + forwardY * 2;
    if (!PreviewTileIsOpen(d1X, d1Y) || !PreviewTileIsOpen(d2X, d2Y))
      return;

    int leftWallTileX = d2X - rightX;
    int leftWallTileY = d2Y - rightY;
    int rightWallTileX = d2X + rightX;
    int rightWallTileY = d2Y + rightY;
    bool leftWallExists = PreviewTileIsWall(leftWallTileX, leftWallTileY);
    bool rightWallExists = PreviewTileIsWall(rightWallTileX, rightWallTileY);

    string leftPhysicalFace =
        FacingName(TurnPreviewFacingRight(previewFacing));
    string rightPhysicalFace =
        FacingName(TurnPreviewFacingLeft(previewFacing));

    bool leftDrawn = false;
    bool rightDrawn = false;

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsManaclesOrnament(ornament) || !ornament.wallTilePlacement)
        continue;

      bool matchesLeft =
          leftWallExists
          && ornament.x == leftWallTileX
          && ornament.y == leftWallTileY
          && string.Equals(
              ornament.wall,
              leftPhysicalFace,
              System.StringComparison.OrdinalIgnoreCase);
      bool matchesRight =
          rightWallExists
          && ornament.x == rightWallTileX
          && ornament.y == rightWallTileY
          && string.Equals(
              ornament.wall,
              rightPhysicalFace,
              System.StringComparison.OrdinalIgnoreCase);

      if (matchesLeft && !leftDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side, ornament, ManaclesD2SideLeftX, ManaclesD2SideY, false);
        leftDrawn = true;
      }

      if (matchesRight && !rightDrawn)
      {
        BlitOrnamentPieceIntoPreview(
            pixels, side, ornament, ManaclesD2SideRightX, ManaclesD2SideY, true);
        rightDrawn = true;
      }

      if (leftDrawn && rightDrawn)
        return;
    }
  }

  private Texture2D GetManaclesGeneratedD2SideTexture()
  {
    if (cachedManaclesGeneratedD2SideTexture != null)
      return cachedManaclesGeneratedD2SideTexture;

    Texture2D source = GetManaclesS1Texture();
    if (source == null || !source.isReadable)
      return null;

    cachedManaclesGeneratedD2SideTexture = GenerateManaclesSideScaled(
        source,
        ManaclesD2SideWidth,
        ManaclesD2SideHeight,
        "Manacles S2 Generated from S1");
    return cachedManaclesGeneratedD2SideTexture;
  }

  // The shared wall-ornament shrink remaps this side graphic's metal greys
  // onto wall greys and samples through the chains, so the D2 shackles
  // draw as separate specks. Cover each destination pixel with the opaque
  // source colour that actually occupies that cell and keep the S1 palette.
  private static Texture2D GenerateManaclesSideScaled(
      Texture2D source,
      int targetWidth,
      int targetHeight,
      string textureName)
  {
    if (source == null
        || !source.isReadable
        || targetWidth <= 0
        || targetHeight <= 0)
    {
      return null;
    }

    Color32[] sourcePixels = source.GetPixels32();
    Color32[] targetPixels = new Color32[targetWidth * targetHeight];
    Color32[] palette = DungeonViewportLightPalettes[0];
    int sourceWidth = source.width;
    int sourceHeight = source.height;

    for (int y = 0; y < targetHeight; y++)
    {
      int sourceY0 = y * sourceHeight / targetHeight;
      int sourceY1 = (y + 1) * sourceHeight / targetHeight;
      if (sourceY1 <= sourceY0)
        sourceY1 = sourceY0 + 1;

      for (int x = 0; x < targetWidth; x++)
      {
        int sourceX0 = x * sourceWidth / targetWidth;
        int sourceX1 = (x + 1) * sourceWidth / targetWidth;
        if (sourceX1 <= sourceX0)
          sourceX1 = sourceX0 + 1;

        int[] counts = new int[16];
        int bestIndex = -1;
        int bestCount = 0;
        for (int sourceY = sourceY0; sourceY < sourceY1; sourceY++)
        {
          int sourceRow = sourceY * sourceWidth;
          for (int sourceX = sourceX0; sourceX < sourceX1; sourceX++)
          {
            Color32 sourcePixel = sourcePixels[sourceRow + sourceX];
            if (sourcePixel.a == 0)
              continue;

            int paletteIndex = FindExactDmPaletteIndexOrNearest(
                sourcePixel,
                palette);
            counts[paletteIndex]++;
            if (counts[paletteIndex] <= bestCount)
              continue;

            bestCount = counts[paletteIndex];
            bestIndex = paletteIndex;
          }
        }

        int destination = y * targetWidth + x;
        if (bestIndex < 0)
        {
          targetPixels[destination] = new Color32(0, 0, 0, 0);
          continue;
        }

        Color32 mapped = palette[bestIndex];
        mapped.a = 255;
        targetPixels[destination] = mapped;
      }
    }

    Texture2D generated = new Texture2D(
        targetWidth,
        targetHeight,
        TextureFormat.RGBA32,
        false);
    generated.name = textureName;
    generated.filterMode = FilterMode.Point;
    generated.wrapMode = TextureWrapMode.Clamp;
    generated.SetPixels32(targetPixels);
    generated.Apply(false, false);
    return generated;
  }

