  private void BlitManaclesD1FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D manacles = GetManaclesF1Texture();
    if (manacles == null || !manacles.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int wallTileX = previewX + forwardX;
    int wallTileY = previewY + forwardY;
    if (!previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);
    string visiblePhysicalWallFace = OppositeFacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsManaclesOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == previewX
            && ornament.y == previewY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      // D1/front wall ornaments are centered on the 224px dungeon viewport.
      // Keep the native F1 artwork 1:1. The vertical anchor is shared by all
      // Manacles F1 placements and can be pixel-calibrated from the original.
      int destinationX = (DungeonViewportWidth - manacles.width) / 2;
      const int destinationY = 77;
      BlitOrnamentPieceIntoPreview(
          pixels, manacles, ornament, destinationX, destinationY, false);
      return;
    }
  }

  private static bool IsManaclesOrnament(WallOrnamentPlacement ornament)
  {
    return ornament != null
        && !string.IsNullOrEmpty(ornament.type)
        && ornament.type.IndexOf(
            "Manacles",
            System.StringComparison.OrdinalIgnoreCase) >= 0;
  }

  private Texture2D GetManaclesF1Texture()
  {
    if (cachedManaclesF1Texture != null)
      return cachedManaclesF1Texture;

    Texture2D exact =
        AssetDatabase.LoadAssetAtPath<Texture2D>(ManaclesF1AssetPath);
    if (exact != null)
    {
      cachedManaclesF1Texture = exact;
      return exact;
    }

    // Filename-independent fallback in the ornament folder.
    string[] guids = AssetDatabase.FindAssets(
        "Manacles t:Texture2D",
        new[] { OrnamentArtFolder });
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null)
        continue;

      if (path.IndexOf(
              "manacles",
              System.StringComparison.OrdinalIgnoreCase) < 0
          || path.IndexOf(
              "f1",
              System.StringComparison.OrdinalIgnoreCase) < 0)
      {
        continue;
      }

      cachedManaclesF1Texture = candidate;
      return candidate;
    }

    return null;
  }

  private void BlitHookD1FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D hookFront = GetHookFrontTexture();
    if (hookFront == null || !hookFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    // A D1 front ornament can come from either an explicit mechanism on the
    // party's current passable cell or a decoration encoded on the solid wall
    // tile itself. In both cases the tile immediately ahead must be wall.
    int wallTileX = previewX + forwardX;
    int wallTileY = previewY + forwardY;
    if (!previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsHookOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        // Random wall-decoration bits belong to the solid wall tile. When the
        // party looks North, for example, it sees that wall tile's South face.
        string visiblePhysicalWallFace = OppositeFacingName(previewFacing);
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        // Explicit mechanisms are stored on the passable cell and use the
        // direction from that cell toward the wall boundary.
        placementMatches =
            ornament.x == previewX
            && ornament.y == previewY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
          pixels, hookFront, ornament, HookD1FrontX, HookD1FrontY, false);
      return;
    }
  }

  private static bool IsHookOrnament(WallOrnamentPlacement ornament)
  {
    if (ornament == null)
      return false;

    if (string.Equals(
            ornament.type,
            "Hook",
            System.StringComparison.OrdinalIgnoreCase))
    {
      return true;
    }

    // Explicit Sensor ordinals are level-local. On Hall of Champions local
    // ordinal 1 resolves to global wall ornament source ID 4 = Hook.
    return ResolveHallOfChampionsWallOrnamentSourceId(ornament) == 4;
  }

