    Texture2D grateFront = GetGrateFront2Texture();
    if (grateFront == null
        || !grateFront.isReadable
        || grateFront.width != 21
        || grateFront.height != 13)
    {
      return;
    }

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    // F2 front is the wall two steps ahead, seen through an open D1 cell.
    int openX = previewX + forwardX;
    int openY = previewY + forwardY;
    int wallTileX = previewX + forwardX * 2;
    int wallTileY = previewY + forwardY * 2;
    if (!previewMiniMap.IsInside(openX, openY)
        || previewMiniMap.GetTile(openX, openY).Type == DungeonTileType.Wall
        || !previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsGrateOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        string visiblePhysicalWallFace = OppositeFacingName(previewFacing);
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == openX
            && ornament.y == openY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
            pixels, grateFront, ornament,
            GrateD2FrontX, GrateD2FrontY, false);
      return;
    }
  }

  private Texture2D GetGrateFront2Texture()
  {
    if (cachedGrateFront2Texture != null)
      return cachedGrateFront2Texture;

    Texture2D source = GetGrateFrontTexture();
    if (source == null || !source.isReadable)
      return null;

    cachedGrateFront2Texture = GenerateDmScaledWallDecoration(
        source,
        21,
        13,
        WallOrnamentMediumColorMap,
        "Grate F2 Generated from F1");
    return cachedGrateFront2Texture;
  }

  private void BlitGrateD1FrontIntoPreview(Color32[] pixels)
  {
    EnsurePreviewMiniMapLoaded();
    if (previewMiniMap == null
        || previewWallOrnaments == null
        || previewWallOrnaments.Length == 0)
    {
      return;
    }

    Texture2D grateFront = GetGrateFrontTexture();
    if (grateFront == null || !grateFront.isReadable)
      return;

    DungeonMap.GetForwardOffset(
        previewFacing,
        out int forwardX,
        out int forwardY);

    int wallTileX = previewX + forwardX;
    int wallTileY = previewY + forwardY;
    if (!previewMiniMap.IsInside(wallTileX, wallTileY)
        || previewMiniMap.GetTile(wallTileX, wallTileY).Type
            != DungeonTileType.Wall)
    {
      return;
    }

    string viewedWallSide = FacingName(previewFacing);

    for (int i = 0; i < previewWallOrnaments.Length; i++)
    {
      WallOrnamentPlacement ornament = previewWallOrnaments[i];
      if (ornament != null
          && !IsPreviewFeatureEnabled(
              MakePreviewFeatureKey("Ornament", ornament.x, ornament.y, ornament.wall)))
        continue;
      if (!IsGrateOrnament(ornament))
        continue;

      bool placementMatches;
      if (ornament.wallTilePlacement)
      {
        string visiblePhysicalWallFace = OppositeFacingName(previewFacing);
        placementMatches =
            ornament.x == wallTileX
            && ornament.y == wallTileY
            && string.Equals(
                ornament.wall,
                visiblePhysicalWallFace,
                System.StringComparison.OrdinalIgnoreCase);
      }
      else
      {
        placementMatches =
            ornament.x == previewX
            && ornament.y == previewY
            && string.Equals(
                ornament.wall,
                viewedWallSide,
                System.StringComparison.OrdinalIgnoreCase);
      }

      if (!placementMatches)
        continue;

      BlitOrnamentPieceIntoPreview(
            pixels, grateFront, ornament,
            GrateD1FrontX, GrateD1FrontY, false);
      return;
    }
  }

  private bool GetPreviewFeatureMirrorValue(
      WallOrnamentPlacement ornament,
      bool defaultMirror)
  {
    if (ornament == null)
      return defaultMirror;

    string key = MakePreviewFeatureKey(
        "Ornament", ornament.x, ornament.y, ornament.wall);
    return previewFeatureMirrorOverrides.TryGetValue(key, out bool value)
        ? value
        : defaultMirror;
  }

  private void BlitOrnamentPieceIntoPreview(
      Color32[] pixels,
      Texture2D texture,
      WallOrnamentPlacement ornament,
      int defaultX,
      int defaultY,
      bool defaultMirror)
  {
    if (ornament == null || IsHookHiddenAtStairsS2Reference(ornament))
      return;

    string key = MakePreviewFeatureKey(
        "Ornament", ornament.x, ornament.y, ornament.wall);
    bool hasGenericProjection =
        TryGetWallOrnamentProjectionOverrideDescriptor(
            ornament,
            out string projectionKey,
            out _);
    if (hasGenericProjection)
      key = projectionKey;

    int x = defaultX;
    int y = defaultY;
    bool mirror = defaultMirror;
    if (hasGenericProjection)
      ApplyAcceptedOrnamentReference(key, ref x, ref y, ref mirror);
    ApplyPreviewFeatureRenderOverrides(key, ref x, ref y, ref mirror);
    BlitPieceIntoPreview(pixels, texture, x, y, mirror);
  }

  private static bool IsGrateOrnament(WallOrnamentPlacement ornament)
  {
    if (ornament == null)
      return false;

    if (string.Equals(
            ornament.type,
            "Grate",
            System.StringComparison.OrdinalIgnoreCase))
    {
      return true;
    }

    // Hall of Champions local ordinal 3 -> global source ID 34 = Grate.
    return ResolveHallOfChampionsWallOrnamentSourceId(ornament) == 34;
  }

  private Texture2D GetGrateFrontTexture()
  {
    if (cachedGrateFrontTexture != null)
      return cachedGrateFrontTexture;

    Texture2D texture =
        AssetDatabase.LoadAssetAtPath<Texture2D>(GrateFrontAssetPath);
    if (texture != null && texture.width == 32 && texture.height == 28)
    {
      cachedGrateFrontTexture = texture;
      return texture;
    }

    string[] guids = AssetDatabase.FindAssets(
        "Grate t:Texture2D",
        new[] { OrnamentArtFolder });
    for (int i = 0; i < guids.Length; i++)
    {
      string path = AssetDatabase.GUIDToAssetPath(guids[i]);
      Texture2D candidate = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
      if (candidate == null || candidate.width != 32 || candidate.height != 28)
        continue;

      if (path.IndexOf(
              "grate",
              System.StringComparison.OrdinalIgnoreCase) < 0
          || path.IndexOf(
              "front",
              System.StringComparison.OrdinalIgnoreCase) < 0)
      {
        continue;
      }

      cachedGrateFrontTexture = candidate;
      return candidate;
    }

    return texture;
  }

  private static string FacingName(DungeonFacing facing)
  {
    return facing switch
    {
      DungeonFacing.North => "North",
      DungeonFacing.East => "East",
      DungeonFacing.South => "South",
      DungeonFacing.West => "West",
      _ => string.Empty
    };
  }

  private static string OppositeFacingName(DungeonFacing facing)
  {
    return facing switch
    {
      DungeonFacing.North => "South",
      DungeonFacing.East => "West",
      DungeonFacing.South => "North",
      DungeonFacing.West => "East",
      _ => string.Empty
    };
  }

  private static void BlitPieceIntoPreview(
      Color32[] dest,
      Texture2D source,
      int destinationX,
      int destinationY,
      bool mirrorHorizontally = false)
  {
    if (!source.isReadable)
      return;

    Color32[] sourcePixels = source.GetPixels32();

    for (int sourceY = 0; sourceY < source.height; sourceY++)
    {
      int targetY = destinationY + sourceY;
      if (targetY < 0 || targetY >= PreviewHeight)
        continue;

      for (int column = 0; column < source.width; column++)
      {
        int sourceX = mirrorHorizontally
            ? source.width - 1 - column
            : column;
        int targetX = destinationX + column;

        // Dungeon/map graphics are clipped to the original 224-pixel viewport.
        // Right-side walls may extend geometrically past X=223, but they must
        // never paint into the HUD / magenta border at X>=224.
        if (targetX < 0 || targetX >= DungeonViewportWidth)
          continue;

        Color32 sourceColour =
            sourcePixels[sourceY * source.width + sourceX];
        if (sourceColour.a == 0)
          continue;

        dest[targetY * PreviewWidth + targetX] = sourceColour;
      }
    }
  }

  private static void BlitPieceScaledIntoPreview(
      Color32[] dest,
      Texture2D source,
      int destinationX,
      int destinationY,
      int destWidth,
      int destHeight,
      bool mirrorHorizontally = false,
      bool skipCyanTransparencyKey = false,
      byte[] colorMap = null)
  {
    if (source == null)
      return;

    BlitPieceScaledIntoPreview(
        dest,
        source,
        destinationX,
        destinationY,
        destWidth,
        destHeight,
        mirrorHorizontally,
        0,
        0,
        source.width,
        source.height,
        skipCyanTransparencyKey,
        colorMap);
  }

  private static void BlitPieceScaledIntoPreview(
      Color32[] dest,
      Texture2D source,
      int destinationX,
      int destinationY,
      int destWidth,
      int destHeight,
      bool mirrorHorizontally,
      int sourceX,
      int sourceY,
      int sourceWidth,
      int sourceHeight,
      bool skipCyanTransparencyKey = false,
      byte[] colorMap = null)
  {
    if (!source.isReadable
        || destWidth <= 0
        || destHeight <= 0
        || sourceWidth <= 0
        || sourceHeight <= 0)
    {
      return;
    }

    Color32[] sourcePixels = source.GetPixels32();

    for (int destRow = 0; destRow < destHeight; destRow++)
    {
      int targetY = destinationY + destRow;
      if (targetY < 0 || targetY >= PreviewHeight)
        continue;

      int sampleY = sourceY + destRow * sourceHeight / destHeight;
      if (sampleY < 0 || sampleY >= source.height)
        continue;

      for (int destCol = 0; destCol < destWidth; destCol++)
      {
        int offsetX = destCol * sourceWidth / destWidth;
        int sampleX = mirrorHorizontally
            ? sourceX + sourceWidth - 1 - offsetX
            : sourceX + offsetX;
        if (sampleX < 0 || sampleX >= source.width)
          continue;

        int targetX = destinationX + destCol;

        // Scaled dungeon/map graphics obey the same hard X=224 viewport clip.
        if (targetX < 0 || targetX >= DungeonViewportWidth)
          continue;

        Color32 sourceColour =
            sourcePixels[sampleY * source.width + sampleX];
        if (sourceColour.a == 0)
          continue;

        // Some original Dungeon Master item artwork uses pure cyan as its
        // transparency key instead of alpha. Keep this opt-in so wall and
        // ornament scaling is unchanged; generated floor-item depths can
        // discard the key colour before writing into the framebuffer.
        if (skipCyanTransparencyKey
            && sourceColour.r == 0
            && sourceColour.g == 255
            && sourceColour.b == 255)
        {
          continue;
        }

        // Optional Dungeon Master distance-palette remap. The F2 apple uses
        // the recovered Medium map, which turns the bright source red into
        // the darker brown/orange seen in the original DOS F2 view.
        if (colorMap != null && colorMap.Length >= 16)
        {
          Color32[] brightPalette = DungeonViewportLightPalettes[0];
          int sourcePaletteIndex =
              FindExactDmPaletteIndexOrNearest(sourceColour, brightPalette);
          int mappedPaletteIndex =
              Mathf.Clamp(colorMap[sourcePaletteIndex], 0, 15);
          sourceColour = brightPalette[mappedPaletteIndex];
        }

        dest[targetY * PreviewWidth + targetX] = sourceColour;
      }
    }
  }

  private void StealViewportTextureIfNeeded(RawImage dungeonImage)
  {
    if (viewportTextureStolen)
      return;

    savedViewportTexture = dungeonImage.texture;
    viewportTextureStolen = true;
  }

  private void RestoreViewportTextureAndDestroyPreview()
  {
    RestoreEditModePresentationOverrides();

    if (TryGetViewportRawImage(out RawImage dungeonImage)
        && viewportTextureStolen)
    {
      dungeonImage.texture = savedViewportTexture;
    }

    savedViewportTexture = null;
    viewportTextureStolen = false;
    cachedViewportImage = null;

    if (editModePreviewTexture != null)
    {
      Object.DestroyImmediate(editModePreviewTexture);
      editModePreviewTexture = null;
    }
  }

  private static void RefreshDungeonRenderer()
  {
    if (!Application.isPlaying)
      return;

    DungeonRenderer renderer =
        Object.FindAnyObjectByType<DungeonRenderer>();

    if (renderer == null)
      return;

    renderer.RequestRedraw();
  }

  private static int DrawDelayedIntFieldMaybeRed(
      string label,
      int value,
      bool valueDiffersFromRef,
      bool immediate = false,
      float fieldWidth = 36f)
  {
    Color previousGuiColor = GUI.color;
    Color previousContentColor = GUI.contentColor;
    GUIStyle fieldStyle = EditorStyles.numberField;
    if (valueDiffersFromRef)
    {
      fieldStyle = new GUIStyle(EditorStyles.numberField);
      Color red = Color.red;
      fieldStyle.normal.textColor = red;
      fieldStyle.hover.textColor = red;
      fieldStyle.focused.textColor = red;
      fieldStyle.active.textColor = red;
    }

    EditorGUILayout.LabelField(label, GUILayout.Width(12f));
    int result = immediate
        ? EditorGUILayout.IntField(value, fieldStyle, GUILayout.Width(fieldWidth))
        : EditorGUILayout.DelayedIntField(
            value, fieldStyle, GUILayout.Width(fieldWidth));
    GUI.color = previousGuiColor;
    GUI.contentColor = previousContentColor;
    return result;
  }

  private static bool DrawIntStepperInline(
      string label,
      ref int value,
      int step,
      bool valueDiffersFromRef = false,
      bool immediate = false,
      float buttonWidth = 36f,
      float fieldWidth = 36f)
  {
    EditorGUI.BeginChangeCheck();
    value = DrawDelayedIntFieldMaybeRed(
        label, value, valueDiffersFromRef, immediate, fieldWidth);

    bool changed = EditorGUI.EndChangeCheck();

    if (GUILayout.Button($"-{step}", GUILayout.Width(buttonWidth)))
    {
      value -= step;
      changed = true;
    }

    if (GUILayout.Button($"+{step}", GUILayout.Width(buttonWidth)))
    {
      value += step;
      changed = true;
    }

    return changed;
  }

  private static bool DrawTopDownYStepperInline(
      ref int unityY,
      int pieceHeight,
      int step,
      bool valueDiffersFromRef = false,
      bool immediate = false)
  {
    int oldUnityY = unityY;
    int displayY = UnityYToDisplayY(unityY, pieceHeight);

    EditorGUI.BeginChangeCheck();
    displayY = DrawDelayedIntFieldMaybeRed(
        "Y", displayY, valueDiffersFromRef, immediate);

    if (GUILayout.Button($"-{step}", GUILayout.Width(36f)))
      displayY -= step;

    if (GUILayout.Button($"+{step}", GUILayout.Width(36f)))
      displayY += step;

    int maxDisplayY = Mathf.Max(0, PreviewHeight - Mathf.Max(1, pieceHeight));
    displayY = Mathf.Clamp(displayY, 0, maxDisplayY);
    unityY = DisplayYToUnityY(displayY, pieceHeight);

    return EditorGUI.EndChangeCheck() || unityY != oldUnityY;
  }

  private static bool DrawIntStepper(
      string label,
      ref int value,
      int step,
      bool valueDiffersFromRef = false)
  {
    EditorGUILayout.BeginHorizontal(GUILayout.ExpandWidth(false));
    EditorGUI.BeginChangeCheck();
    value = DrawDelayedIntFieldMaybeRed(
        label, value, valueDiffersFromRef);

    bool changed = EditorGUI.EndChangeCheck();

    if (GUILayout.Button($"-{step}", GUILayout.Width(36)))
    {
      value -= step;
      changed = true;
    }

    if (GUILayout.Button($"+{step}", GUILayout.Width(36)))
    {
      value += step;
      changed = true;
    }

    EditorGUILayout.EndHorizontal();
    return changed;
  }

  private void RefreshTemporaryNormalWallPreview()
  {
    if (Application.isPlaying)
      return;

    // Enabled/Mirror/X/Y tests are a ViewEdit overlay only. Do NOT rebuild the
    // automatic wall recipe here: after navigation that would switch away from
    // the destination pose's normal navigation state and could change the
    // default walls. Compose reads the temporary override dictionaries directly.
    ResetEditModeViewportLogCache();
    DestroyEditModePreviewTextureOnly();
    RefreshEditModePreview();
    RepaintGameViews();
    Repaint();
  }

  /// <summary>
  /// Temporary normal-wall Y editor. The value is Unity bottom-origin, while
  /// ViewEdit displays GIMP/top-origin Y. No layout field is mutated.
  /// </summary>
  private static bool DrawTopDownYStepper(
      ref int unityY,
      int pieceHeight,
      int step,
      bool valueDiffersFromRef = false)
  {
    int oldUnityY = unityY;
    int displayY = UnityYToDisplayY(unityY, pieceHeight);

    EditorGUI.BeginChangeCheck();
    EditorGUILayout.BeginHorizontal(GUILayout.ExpandWidth(false));
    displayY = DrawDelayedIntFieldMaybeRed(
        "Y", displayY, valueDiffersFromRef);

    if (GUILayout.Button($"-{step}", GUILayout.Width(36)))
      displayY -= step;

    if (GUILayout.Button($"+{step}", GUILayout.Width(36)))
      displayY += step;

    EditorGUILayout.EndHorizontal();

    int maxDisplayY = Mathf.Max(0, PreviewHeight - Mathf.Max(1, pieceHeight));
    displayY = Mathf.Clamp(displayY, 0, maxDisplayY);
    unityY = DisplayYToUnityY(displayY, pieceHeight);

    return EditorGUI.EndChangeCheck() || unityY != oldUnityY;
  }

  /// <summary>
  /// Editor-only Y: show/edit top-down (GIMP) coords. Storage stays Unity
  /// bottom-up framebuffer Y used by blit. displayY = 200 - unityY - h.
  /// </summary>
  private bool DrawTopDownYStepper(ViewportPiece piece, int step)
  {
    if (piece == null)
      return false;

    int pieceHeight = GetPieceHeightForEditorY(piece);
    int oldUnityY = piece.Y;
    int displayY = UnityYToDisplayY(oldUnityY, pieceHeight);

    EditorGUI.BeginChangeCheck();
    EditorGUILayout.BeginHorizontal();
    displayY = EditorGUILayout.IntField("Y", displayY);

    if (GUILayout.Button($"-{step}", GUILayout.Width(36)))
      displayY -= step;

    if (GUILayout.Button($"+{step}", GUILayout.Width(36)))
      displayY += step;

    EditorGUILayout.EndHorizontal();

    int maxDisplayY = Mathf.Max(0, PreviewHeight - pieceHeight);
    displayY = Mathf.Clamp(displayY, 0, maxDisplayY);
    piece.Y = DisplayYToUnityY(displayY, pieceHeight);

    return EditorGUI.EndChangeCheck() || piece.Y != oldUnityY;
  }

  private int GetPieceHeightForEditorY(ViewportPiece piece)
  {
    if (piece == null || graphics == null)
      return 1;

    if (piece.Name == "BlackDoorF3")
    {
      Texture2D f3Texture = GetBlackDoorF3SourceTexture();
      if (f3Texture != null && f3Texture.height > 0)
        return f3Texture.height;
    }

    if (IsFrontWallF1Card(piece))
    {
      Texture2D f1Texture = GetReadableNativeFrontF1Texture();
      if (f1Texture != null && f1Texture.height > 0)
        return f1Texture.height;
    }

    if (IsFrontWallF2Card(piece))
    {
      Texture2D f2Texture = GetReadableNativeFrontF2Texture();
      if (f2Texture != null && f2Texture.height > 0)
        return f2Texture.height;
      return 74;
    }

    if (IsFrontWallF3Card(piece))
    {
      Texture2D f3Texture = GetReadableNativeFrontF3Texture();
      if (f3Texture != null && f3Texture.height > 0)
        return f3Texture.height;
      return 49;
    }

    if (piece.Name == "RightS3")
    {
      Texture2D rightS3Texture = GetRight2STexture();
      if (rightS3Texture != null && rightS3Texture.height > 0)
        return rightS3Texture.height;
    }

    Texture2D texture = graphics.GetTexture(piece.Graphic);
    if (texture == null || texture.height <= 0)
      return 1;

    return texture.height;
  }

  private static int UnityYToDisplayY(int storedUnityY, int pieceHeight)
  {
    int height = Mathf.Max(1, pieceHeight);
    return PreviewHeight - storedUnityY - height;
  }

  private static int DisplayYToUnityY(int displayY, int pieceHeight)
  {
    int height = Mathf.Max(1, pieceHeight);
    return PreviewHeight - displayY - height;
  }
}
